  modal('Notifications', `<div class="panel">${list}</div>`, { actions: [{ label: 'Open alerts', fn: c => { c(); go('alerts'); } }, { label: 'Mark all read', cls: 'pri', fn: c => { S.notifs.forEach(n => n.read = true); save(); updateBell(); c(); } }] });
