      const g = e.target.closest('[data-go]'); if (g) { e.preventDefault(); go(g.dataset.go, g.dataset.p); return; }
      const q = e.target.closest('[data-qa]'); if (q) { e.preventDefault(); quickAction(q.dataset.qa, q.dataset.id, q); return; }
      const n = e.target.closest('[data-note]'); if (n) { go('notes', n.dataset.note); return; }
