/* =====================================================================
   Superfinancials — pages: market intelligence & personal workspace
   ===================================================================== */
const PAGES = {};

/* ---------- shared quote table ---------- */
function qcols(per, opt = {}) {
  const cols = [{ k: 'tk', h: opt.nameH || 'Instrument', v: r => r.o.tk, f: r => `${lnk(r.o.id)}${opt.badge ? ` <span class="badge">${esc(r.o.cls)}</span>` : ''}<div class="sub">${esc(opt.country && r.o.country ? (COUNTRY[r.o.country]?.n || r.o.country) + ' · ' + r.o.name : r.o.short || r.o.name)}</div>` }];
  if (opt.unit) cols.push({ k: 'unit', h: 'Unit', v: r => unitOf(r.o), f: r => `<span class="sub">${esc(unitOf(r.o))}</span>` });
  cols.push({ k: 'last', h: 'Last', a: 'r', v: r => r.q.last, f: r => fv(r.o, r.q.last) },
    { k: 'chg', h: 'Chg', a: 'r', v: r => r.o.type === 'yield' ? r.q.bp : r.q.chg, f: r => `<span class="${cls(r.q.chg)}">${fchg(r.o, r.q)}</span>` },
    { k: 'pct', h: '%Chg', a: 'r', v: r => r.q.pct, f: r => r.q.pct == null ? '<span class="muted">n/a</span>' : `<span class="${cls(r.q.pct)}">${pc(r.q.pct)}</span>` });
  if (per && per !== '1D') cols.push({ k: 'per', h: per, a: 'r', v: r => perf(r.o.id, per), f: r => { const v = perf(r.o.id, per); return `<span class="${cls(v)}">${fper(r.o, v)}</span>`; } });
  (opt.extra || []).forEach(c => cols.push(c));
  if (opt.spark) cols.push({ k: 'sp', h: '1M', f: r => spark(lastN(r.o.id, 22)) });
  if (!opt.noDate) cols.push({ k: 'asof', h: 'As of', v: r => r.q.date, f: r => `<span class="sub">${fds(r.q.date)}</span>` });
  return cols;
}
function qtable(el, ids, per, opt = {}) { return table(el, { cols: qcols(per, opt), rows: rowsOf(ids), dense: true, search: opt.search, csv: opt.csv, page: opt.page, sort: opt.sort, empty: opt.empty }); }

/* ---------- dashboard panels ---------- */
function sectorHeat(el, per) {
  const spx = perf('IX.SPX', per); const rows = SECTORS.map(o => ({ o, v: perf(o.id, per) })).sort((a, b) => b.v - a.v); const sc = Math.max(...rows.map(r => Math.abs(r.v)), .5);
  el.innerHTML = `<div class="heat">${rows.map(r => `<a class="hc" data-sec="${r.o.id}" href="#sec.${r.o.id}" style="${heatBg(r.v, sc)}" title="${esc(r.o.name)} (${r.o.tk}) — investable ETF proxy"><span class="n">${esc(r.o.sector)}</span><span class="v">${pc(r.v)}</span><span class="rel">${r.o.tk} · ${sgn(r.v - spx, 2)} vs SPX</span></a>`).join('')}</div><div class="note" style="margin-top:8px">S&amp;P 500 ${per}: <b class="${cls(spx)}">${pc(spx)}</b>. SPDR sector ETFs as proxies; “vs SPX” is the difference in percentage points.</div>`;
}
function factorMatrix(el, per) {
  const g = (s, st) => STYLE.find(o => o.size === s && o.style === st); const cells = []; for (const s of ['Large', 'Mid', 'Small']) for (const st of ['Value', 'Core', 'Growth']) cells.push(g(s, st) ? perf(g(s, st).id, per) : null); /* Next.js port: style ETF hidden without real data */ const sc = Math.max(...cells.map(Math.abs), .5);
  el.innerHTML = `<div class="tw"><table class="mx"><thead><tr><th></th><th>Value</th><th>Core</th><th>Growth</th></tr></thead><tbody>${['Large', 'Mid', 'Small'].map(s => `<tr><th class="rh">${s}</th>${['Value', 'Core', 'Growth'].map(st => { const o = g(s, st); if (!o) return '<td class="sub" title="No real data for this style ETF">—</td>'; const v = perf(o.id, per); return `<td data-sec="${o.id}" style="${heatBg(v, sc)}" title="${esc(o.name)} — investable proxy, not a pure factor">${pc(v)}<small>${o.tk}</small></td>`; }).join('')}</tr>`).join('')}</tbody></table></div><div class="note">${per} price return. Each cell is an iShares Russell style ETF used as an <b>investable proxy</b>; ETFs approximate, and do not perfectly represent, size and style factors.</div>`;
}
function yieldGrid(el, ccs) {
  const cell = (cc, m) => { const o = BY[`YD.${cc}${m}`]; if (!o) return '<td class="r muted">—</td>'; const q = quote(o.id); return `<td class="r"><a class="tk" data-sec="${o.id}" href="#sec.${o.id}" style="color:var(--fg)">${nf(q.last, 3)}</a><div class="${cls(q.bp)}" style="font-size:11px">${bpf(q.bp)}</div></td>`; };
  el.innerHTML = `<div class="tw"><table class="t dense"><thead><tr><th>Country</th>${MATS.map(m => `<th class="r">${m}Y %</th>`).join('')}<th class="r" title="10-year minus 2-year yield, basis points">2s10s</th></tr></thead><tbody>${ccs.map(cc => { const y2 = BY[`YD.${cc}2`], y10 = BY[`YD.${cc}10`]; const sp = y2 && y10 ? (quote(y10.id).last - quote(y2.id).last) * 100 : null; return `<tr><td>${esc(COUNTRY[cc].n)}</td>${MATS.map(m => cell(cc, m)).join('')}<td class="r ${cls(sp)}">${sp == null ? '—' : sgn(sp, 0) + ' bp'}</td></tr>`; }).join('')}</tbody></table></div>`;
}
function normPanel(el, per) {
  const rg = per === '1D' ? '1M' : per; const ids = S.prefs.normIds || ['IX.SPX', 'IX.NDX', 'IX.RUT', 'IX.SX5E', 'IX.NKY'];
  el.innerHTML = `<div class="row" style="justify-content:space-between;margin-bottom:6px">${seg('nrange', ['5D', '1M', '3M', 'YTD', '1Y', '3Y', '5Y'], rg)}${seg('nccy', [['local', 'Local'], ['USD', 'USD']], S.prefs.normCcy || 'local')}</div><div class="nc"></div><div class="note nn" style="margin-top:4px"></div>`;
  let range = rg, ccy = S.prefs.normCcy || 'local'; let ch = null;
  const draw = () => { const { cfg, al } = buildCompare(ids, { range, ccy, h: 220 }); if (ch) ch.set(cfg); else ch = new TChart($('.nc', el), cfg); $('.nn', el).innerHTML = compareNotes(ids, al, 'norm', ccy) + `<div><a class="tk" data-p="" data-open-graph>Open in chart workspace →</a></div>`; };
  onSeg(el, 'nrange', v => { range = v; draw(); }); onSeg(el, 'nccy', v => { ccy = v; S.prefs.normCcy = v; save(); draw(); });
  el.addEventListener('click', e => { if (e.target.closest('[data-open-graph]')) openGraph({ ids, range, mode: 'norm', ccy }); });
  draw();
}
function wlPanel(el) {
  const wl = S.watchlists.find(w => w.id === S.activeWL) || S.watchlists[0]; if (!wl) { el.innerHTML = '<div class="empty"><b>No watchlists</b><button class="btn sm" data-go="watchlists">Create one</button></div>'; return; }
  el.innerHTML = `<div class="row" style="margin-bottom:6px"><select class="inp sm" aria-label="Watchlist">${S.watchlists.map(w => `<option value="${w.id}" ${w.id === wl.id ? 'selected' : ''}>${esc(w.name)}</option>`).join('')}</select></div><div class="wt"></div>`;
  $('select', el).onchange = e => { S.activeWL = e.target.value; save(); wlPanel(el); renderRP(); };
  qtable($('.wt', el), wl.items, '1M', { spark: true, badge: true, empty: '<b>This watchlist is empty</b>Add instruments from any security page or My Watchlists.' });
}
const PANELS = {
  useq: { t: 'U.S. Equity Markets', r: 'equity', c: 'c6', f: (b, per) => qtable(b, US_IDX.map(o => o.id), per, { spark: true }) },
  sectors: { t: 'U.S. Equity Sectors', r: 'equity', c: 'c6', f: (b, per) => sectorHeat(b, per) },
  norm: { t: 'Normalized Performance', r: 'graphs', c: 'c8', f: (b, per) => normPanel(b, per) },
  news: { t: 'Market News', r: 'news', c: 'c4', f: b => newsList(b, { limit: 7, compact: true }) },
  global: { t: 'Global Markets', r: 'global', c: 'c6', f: (b, per) => qtable(b, GLOBAL_IDX.filter(o => o.country !== 'US').map(o => o.id), per, { country: true, page: 10 }) },
  fx: { t: 'Currencies', r: 'fx', c: 'c6', f: (b, per) => qtable(b, ['FX.DXY', 'FX.EURUSD', 'FX.GBPUSD', 'FX.USDJPY', 'FX.USDCHF', 'FX.AUDUSD', 'FX.USDCAD', 'FX.USDCNH', 'CR.BTCUSD'], per, { badge: true }) },
  yields: { t: 'Global Government Bond Yields', r: 'yields', c: 'c6', f: b => yieldGrid(b, ['US', 'UK', 'DE', 'FR', 'IT', 'JP', 'CA', 'AU']) },
  fi: { t: 'Fixed Income', r: 'fixed', c: 'c6', f: (b, per) => qtable(b, ['ET.SHY', 'ET.IEF', 'ET.TLT', 'ET.TIP', 'ET.LQD', 'ET.HYG', 'ET.AGG', 'ET.MUB'], per, { extra: [{ k: 'dur', h: 'Dur.', a: 'r', title: 'Effective duration, years', v: r => r.o.dur, f: r => nf(r.o.dur, 1) }, { k: 'dy', h: 'Dist. yld', a: 'r', title: 'Distribution yield (fund) — not a bond yield', v: r => r.o.dist, f: r => nf(r.o.dist, 2) + '%' }], noDate: true }) },
  factors: { t: 'U.S. Equity Factors', r: 'equity', c: 'c6', f: (b, per) => factorMatrix(b, per) },
  cmd: { t: 'Commodities', r: 'cmd', c: 'c6', f: (b, per) => qtable(b, ['CM.GC1', 'CM.SI1', 'CM.CL1', 'CM.CO1', 'CM.NG1', 'CM.HG1', 'CM.ZC1', 'CM.BCOM'], per, { unit: true, noDate: true }) },
  wl: { t: 'Watchlist', r: 'watchlists', c: 'c12', f: b => wlPanel(b) }
};
function renderPanels(grid, keys, per) {
  grid.innerHTML = keys.filter(k => PANELS[k]).map(k => { const P = PANELS[k]; return `<section class="panel ${P.c}" data-panel="${k}"><header class="ph"><a class="pt" data-go="${P.r}" href="#${P.r}" title="Open ${esc(ROUTES[P.r].t)}">${esc(P.t)}</a><span class="pm">${simB()}<button class="btn sm ghost" data-expand aria-label="Expand panel">⤢</button></span></header><div class="pb"></div></section>`; }).join('');
  $$('[data-panel]', grid).forEach(sec => { try { PANELS[sec.dataset.panel].f($('.pb', sec), per); } catch (e) { console.error(e); $('.pb', sec).innerHTML = `<div class="callout">Panel failed to load: ${esc(e.message)}</div>`; } });
  on(grid, 'click', '[data-expand]', (e, b) => { const s = b.closest('.panel'); s.classList.toggle('wide'); b.textContent = s.classList.contains('wide') ? '⤡' : '⤢'; CHARTS.forEach(c => c.render()); });
}

/* ---------- market brief generator (descriptive, from simulated data; no causal claims) ---------- */
let NEWS = null;
function newsFeed() {
  if (NEWS) return NEWS; const out = []; const d = series('IX.SPX').d; const days = d.slice(-12).reverse();
  const ch = (id, t) => { const s = series(id); const i = bsLE(s.d, t); if (i < 1) return null; return BY[id].type === 'yield' ? (s.c[i] - s.c[i - 1]) * 100 : (s.c[i] / s.c[i - 1] - 1) * 100; };
  const pub = 'Superfinancials Briefs (auto-generated)';
  for (const t of days) {
    const ts = t + 21.5 * 3600e3; const spx = ch('IX.SPX', t), ndx = ch('IX.NDX', t), rut = ch('IX.RUT', t), vix = valAt('IX.VIX', t);
    out.push({ id: 'w' + t, t: ts, topic: 'Markets', ids: ['IX.SPX', 'IX.NDX', 'IX.RUT', 'IX.VIX'], title: `S&P 500 ${spx >= 0 ? 'gains' : 'slips'} ${pc(Math.abs(spx)).replace('+', '')} to ${nf(valAt('IX.SPX', t))}; Nasdaq 100 ${pc(ndx)}, Russell 2000 ${pc(rut)}`, body: `VIX closed at ${nf(vix)}. Session summary built from simulated end-of-day values.` });
    const sec = SECTORS.map(o => ({ o, v: ch(o.id, t) })).sort((a, b) => b.v - a.v);
    if (sec.length) out.push({ id: 's' + t, t: ts - 60e3, topic: 'Sectors', ids: [sec[0].o.id, sec[sec.length - 1].o.id], title: `${sec[0].o.sector} leads U.S. sectors (${pc(sec[0].v)}); ${sec[sec.length - 1].o.sector} trails (${pc(sec[sec.length - 1].v)})`, body: `Spread between best and worst sector ETF: ${nf(sec[0].v - sec[sec.length - 1].v)} percentage points.` });
    const eq = EQ.map(o => ({ o, v: ch(o.id, t) })).filter(x => x.v != null).sort((a, b) => b.v - a.v);
    if (eq.length) out.push({ id: 'm' + t, t: ts - 120e3, topic: 'Movers', ids: [eq[0].o.id, eq[eq.length - 1].o.id], title: `${eq[0].o.name} (${eq[0].o.tk}) ${pc(eq[0].v)} tops the large-cap tracker; ${eq[eq.length - 1].o.tk} ${pc(eq[eq.length - 1].v)} is the weakest`, body: `Largest one-day moves among ${eq.length} tracked U.S. large caps. The brief reports price changes only and does not attribute a cause.` });
    const y10 = ch('YD.US10', t), y2 = ch('YD.US2', t); const sp = (valAt('YD.US10', t) - valAt('YD.US2', t)) * 100;
    out.push({ id: 'r' + t, t: ts - 180e3, topic: 'Rates', ids: ['YD.US10', 'YD.US2', 'YD.DE10'], title: `U.S. 10-year yield ${bpf(y10)} to ${nf(valAt('YD.US10', t), 3)}%; 2-year ${bpf(y2)}`, body: `2s10s spread at ${sgn(sp, 0)} bp. Bund 10Y ${bpf(ch('YD.DE10', t))}.` });
    out.push({ id: 'f' + t, t: ts - 240e3, topic: 'FX', ids: ['FX.DXY', 'FX.EURUSD', 'FX.USDJPY'], title: `Dollar index ${pc(ch('FX.DXY', t))}; EUR/USD at ${nf(valAt('FX.EURUSD', t), 4)}, USD/JPY ${nf(valAt('FX.USDJPY', t), 2)}`, body: `G10 summary from simulated closes.` });
    out.push({ id: 'c' + t, t: ts - 300e3, topic: 'Commodities', ids: ['CM.CO1', 'CM.CL1', 'CM.GC1'], title: `Brent ${pc(ch('CM.CO1', t))} to $${nf(valAt('CM.CO1', t))}/bbl; gold ${pc(ch('CM.GC1', t))} at $${nf(valAt('CM.GC1', t))}/oz`, body: `Front-month continuous futures. WTI ${pc(ch('CM.CL1', t))}.` });
  }
  const up = EQ.map(o => ({ o, f: fund(o.id) })).filter(x => x.f.nextEarn - END < 10 * DAY).sort((a, b) => a.f.nextEarn - b.f.nextEarn).slice(0, 6);
  if (up.length) out.push({ id: 'cal', t: days[0] + 22 * 3600e3, topic: 'Calendar', ids: up.map(x => x.o.id), title: `Earnings ahead (simulated schedule): ${up.map(x => x.o.tk).join(', ')}`, body: `Next reporting dates over the coming two weeks in the simulated calendar.` });
  return NEWS = out.sort((a, b) => b.t - a.t);
}
function newsList(el, { limit = 50, topic = 'All', ticker = null, q = '', compact = false } = {}) {
  let items = newsFeed(); if (topic !== 'All') items = items.filter(n => n.topic === topic); if (ticker) items = items.filter(n => n.ids.includes(ticker)); if (q) { const qq = q.toLowerCase(); items = items.filter(n => (n.title + n.body).toLowerCase().includes(qq)); }
  items = items.slice(0, limit);
  el.classList.add('flush');
  el.innerHTML = items.length ? items.map(n => `<article class="news-i"><div class="m"><span class="badge">${esc(n.topic)}</span><span>Sim EOD ${fd(n.t)}</span>${compact ? '' : `<span>Superfinancials Briefs · auto-generated</span>`}</div><h4>${esc(n.title)}</h4>${compact ? '' : `<div class="note">${esc(n.body)}</div>`}<div class="row" style="gap:6px">${n.ids.map(id => lnk(id)).join(' ')}</div></article>`).join('') : '<div class="empty"><b>No headlines match</b>Try another topic or clear the ticker filter.</div>';
}

/* ---------- Home / Market Overview ---------- */
PAGES.overview = pg => {
  const dash = S.dashboards.find(d => d.id === S.prefs.activeDash) || S.dashboards[0]; const per = S.prefs.dashPeriod || '1D';
  pg.innerHTML = hdr('overview', `Global markets on one screen. ${eodTxt()} Click a panel title for the full workspace.`, `<select class="inp sm" id="dsel" aria-label="Dashboard">${S.dashboards.map(d => `<option value="${d.id}" ${d.id === dash.id ? 'selected' : ''}>${esc(d.name)}</option>`).join('')}</select>${seg('period', ['1D', '5D', '1M', 'YTD', '1Y'], per)}<button class="btn sm" id="cust">Customize</button><button class="btn sm" id="saveas">Save layout as…</button>`) + '<div class="grid" id="pgrid"></div>';
  renderPanels($('#pgrid', pg), dash.panels.filter(k => !dash.hidden.includes(k)), per);
  onSeg(pg, 'period', v => { S.prefs.dashPeriod = v; save(); render(); });
  $('#dsel', pg).onchange = e => { S.prefs.activeDash = e.target.value; save(); render(); };
  $('#cust', pg).onclick = () => customizeDash(dash);
  $('#saveas', pg).onclick = () => saveDashAs(dash);
};
function customizeDash(dash) {
  const order = dash.panels.slice(); const hidden = new Set(dash.hidden);
  const body = document.createElement('div'); const draw = () => { body.innerHTML = `<p class="note" style="margin:0">Show, hide and reorder panels on “${esc(dash.name)}”.</p><div class="panel">${order.map((k, i) => `<div class="wlr" style="grid-template-columns:auto minmax(0,1fr) auto;align-items:center"><input type="checkbox" id="pc_${k}" data-k="${k}" ${hidden.has(k) ? '' : 'checked'}><label for="pc_${k}">${esc(PANELS[k].t)}</label><span class="row" style="gap:4px"><button class="btn sm" data-up="${i}" ${i ? '' : 'disabled'} aria-label="Move up">↑</button><button class="btn sm" data-dn="${i}" ${i < order.length - 1 ? '' : 'disabled'} aria-label="Move down">↓</button></span></div>`).join('')}</div>`; };
  draw();
  body.addEventListener('click', e => { const u = e.target.closest('[data-up]'), d = e.target.closest('[data-dn]'); if (u) { const i = +u.dataset.up; [order[i - 1], order[i]] = [order[i], order[i - 1]]; draw(); } if (d) { const i = +d.dataset.dn; [order[i + 1], order[i]] = [order[i], order[i + 1]]; draw(); } });
  body.addEventListener('change', e => { const k = e.target.dataset.k; if (k) e.target.checked ? hidden.delete(k) : hidden.add(k); });
  modal('Customize dashboard', body, { actions: [{ label: 'Cancel', fn: c => c() }, { label: 'Apply', cls: 'pri', fn: c => { dash.panels = order; dash.hidden = Array.from(hidden); save(); c(); render(); toast('Dashboard layout saved'); } }] });
}
function saveDashAs(dash) { modal('Save dashboard layout', `<label class="f"><span>Name</span><input class="inp" id="dn" value="${esc(dash.name)} copy" maxlength="60"></label>`, { actions: [{ label: 'Cancel', fn: c => c() }, { label: 'Save', cls: 'pri', fn: (c, mb) => { const d = { id: uid(), name: $('#dn', mb).value.trim() || 'Untitled dashboard', panels: dash.panels.slice(), hidden: dash.hidden.slice(), period: S.prefs.dashPeriod }; S.dashboards.push(d); S.prefs.activeDash = d.id; save(); c(); render(); toast('Dashboard saved'); } }] }); }

/* ---------- Market News ---------- */
PAGES.news = pg => {
  const st = { topic: 'All', ticker: null, q: '' };
  pg.innerHTML = hdr('news', 'Auto-generated briefs that describe moves in the simulated data. They report what changed, never why; no external publishers are connected in this build.', '') +
    `<section class="panel"><div class="tbar"><div class="row" id="tops">${['All', 'Markets', 'Sectors', 'Movers', 'Rates', 'FX', 'Commodities', 'Calendar'].map(t => `<button class="chip ${t === 'All' ? 'on' : ''}" data-t="${t}">${t}</button>`).join('')}</div><div class="row" style="margin-left:auto;gap:6px"><input class="inp sm" id="nq" type="search" placeholder="Search headlines" aria-label="Search headlines">${secSearch('Filter by ticker…')}<span id="tkf"></span></div></div><div class="pb" id="nl"></div><div class="pf"><span>Publisher: Superfinancials Briefs (auto-generated from simulated EOD data)</span><span>Original-article links appear when a licensed news provider is connected in Data Sources.</span></div></section>`;
  const draw = () => { newsList($('#nl', pg), st); $('#tkf', pg).innerHTML = st.ticker ? `<span class="chip on">${esc(BY[st.ticker].tk)} <span class="x" data-clr aria-label="Clear">×</span></span>` : ''; };
  on(pg, 'click', '[data-t]', (e, b) => { st.topic = b.dataset.t; $$('#tops .chip', pg).forEach(x => x.classList.toggle('on', x === b)); draw(); });
  on(pg, 'click', '[data-clr]', () => { st.ticker = null; draw(); });
  $('#nq', pg).oninput = e => { st.q = e.target.value; draw(); };
  wireSecSearch(pg, id => { st.ticker = id; draw(); });
  draw();
};

/* ---------- Market Movers ---------- */
PAGES.movers = pg => {
  let per = '1D', uni = 'eq';
  pg.innerHTML = hdr('movers', 'Largest moves and unusual volume across the tracked universe.', `${seg('per', ['1D', '5D', '1M', 'YTD'], per)}${seg('uni', [['eq', 'U.S. large caps'], ['etf', 'ETFs'], ['all', 'All assets']], uni)}`) + `<div class="grid"><div class="panel c4"><header class="ph"><span class="pt">Top gainers</span></header><div class="pb flush" id="g1"></div></div><div class="panel c4"><header class="ph"><span class="pt">Top decliners</span></header><div class="pb flush" id="g2"></div></div><div class="panel c4"><header class="ph"><span class="pt">Most active vs. 20D avg</span></header><div class="pb flush" id="g3"></div></div></div>`;
  const draw = () => {
    const pool = (uni === 'eq' ? EQ : uni === 'etf' ? U.filter(o => o.type === 'etf') : U.filter(o => !isRate(o) && o.type !== 'bond')).map(o => ({ o, q: quote(o.id), v: perf(o.id, per) })).filter(r => r.v != null);
    const c = [{ k: 'tk', h: 'Instrument', v: r => r.o.tk, f: r => `${lnk(r.o.id)}<div class="sub">${esc(r.o.short || r.o.name)}</div>` }, { k: 'last', h: 'Last', a: 'r', v: r => r.q.last, f: r => fv(r.o, r.q.last) }, { k: 'v', h: per, a: 'r', v: r => r.v, f: r => `<span class="${cls(r.v)}">${pc(r.v)}</span>` }];
    table($('#g1', pg), { cols: c, rows: pool.slice().sort((a, b) => b.v - a.v).slice(0, 12), dense: true });
    table($('#g2', pg), { cols: c, rows: pool.slice().sort((a, b) => a.v - b.v).slice(0, 12), dense: true });
    const act = pool.filter(r => r.q.vol && r.q.avgVol).map(r => ({ ...r, rv: r.q.vol / r.q.avgVol })).sort((a, b) => b.rv - a.rv).slice(0, 12);
    table($('#g3', pg), { cols: [c[0], { k: 'vol', h: 'Volume', a: 'r', v: r => r.q.vol, f: r => big(r.q.vol) }, { k: 'rv', h: '× avg', a: 'r', v: r => r.rv, f: r => nf(r.rv, 2) + '×' }, { k: 'p', h: '1D', a: 'r', v: r => r.q.pct, f: r => `<span class="${cls(r.q.pct)}">${pc(r.q.pct)}</span>` }], rows: act, dense: true, empty: '<b>No volume data</b>Volume is available for equities and ETFs only.' });
  };
  onSeg(pg, 'per', v => { per = v; draw(); }); onSeg(pg, 'uni', v => { uni = v; draw(); }); draw();
};

/* ---------- Global Markets ---------- */
PAGES.global = pg => {
  const st = { region: 'All', cls: 'All', ccy: 'local', range: '1Y', sel: ['IX.SPX', 'IX.UKX', 'IX.DAX', 'IX.NKY', 'IX.SENSEX', 'IX.IBOV'] }; { const hi = homeIdx(S.prefs.market || 'US'); if (hi && !st.sel.includes(hi)) st.sel.unshift(hi); }
  pg.innerHTML = hdr('global', 'Equity benchmarks by region and market classification. Index performance describes listed equities, not the wider economy — see Economic Indicators for macro data.', '') +
    `<section class="panel"><div class="tbar"><div class="row">${['All', 'Americas', 'Europe', 'Asia-Pacific', 'Middle East & Africa'].map(r => `<button class="chip ${r === 'All' ? 'on' : ''}" data-rg="${r}">${r}</button>`).join('')}</div><div class="row" style="margin-left:auto">${seg('cl', ['All', 'Developed', 'Emerging', 'Frontier'], 'All')}</div></div><div id="gt"></div><div class="pf"><span>Tick boxes to compare. Currency column = quotation currency. ${simB('SIM EOD')}</span><span>Linked: local FX vs USD and 10Y government yield</span></div></section>
    <section class="panel"><header class="ph"><span class="pt">Comparative performance</span><span class="pm">${seg('rg', RANGES, st.range, ['1D'])}${seg('ccy', [['local', 'Local ccy'], ['USD', 'In USD']], st.ccy)}</span></header><div class="pb"><div id="gc"></div><div class="note" id="gn" style="margin-top:6px"></div></div></section>`;
  let ch = null;
  const drawC = () => { if (!st.sel.length) { $('#gc', pg).innerHTML = '<div class="empty"><b>Nothing selected</b>Tick one or more indices above.</div>'; ch = null; return; } const { cfg, al } = buildCompare(st.sel, { range: st.range, ccy: st.ccy, h: 300 }); if (ch && document.body.contains(ch.el)) ch.set(cfg); else ch = new TChart($('#gc', pg), cfg); $('#gn', pg).innerHTML = compareNotes(st.sel, al, 'norm', st.ccy); };
  const drawT = () => {
    const rows = rowsOf(GLOBAL_IDX.filter(o => (st.region === 'All' || o.region === st.region) && (st.cls === 'All' || o.dev === st.cls)).map(o => o.id));
    table($('#gt', pg), {
      rows, dense: true, csv: 'global-markets', search: true, sort: { k: 'reg', d: 1 },
      cols: [{ k: 'sel', h: '', f: r => `<input type="checkbox" data-sel="${r.o.id}" aria-label="Compare ${esc(r.o.tk)}" ${st.sel.includes(r.o.id) ? 'checked' : ''}>` },
      { k: 'reg', h: 'Country', v: r => r.o.region + (COUNTRY[r.o.country]?.n || ''), f: r => `${esc(COUNTRY[r.o.country]?.n || r.o.country)}<div class="sub">${esc(r.o.region)} · ${esc(r.o.dev)}</div>`, csv: r => COUNTRY[r.o.country]?.n }, { k: 'tk', h: 'Index', v: r => r.o.tk, f: r => `${lnk(r.o.id)}<div class="sub">${esc(r.o.name)}</div>` },
      { k: 'last', h: 'Last', a: 'r', v: r => r.q.last, f: r => fv(r.o, r.q.last) }, { k: 'chg', h: 'Chg', a: 'r', v: r => r.q.chg, f: r => `<span class="${cls(r.q.chg)}">${fchg(r.o, r.q)}</span>` }, { k: 'pct', h: '1D', a: 'r', v: r => r.q.pct, f: r => `<span class="${cls(r.q.pct)}">${pc(r.q.pct)}</span>` },
      ...['1M', 'YTD', '1Y'].map(p => ({ k: p, h: p, a: 'r', v: r => perf(r.o.id, p), f: r => { const v = perf(r.o.id, p); return `<span class="${cls(v)}">${pc(v)}</span>`; } })),
      { k: 'usd', h: '1Y in USD', a: 'r', title: 'One-year price return converted to USD at simulated FX closes', v: r => usdRet(r.o, '1Y'), f: r => { const v = usdRet(r.o, '1Y'); return `<span class="${cls(v)}">${pc(v)}</span>`; } },
      { k: 'ccy', h: 'Ccy', v: r => r.o.ccy, f: r => esc(r.o.ccy) }, { k: 'fx', h: 'FX', f: r => { const c = COUNTRY[r.o.country]; return c?.fx ? lnk(c.fx) : '<span class="muted">—</span>'; } }, { k: 'y', h: '10Y yld', a: 'r', f: r => { const c = COUNTRY[r.o.country]; return c?.y ? `<a class="tk" data-sec="${c.y}" style="color:var(--fg)">${nf(quote(c.y).last, 2)}%</a>` : '<span class="muted">—</span>'; } },
      { k: 'asof', h: 'As of', v: r => r.q.date, f: r => `<span class="sub">${fds(r.q.date)}</span>` }]
    });
  };
  on(pg, 'click', '[data-rg]', (e, b) => { st.region = b.dataset.rg; $$('[data-rg]', pg).forEach(x => x.classList.toggle('on', x === b)); drawT(); });
  onSeg(pg, 'cl', v => { st.cls = v; drawT(); }); onSeg(pg, 'rg', v => { st.range = v; drawC(); }); onSeg(pg, 'ccy', v => { st.ccy = v; drawC(); });
  on(pg, 'change', '[data-sel]', (e, b) => { const id = b.dataset.sel; if (b.checked) { if (st.sel.length >= 8) { b.checked = false; toast('Compare up to 8 series at once', true); return; } st.sel.push(id); } else st.sel = st.sel.filter(x => x !== id); drawC(); });
  drawT(); drawC();
};
function usdRet(o, key) { if (o.ccy === 'USD') return perf(o.id, key); const fx = fxToUSD(o.ccy); if (!fx) return null; const a = perf(o.id, key), f = perf(fx.id, key); if (a == null || f == null) return null; const fr = fx.mult ? f / 100 : 1 / (1 + f / 100) - 1; return ((1 + a / 100) * (1 + fr) - 1) * 100; }

/* ---------- Market Calendars ---------- */
PAGES.calendar = pg => {
  let tab = 'earn';
  pg.innerHTML = hdr('calendar', `Upcoming events over the next 45 days. ${simB('Simulated schedule')} Dates are generated by the simulator, not announced by companies or agencies.`, '') + `<section class="panel"><div class="tabs" role="tablist"><button class="on" data-tab="earn" role="tab">Earnings</button><button data-tab="eco" role="tab">Economic releases</button></div><div id="cb"></div></section>`;
  const draw = () => {
    const el = $('#cb', pg); let items = [];
    if (tab === 'earn') items = EQ.map(o => { const f = fund(o.id); return { t: f.nextEarn, html: `<td>${lnk(o.id)}<div class="sub">${esc(o.name)}</div></td><td>${esc(o.sector)}</td><td>${esc(f.earnTime)}</td><td class="r">${big(f.mcap, '$')}</td><td class="r">${f.eps > 0 ? '$' + nf(f.eps * 1.02 / 4, 2) : '—'}</td>` }; });
    else items = ECO.map(o => { const q = quote(o.id); return { t: nextRelease(o), html: `<td>${lnk(o.id)}<div class="sub">${esc(o.name)}</div></td><td>${esc(COUNTRY[o.country]?.n || o.country)}</td><td>${esc(o.src)}</td><td class="r">${fv(o, q.last)}</td><td class="r">${fv(o, q.prev)}</td>` }; });
    items = items.filter(x => x.t >= END && x.t <= END + 45 * DAY).sort((a, b) => a.t - b.t);
    const groups = {}; items.forEach(x => (groups[x.t] = groups[x.t] || []).push(x));
    const head = tab === 'earn' ? '<th>Company</th><th>Sector</th><th>Timing</th><th class="r">Mkt cap</th><th class="r" title="Simulated consensus quarterly EPS">Est. EPS (q)</th>' : '<th>Indicator</th><th>Country</th><th>Source</th><th class="r">Latest</th><th class="r">Prior</th>';
    el.innerHTML = Object.keys(groups).length ? Object.entries(groups).map(([t, xs]) => `<div class="cal-d">${fd(+t, { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' })}</div><div class="tw"><table class="t dense"><thead><tr>${head}</tr></thead><tbody>${xs.map(x => `<tr>${x.html}</tr>`).join('')}</tbody></table></div>`).join('') : '<div class="empty"><b>No events in the next 45 days</b></div>';
  };
  on(pg, 'click', '[data-tab]', (e, b) => { tab = b.dataset.tab; $$('[data-tab]', pg).forEach(x => x.classList.toggle('on', x === b)); draw(); });
  draw();
};

/* ---------- My Watchlists ---------- */
PAGES.watchlists = pg => {
  let wl = S.watchlists.find(w => w.id === S.activeWL) || S.watchlists[0];
  pg.innerHTML = hdr('watchlists', `Multiple lists with live-in-workspace persistence. ${S.watchlists.length}/${plan().wl} lists on the ${plan().name} plan.`, `<button class="btn pri" id="nw">New watchlist</button>`) + `<div class="split"><section class="panel"><header class="ph"><span class="pt">Lists</span></header><div class="lst" id="wls"></div></section><section class="panel" id="wlp"></section></div>`;
  $('#nw', pg).onclick = () => newWatchlist();
  const drawL = () => { $('#wls', pg).innerHTML = S.watchlists.map(w => `<button class="li ${wl && w.id === wl.id ? 'on' : ''}" data-w="${w.id}"><b>${esc(w.name)}</b><small>${w.items.length} instruments</small></button>`).join('') || '<div class="empty">No watchlists yet.</div>'; };
  const drawP = () => {
    const p = $('#wlp', pg); if (!wl) { p.innerHTML = '<div class="empty"><b>Create your first watchlist</b>Use “New watchlist” above.</div>'; return; }
    let per = S.prefs.wlPer || '1M';
    p.innerHTML = `<header class="ph"><input class="inp sm" id="wln" value="${esc(wl.name)}" aria-label="Watchlist name" style="font-weight:600;min-width:200px"><span class="pm">${seg('wper', ['5D', '1M', 'YTD', '1Y'], per)}<button class="btn sm" id="wchart">Chart all</button><button class="btn sm" id="wcmp">Compare</button><button class="btn sm dng" id="wdel">Delete list</button></span></header><div class="tbar">${secSearch('Add ticker or name…')}</div><div id="wt"></div>`;
    const tb = () => qtable($('#wt', p), wl.items, per, { spark: true, badge: true, search: true, csv: 'watchlist', sort: null, empty: '<b>No instruments yet</b>Search above to add stocks, ETFs, indices, FX, yields or commodities.', extra: [{ k: 'rm', h: '', f: r => `<button class="btn sm ghost" data-rm="${r.o.id}" aria-label="Remove ${esc(r.o.tk)}">Remove</button>` }] });
    tb();
    onSeg(p, 'wper', v => { per = v; S.prefs.wlPer = v; save(); tb(); });
    $('#wln', p).onchange = e => { wl.name = e.target.value.trim() || wl.name; save(); drawL(); renderRP(); };
    $('#wdel', p).onclick = () => confirmBox(`Delete “${wl.name}”? This cannot be undone.`, () => { S.watchlists = S.watchlists.filter(w => w !== wl); wl = S.watchlists[0]; S.activeWL = wl?.id; save(); drawL(); drawP(); renderRP(); });
    $('#wchart', p).onclick = () => wl.items.length && openGraph({ ids: wl.items.filter(id => !isRate(BY[id])).slice(0, 8), mode: 'norm' });
    $('#wcmp', p).onclick = () => { S.compare = wl.items.filter(id => !isRate(BY[id])).slice(0, 8); save(); go('compare'); };
    on(p, 'click', '[data-rm]', (e, b) => { wl.items = wl.items.filter(x => x !== b.dataset.rm); save(); tb(); drawL(); renderRP(); });
    wireSecSearch(p, id => { if (wl.items.includes(id)) { toast(`${BY[id].tk} is already on this list`); return; } wl.items.push(id); save(); tb(); drawL(); renderRP(); toast(`Added ${BY[id].tk}`); });
  };
  on(pg, 'click', '[data-w]', (e, b) => { wl = S.watchlists.find(w => w.id === b.dataset.w); S.activeWL = wl.id; save(); drawL(); drawP(); renderRP(); });
  drawL(); drawP();
};

/* ---------- My Portfolio ---------- */
function holdingsValue(holds) { return holds.filter(h => BY[h.sid]).map(h => { const o = BY[h.sid], q = quote(h.sid); const fx = o.ccy !== 'USD' && FXUSD[o.ccy] ? (() => { const f = fxToUSD(o.ccy); const r = quote(f.id).last; return f.mult ? r : 1 / r; })() : 1; const mv = h.qty * q.last * fx; return { h, o, q, mv, day: h.qty * q.chg * fx, cost: h.cost != null ? h.qty * h.cost * fx : null }; }); }
function backtest(weights, range = '3Y', rebal = 'M') {
  const ids = Object.keys(weights).filter(id => BY[id] && weights[id] > 0); if (!ids.length) return null; const tot = ids.reduce((a, id) => a + weights[id], 0); const t0 = periodStart(range); const al = align(ids, t0, END, 'D', 'USD');
  let base = al.dates.findIndex((_, i) => ids.every((id, k) => al.cols[k][i] != null)); if (base < 0) return null; const vals = new Array(al.dates.length).fill(null); let units = ids.map((id, k) => weights[id] / tot * 100 / al.cols[k][base]); let lastM = new Date(al.dates[base]).getUTCMonth();
  for (let i = base; i < al.dates.length; i++) { const v = ids.reduce((a, id, k) => a + units[k] * (al.cols[k][i] ?? 0), 0); vals[i] = v; const m = new Date(al.dates[i]).getUTCMonth(); if (rebal === 'M' && m !== lastM) { units = ids.map((id, k) => weights[id] / tot * v / al.cols[k][i]); lastM = m; } }
  return { dates: al.dates, vals };
}
function seriesStats(vals) { const v = vals.filter(x => x != null); if (v.length < 3) return {}; const r = []; for (let i = 1; i < v.length; i++) r.push(Math.log(v[i] / v[i - 1])); const m = r.reduce((a, b) => a + b, 0) / r.length; const sd = Math.sqrt(r.reduce((a, b) => a + (b - m) ** 2, 0) / (r.length - 1)); let pk = v[0], dd = 0; v.forEach(x => { pk = Math.max(pk, x); dd = Math.min(dd, x / pk - 1); }); const yrs = r.length / 252; return { ret: (v[v.length - 1] / v[0] - 1) * 100, cagr: (Math.pow(v[v.length - 1] / v[0], 1 / yrs) - 1) * 100, vol: sd * Math.sqrt(252) * 100, dd: dd * 100, sharpe: (m * 252) / (sd * Math.sqrt(252)) }; }
PAGES.portfolio = pg => {
  const P = S.portfolio; let range = '1Y';
  pg.innerHTML = hdr('portfolio', 'Holdings valued at simulated closes in USD. Performance is a constant-holdings look-back: today’s positions applied to past prices.', `<button class="btn" id="pexp">Holdings CSV</button>`) +
    `<div class="grid"><section class="panel c8"><header class="ph"><span class="pt">${esc(P.name)}</span><span class="pm" id="ptot"></span></header><div class="tbar"><div class="row" style="flex:1">${secSearch('Add holding…')}<input class="inp sm" id="pq" type="number" min="0" step="any" placeholder="Qty" style="width:80px" aria-label="Quantity"><input class="inp sm" id="pc" type="number" min="0" step="any" placeholder="Unit cost" style="width:100px" aria-label="Unit cost"><span id="psel" class="note"></span><button class="btn sm pri" id="padd">Add</button></div></div><div id="pt"></div></section>
    <section class="panel c4"><header class="ph"><span class="pt">Allocation</span></header><div class="pb"><div id="pal"></div></div></section>
    <section class="panel c12"><header class="ph"><span class="pt">Look-back performance vs. S&amp;P 500</span><span class="pm">${seg('prg', ['3M', '6M', 'YTD', '1Y', '3Y', '5Y'], range)}</span></header><div class="pb"><div id="pch"></div><div class="kv" id="pst" style="margin-top:8px"></div></div></section></div>`;
  let pick = null; let ch = null;
  wireSecSearch(pg, id => { pick = id; $('#psel', pg).textContent = BY[id].tk + ' selected'; $('#pc', pg).value = nf(quote(id).last, 2).replace(/,/g, ''); });
  $('#padd', pg).onclick = () => { const q = +$('#pq', pg).value, c = +$('#pc', pg).value; if (!pick || !(q > 0)) { toast('Pick an instrument and enter a quantity above zero', true); return; } if (isRate(BY[pick])) { toast('Yields and indicators cannot be held', true); return; } const ex = P.holdings.find(h => h.sid === pick); if (ex) { const nq = ex.qty + q; ex.cost = ((ex.cost || 0) * ex.qty + (c || 0) * q) / nq; ex.qty = nq; } else P.holdings.push({ sid: pick, qty: q, cost: c || null }); save(); pick = null; $('#psel', pg).textContent = ''; $('#pq', pg).value = ''; draw(); };
  const draw = () => {
    const rows = holdingsValue(P.holdings); const tot = rows.reduce((a, r) => a + r.mv, 0), day = rows.reduce((a, r) => a + r.day, 0), cost = rows.reduce((a, r) => a + (r.cost ?? r.mv), 0);
    $('#ptot', pg).innerHTML = `<span class="mono">$${nf(tot, 0)}</span> <span class="mono ${cls(day)}">${sgn(day, 0)} (${pc(day / (tot - day) * 100)})</span>`;
    table($('#pt', pg), { rows, dense: true, sort: { k: 'mv', d: -1 }, empty: '<b>No holdings</b>Add a position above.', cols: [{ k: 'tk', h: 'Holding', v: r => r.o.tk, f: r => `${lnk(r.o.id)}<div class="sub">${esc(r.o.name)}</div>` }, { k: 'qty', h: 'Qty', a: 'r', v: r => r.h.qty, f: r => `<input class="inp sm" type="number" step="any" min="0" value="${r.h.qty}" data-qty="${r.o.id}" style="width:80px;text-align:right" aria-label="Quantity">` }, { k: 'px', h: 'Price', a: 'r', v: r => r.q.last, f: r => fv(r.o, r.q.last) + (r.o.ccy !== 'USD' ? ` <span class="sub">${r.o.ccy}</span>` : '') }, { k: 'mv', h: 'Value (USD)', a: 'r', v: r => r.mv, f: r => nf(r.mv, 0) }, { k: 'w', h: 'Weight', a: 'r', v: r => r.mv / tot, f: r => nf(r.mv / tot * 100, 1) + '%' }, { k: 'day', h: 'Day P&L', a: 'r', v: r => r.day, f: r => `<span class="${cls(r.day)}">${sgn(r.day, 0)}</span>` }, { k: 'pl', h: 'Total P&L', a: 'r', v: r => r.cost == null ? null : r.mv - r.cost, f: r => r.cost == null ? '<span class="muted">no cost</span>' : `<span class="${cls(r.mv - r.cost)}">${sgn(r.mv - r.cost, 0)} (${pc((r.mv / r.cost - 1) * 100, 1)})</span>` }, { k: 'x', h: '', f: r => `<button class="btn sm ghost" data-del="${r.o.id}">Remove</button>` }] });
    const by = {}; rows.forEach(r => { const k = r.o.type === 'equity' ? r.o.sector : r.o.fi ? 'Fixed income' : r.o.cat === 'Commodity' || r.o.type === 'commodity' ? 'Commodities' : r.o.cat || r.o.cls; by[k] = (by[k] || 0) + r.mv; });
    $('#pal', pg).innerHTML = `<div class="alloc">${Object.entries(by).sort((a, b) => b[1] - a[1]).map(([k, v], i) => `<div class="ar"><span>${esc(k)}</span><div class="bar"><i style="width:${v / tot * 100}%;background:${PAL[i % 8]}"></i></div><span class="mono" style="text-align:right">${nf(v / tot * 100, 1)}%</span></div>`).join('') || '<div class="empty">No holdings.</div>'}</div><div class="note" style="margin-top:8px">Cost basis $${nf(cost, 0)} · unrealised ${sgn(tot - cost, 0)}</div>`;
    const w = {}; rows.forEach(r => w[r.o.id] = r.mv); const bt = backtest(w, range, 'none');
    if (bt) { const sp = align(['IX.SPX'], periodStart(range), END, 'D', 'USD'); const spv = bt.dates.map(t => { const i = bsLE(sp.dates, t); return i < 0 ? null : sp.cols[0][i]; }); const cfg = { dates: bt.dates, panes: [{ h: 240, rebase: true, fmt: pctAx, series: [{ key: 'p', label: 'Portfolio', color: 'var(--s2)', values: bt.vals, type: 'area' }, { key: 's', label: 'S&P 500', color: 'var(--s8)', values: spv }] }] }; if (ch && document.body.contains(ch.el)) ch.set(cfg); else ch = new TChart($('#pch', pg), cfg); const a = seriesStats(bt.vals), b = seriesStats(spv); $('#pst', pg).innerHTML = [['Return', pc(a.ret), pc(b.ret)], ['Ann. volatility', nf(a.vol, 1) + '%', nf(b.vol, 1) + '%'], ['Max drawdown', pc(a.dd), pc(b.dd)], ['Return / vol', nf(a.sharpe, 2), nf(b.sharpe, 2)]].map(([k, x, y]) => `<div><dt>${k}</dt><dd>${x} <span class="muted">vs ${y}</span></dd></div>`).join(''); } else $('#pch', pg).innerHTML = '<div class="empty">Add holdings to see performance.</div>';
  };
  on(pg, 'change', '[data-qty]', (e, b) => { const h = P.holdings.find(x => x.sid === b.dataset.qty); h.qty = Math.max(0, +b.value || 0); save(); draw(); });
  on(pg, 'click', '[data-del]', (e, b) => { P.holdings = P.holdings.filter(h => h.sid !== b.dataset.del); save(); draw(); });
  onSeg(pg, 'prg', v => { range = v; draw(); });
  $('#pexp', pg).onclick = () => csvModal('portfolio', ['ticker,name,qty,unit_cost,price,currency,value_usd'].concat(holdingsValue(P.holdings).map(r => [csvCell(r.o.tk), csvCell(r.o.name), r.h.qty, r.h.cost ?? '', r.q.last.toFixed(4), csvCell(r.o.ccy), r.mv.toFixed(2)].join(','))).join('\n'));
  draw();
};

