    const cfg = { dates: al.dates, panes, start: s0, label: o.name + ' price chart', clean: true, lastTag: !retail, retail, noXAxis: retail, legend: false, noTip: true, onHover: i => readout(i) };
    const host = $('#sc', pg); host.classList.add('clean'); host.classList.toggle('retail', retail); const vb = $('[data-ovl="vol"]', pg); if (vb) vb.hidden = retail; if (ch && document.body.contains(ch.el)) ch.set(cfg); else ch = new TChart(host, cfg);
