    const ranges = o.type === 'econ' ? '' : rb('Day range', q.low, q.high, q.last) + rb('52-week range', q.lo52, q.hi52, q.last);
    const peers = o.type === 'equity' ? EQ.filter(x => x.sector === o.sector && x.id !== id).slice(0, 5) : o.type === 'etf' && o.sector ? SECTORS.filter(x => x.id !== id).slice(0, 5) : o.type === 'index' ? GLOBAL_IDX.filter(x => x.id !== id && x.region === o.region).slice(0, 5) : [];
    return `${ranges ? `<section><h3 class="side-h">Price ranges</h3>${ranges}</section>` : ''}<section><h3 class="side-h">Key statistics ${o.type === 'equity' ? '<small>Simulated</small>' : ''}</h3><dl class="kl">${kv.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join('')}</dl></section>${o.type === 'yield' && !o.spread ? '<section><h3 class="side-h">Yield curve</h3><div id="scv"></div></section>' : o.desc ? `<section><h3 class="side-h">About this measure</h3><p class="note" style="margin:0">${esc(o.desc)}. Simulated values.</p></section>` : ''}${peers.length ? `<section><h3 class="side-h">${o.type === 'equity' ? 'Sector peers' : 'Related'} <small>1M</small></h3>${peers.map(p => { const pq = quote(p.id); return `<div class="peer" data-sec="${p.id}" role="link" tabindex="0"><div class="pn"><b>${esc(p.tk)}</b><small>${esc(p.short || p.name)}</small></div>${spark(lastN(p.id, 22), 64, 22)}<div class="pp">${fv(p, pq.last)}<br><span class="chgp ${cls(pq.pct)}">${pc(pq.pct)}</span></div></div>`; }).join('')}</section>` : ''}`;
