    if (tab === 'val') { const f = fund(id); const peers = EQ.filter(x => x.sector === o.sector).map(x => fund(x.id)); const med = k => { const v = peers.map(p => p[k]).filter(x => x != null && isFinite(x)).sort((a, b) => a - b); return v.length ? v[Math.floor(v.length / 2)] : null; }; const all = EQ.map(x => fund(x.id)); const medAll = k => { const v = all.map(p => p[k]).filter(x => x != null && isFinite(x)).sort((a, b) => a - b); return v[Math.floor(v.length / 2)]; }; el.innerHTML = `<div class="tw"><table class="t"><thead><tr><th>Metric</th><th class="r">${esc(o.tk)}</th><th class="r">${esc(o.sector)} median</th><th class="r">Universe median</th><th>vs sector</th></tr></thead><tbody>${[['P/E (TTM)', 'pe', 1, 'x'], ['Forward P/E', 'fpe', 1, 'x'], ['Price / sales', 'ps', 1, 'x'], ['Price / book', 'pb', 1, 'x'], ['EV / EBITDA', 'evE', 1, 'x'], ['Dividend yield', 'div', 2, '%'], ['FCF yield', 'fcfY', 2, '%']].map(([l, k, dp, u]) => { const v = f[k], m = med(k); const rel = v != null && m ? (v / m - 1) * 100 : null; const cheap = u === '%' ? rel > 0 : rel < 0; return `<tr><td>${l}</td><td class="r">${v == null ? 'n/m' : nf(v, dp) + u}</td><td class="r">${m == null ? '—' : nf(m, dp) + u}</td><td class="r">${nf(medAll(k), dp) + u}</td><td>${rel == null ? '—' : `<span class="badge ${cheap ? 'ok' : 'bad'}">${pc(rel, 0)} ${u === '%' ? (rel > 0 ? 'higher yield' : 'lower yield') : (rel < 0 ? 'cheaper' : 'richer')}</span>`}</td></tr>`; }).join('')}</tbody></table></div><div class="note" style="margin-top:6px">Sector median across the ${peers.length} tracked ${esc(o.sector)} names. ${typeof fdPeerNote === 'function' ? fdPeerNote(f, peers) : 'Simulated fundamentals.'}</div>`; }
    if (tab === 'perf') { const ks = ['1D', '5D', '1M', '3M', '6M', 'YTD', '1Y', '3Y', '5Y', '10Y']; const ref = isRate(o) ? null : o.type === 'equity' || o.mkt === 'US' ? 'IX.SPX' : null; el.innerHTML = `<div class="tw"><table class="t"><thead><tr><th>Period</th><th class="r">${esc(o.tk)}</th>${ref ? '<th class="r">S&P 500</th><th class="r">Relative</th>' : ''}<th class="r">Annualised</th></tr></thead><tbody>${ks.map(k => { const v = perf(id, k), r = ref ? perf(ref, k) : null; const an = ['3Y', '5Y', '10Y'].includes(k) && !isRate(o) ? cagr(id, k) : null; return `<tr><td>${k}</td><td class="r ${cls(v)}">${fper(o, v)}</td>${ref ? `<td class="r">${pc(r)}</td><td class="r ${cls(v - r)}">${sgn(v - r, 2)} pts</td>` : ''}<td class="r">${an != null ? pc(an) : '—'}</td></tr>`; }).join('')}</tbody></table></div>${isRate(o) ? '' : `<div class="kv" style="margin-top:8px"><div><dt>1Y volatility</dt><dd>${nf(annVol(id), 1)}%</dd></div><div><dt>3Y volatility</dt><dd>${nf(annVol(id, '3Y'), 1)}%</dd></div><div><dt>1Y max drawdown</dt><dd class="dn">${pc(maxDD(id), 1)}</dd></div><div><dt>5Y max drawdown</dt><dd class="dn">${pc(maxDD(id, '5Y'), 1)}</dd></div><div><dt>Beta 1Y vs S&P</dt><dd>${nf(beta(id), 2)}</dd></div></div>`}<div class="note" style="margin-top:6px">${o.type === 'yield' ? 'Changes in basis points.' : o.type === 'econ' ? 'Changes in the indicator’s own unit.' : 'Price returns; distributions excluded.'} Base = last observation on or before the period start.</div>`; }
    if (tab === 'notes') { const ns = S.notes.filter(n => n.links.includes(id)); el.innerHTML = (ns.length ? ns.map(n => `<div class="news-i"><div class="m">${fdt(n.updated)}</div><h4><a class="tk" data-note="${n.id}" style="font-family:var(--f-ui);font-size:14px">${esc(n.title)}</a></h4><div class="note" style="white-space:pre-wrap">${esc(n.body.slice(0, 280))}${n.body.length > 280 ? '…' : ''}</div></div>`).join('') : '<div class="empty"><b>No notes on this security</b>Start one with Write note.</div>') + `<div style="margin-top:8px"><button class="btn sm pri" data-qa="note" data-id="${id}">Write note</button></div>`; }
