/* ---------- Stock Screener ---------- */
const SCR_F = [['mcapMin', 'Market cap min ($bn)'], ['mcapMax', 'Market cap max ($bn)'], ['pxMin', 'Price min ($)'], ['pxMax', 'Price max ($)'], ['peMax', 'P/E max'], ['divMin', 'Dividend yield min (%)'], ['r1yMin', '1Y return min (%)'], ['r1yMax', '1Y return max (%)'], ['nmMin', 'Net margin min (%)'], ['grMin', 'Revenue growth min (%)'], ['betaMax', 'Beta max'], ['avMin', 'Avg volume min (M sh)']];
function runScreen(f) {
  return EQ.filter(o => { const F_ = fund(o.id), q = quote(o.id), r1 = perf(o.id, '1Y'); if (f.sectors && f.sectors.length && !f.sectors.includes(o.sector)) return false; const t = (v, k, lo) => f[k] == null || f[k] === '' || (v != null && (lo ? v >= +f[k] : v <= +f[k])); return t(F_.mcap / 1e9, 'mcapMin', 1) && t(F_.mcap / 1e9, 'mcapMax', 0) && t(q.last, 'pxMin', 1) && t(q.last, 'pxMax', 0) && t(F_.pe, 'peMax', 0) && t(F_.div, 'divMin', 1) && t(r1, 'r1yMin', 1) && t(r1, 'r1yMax', 0) && t(F_.nm, 'nmMin', 1) && t(F_.gr, 'grMin', 1) && t(F_.beta, 'betaMax', 0) && t(q.avgVol / 1e6, 'avMin', 1); });
}
function screenSummary(f) { const p = []; if (f.sectors?.length) p.push(f.sectors.join(', ')); SCR_F.forEach(([k, l]) => { if (f[k] != null && f[k] !== '') p.push(`${l.replace(/ \(.*\)/, '')} ${f[k]}`); }); return p.join(' · ') || 'No filters (all tracked equities)'; }
PAGES.screener = (pg, sid) => {
  const saved = S.screens.find(s => s.id === sid); const f = saved ? JSON.parse(JSON.stringify(saved.f)) : { sectors: [], ...(state.screenPrefill || {}) }; state.screenPrefill = null;
  pg.innerHTML = hdr('screener', `Screen ${EQ.length} tracked U.S. large caps on price, returns and ${typeof fdCoverage === 'function' ? fdCoverage() : 'simulated fundamentals'}. Only fields with data for every name are offered.`, `<button class="btn" id="sv">${saved ? 'Update screen' : 'Save screen'}</button><button class="btn" id="swl">Add results to watchlist</button>`) +
    `<section class="panel"><div class="pb" style="display:flex;flex-direction:column;gap:10px"><div class="row" id="ssec">${SECTOR_NAMES.map(s => `<button class="chip ${f.sectors.includes(s) ? 'on' : ''}" data-sct="${esc(s)}">${esc(s)}</button>`).join('')}</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px">${SCR_F.map(([k, l]) => `<label class="f"><span>${l}</span><input class="inp sm" type="number" step="any" data-fk="${k}" value="${f[k] ?? ''}"></label>`).join('')}</div><div class="row"><span class="note" id="scnt"></span><button class="btn sm ghost" id="sclr">Clear filters</button></div></div></section><section class="panel"><div id="sres"></div></section>`;
  const cols = [{ k: 'tk', h: 'Company', v: r => r.o.tk, f: r => `${lnk(r.o.id)}<div class="sub">${esc(r.o.name)}</div>` }, { k: 'sec', h: 'Sector', v: r => r.o.sector, f: r => `<span class="sub">${esc(r.o.sector)}</span>` }, { k: 'px', h: 'Price', a: 'r', v: r => r.q.last, f: r => nf(r.q.last) }, { k: 'p1', h: '1D', a: 'r', v: r => r.q.pct, f: r => `<span class="${cls(r.q.pct)}">${pc(r.q.pct)}</span>` }, { k: 'r1', h: '1Y', a: 'r', v: r => perf(r.o.id, '1Y'), f: r => `<span class="${cls(perf(r.o.id, '1Y'))}">${pc(perf(r.o.id, '1Y'))}</span>` }, { k: 'mc', h: 'Mkt cap', a: 'r', v: r => r.f.mcap, f: r => big(r.f.mcap, '$') }, { k: 'pe', h: 'P/E', a: 'r', v: r => r.f.pe, f: r => r.f.pe ? nf(r.f.pe, 1) : 'n/m' }, { k: 'div', h: 'Div %', a: 'r', v: r => r.f.div, f: r => nf(r.f.div, 2) }, { k: 'nm', h: 'Net mgn', a: 'r', v: r => r.f.nm, f: r => nf(r.f.nm, 1) + '%' }, { k: 'gr', h: 'Rev gr.', a: 'r', v: r => r.f.gr, f: r => pc(r.f.gr, 1) }, { k: 'b', h: 'Beta', a: 'r', v: r => r.f.beta, f: r => nf(r.f.beta, 2) }, { k: 'av', h: 'Avg vol', a: 'r', v: r => r.q.avgVol, f: r => big(r.q.avgVol) }];
  let tb = null; const run = () => { state.shareScreen = JSON.parse(JSON.stringify(f)); const res = runScreen(f).map(o => ({ o, q: quote(o.id), f: fund(o.id) })); $('#scnt', pg).innerHTML = `<b>${res.length}</b> of ${EQ.length} match · ${esc(screenSummary(f))}`; if (tb) tb.update(res); else tb = table($('#sres', pg), { rows: res, cols, dense: true, csv: 'screen-results', search: true, page: 25, sort: saved?.sort || { k: 'mc', d: -1 }, empty: '<b>No matches</b>Loosen one of the filters.' }); };
  on(pg, 'click', '[data-sct]', (e, b) => { const s = b.dataset.sct; f.sectors.includes(s) ? f.sectors = f.sectors.filter(x => x !== s) : f.sectors.push(s); b.classList.toggle('on'); run(); });
  on(pg, 'input', '[data-fk]', (e, b) => { f[b.dataset.fk] = b.value === '' ? null : +b.value; run(); });
  $('#sclr', pg).onclick = () => { Object.keys(f).forEach(k => delete f[k]); f.sectors = []; $$('[data-fk]', pg).forEach(i => i.value = ''); $$('[data-sct]', pg).forEach(b => b.classList.remove('on')); run(); };
  $('#sv', pg).onclick = () => { if (saved) { saved.f = JSON.parse(JSON.stringify(f)); saved.sort = tb.state.k ? { k: tb.state.k, d: tb.state.d } : null; save(); toast('Screen updated'); return; } modal('Save screen', `<label class="f"><span>Name</span><input class="inp" id="snm" value="${esc(screenSummary(f).slice(0, 60))}"></label>`, { actions: [{ label: 'Cancel', fn: c => c() }, { label: 'Save', cls: 'pri', fn: (c, mb) => { const s = { id: uid(), name: $('#snm', mb).value.trim() || 'Untitled screen', f: JSON.parse(JSON.stringify(f)), sort: tb.state.k ? { k: tb.state.k, d: tb.state.d } : null, created: Date.now() }; S.screens.unshift(s); save(); c(); toast('Screen saved to My Screens'); go('screener', s.id); } }] }); };
  $('#swl', pg).onclick = e => { const ids = runScreen(f).map(o => o.id); if (!ids.length) return toast('No results to add', true); popMenu(e.currentTarget, [{ head: `Add ${ids.length} results to…` }, ...S.watchlists.map(w => ({ label: w.name, fn: () => { ids.forEach(id => !w.items.includes(id) && w.items.push(id)); save(); renderRP(); toast(`Added to ${w.name}`); } })), { label: '+ New watchlist…', fn: () => newWatchlist(ids) }]); };
  run();
};

/* ---------- Compare Matrix ---------- */
PAGES.compare = pg => {
  let range = '1Y', ch = null;
  pg.innerHTML = hdr('compare', 'Side-by-side metrics with the best value in each row highlighted. Add up to 8 instruments.', `${secSearch('Add to comparison…', PRICE_TYPES)}`) + `<section class="panel"><div class="pb flush" id="cm"></div><div class="pf"><span>Best in row highlighted; “—” means the metric does not apply to that instrument type.</span><span>${simB()} returns are price returns</span></div></section><section class="panel"><header class="ph"><span class="pt">Normalized performance</span><span class="pm">${seg('cmr', RANGES, range, ['1D'])}</span></header><div class="pb"><div id="cc"></div><div class="note" id="cn"></div></div></section>`;
  const M = [['Price', id => quote(id).last, (o, v) => fv(o, v), 0], ['1D %', id => quote(id).pct, (o, v) => pc(v), 1], ['1M %', id => perf(id, '1M'), (o, v) => pc(v), 1], ['YTD %', id => perf(id, 'YTD'), (o, v) => pc(v), 1], ['1Y %', id => perf(id, '1Y'), (o, v) => pc(v), 1], ['3Y ann. %', id => cagr(id, '3Y'), (o, v) => pc(v), 1], ['1Y volatility', id => annVol(id), (o, v) => nf(v, 1) + '%', -1], ['1Y max drawdown', id => maxDD(id), (o, v) => pc(v, 1), 1], ['Return / vol (1Y)', id => { const a = perf(id, '1Y'), b = annVol(id); return a != null && b ? a / b : null; }, (o, v) => nf(v, 2), 1], ['Beta vs S&P (1Y)', id => beta(id), (o, v) => nf(v, 2), 0], ['Market cap', id => fund(id)?.mcap, (o, v) => big(v, '$'), 0], ['P/E', id => fund(id)?.pe, (o, v) => nf(v, 1), -1], ['Dividend yield', id => fund(id)?.div ?? (BY[id].fi ? BY[id].dist : null), (o, v) => nf(v, 2) + '%', 1], ['Net margin', id => fund(id)?.nm, (o, v) => nf(v, 1) + '%', 1], ['Duration (yrs)', id => BY[id].dur ?? null, (o, v) => nf(v, 1), 0]];
  const draw = () => {
    const ids = S.compare.filter(id => BY[id] && !isRate(BY[id])); S.compare = ids;
    if (!ids.length) { $('#cm', pg).innerHTML = '<div class="empty"><b>Nothing to compare</b>Add instruments with the search box.</div>'; $('#cc', pg).innerHTML = ''; return; }
    $('#cm', pg).innerHTML = `<div class="tw"><table class="t"><thead><tr><th>Metric</th>${ids.map(id => `<th class="r">${lnk(id)} <button class="btn sm ghost" data-rm="${id}" aria-label="Remove">×</button><div class="sub" style="text-transform:none;letter-spacing:0;font-weight:400;max-width:140px;margin-left:auto">${esc(BY[id].short || BY[id].name)}</div></th>`).join('')}</tr></thead><tbody>${M.map(([l, fn, fmt, dir]) => { const vals = ids.map(id => { const v = fn(id); return v == null || !isFinite(v) ? null : v; }); const valid = vals.filter(v => v != null); if (!valid.length) return ''; const best = dir === 0 ? null : dir > 0 ? Math.max(...valid) : Math.min(...valid); return `<tr><td>${l}</td>${vals.map((v, k) => `<td class="r" ${v != null && v === best && valid.length > 1 ? 'style="background:var(--accent-soft);color:var(--accent)"' : ''}>${v == null ? '<span class="muted">—</span>' : fmt(BY[ids[k]], v)}</td>`).join('')}</tr>`; }).join('')}</tbody></table></div>`;
    const { cfg, al } = buildCompare(ids, { range, h: 280 }); if (ch && document.body.contains(ch.el)) ch.set(cfg); else ch = new TChart($('#cc', pg), cfg); $('#cn', pg).innerHTML = compareNotes(ids, al, 'norm', 'local');
  };
  wireSecSearch(pg, id => { if (S.compare.includes(id)) return; if (S.compare.length >= 8) return toast('Compare up to 8 instruments', true); S.compare.push(id); save(); draw(); });
  on(pg, 'click', '[data-rm]', (e, b) => { S.compare = S.compare.filter(x => x !== b.dataset.rm); save(); draw(); });
  onSeg(pg, 'cmr', v => { range = v; draw(); }); draw();
};

/* ---------- Lots of Charts ---------- */
PAGES.lots = pg => {
  const sets = () => [...S.watchlists.map(w => ['wl:' + w.id, 'Watchlist: ' + w.name, w.items]), ['sec', 'U.S. sectors', SECTORS.map(o => o.id)], ['us', 'U.S. indices', US_IDX.map(o => o.id)], ['gl', 'Global indices', GLOBAL_IDX.map(o => o.id)], ['fx', 'FX majors', ['FX.DXY', 'FX.EURUSD', 'FX.GBPUSD', 'FX.USDJPY', 'FX.AUDUSD', 'FX.USDCAD', 'FX.USDCHF', 'FX.USDCNH']], ['cm', 'Commodities', CMD.map(o => o.id)], ['y10', '10Y government yields', YC.map(c => `YD.${c[0]}10`)], ['ff', 'Size & style ETFs', STYLE.map(o => o.id)]];
  let set = S.prefs.lotsSet || 'sec', range = '6M';
  pg.innerHTML = hdr('lots', 'A grid of small multiples on a shared range. Each chart keeps its own scale; compare shapes, not levels.', `<select class="inp sm" id="ls" aria-label="Chart set">${sets().map(s => `<option value="${s[0]}" ${s[0] === set ? 'selected' : ''}>${esc(s[1])}</option>`).join('')}</select>${seg('lr', ['1M', '3M', '6M', 'YTD', '1Y', '3Y', '5Y'], range)}`) + '<div class="mini" id="lg"></div>';
  const draw = () => {
    destroyCharts(); const s = sets().find(x => x[0] === set) || sets()[0]; const ids = s[2].filter(id => BY[id]); const g = $('#lg', pg);
    if (!ids.length) { g.innerHTML = '<div class="empty"><b>This set is empty</b></div>'; return; }
    g.innerHTML = ids.map(id => { const o = BY[id], q = quote(id), p = perf(id, range); return `<section class="panel"><header class="ph">${lnk(id)}<span class="sub" style="max-width:120px">${esc(o.short || o.name)}</span><span class="pm mono"><span>${fv(o, q.last)}</span><span class="${cls(p)}">${fper(o, p)}</span></span></header><div class="pb"><div data-mc="${id}"></div></div></section>`; }).join('');
    ids.forEach(id => { const al = align([id], periodStart(range), END); const o = BY[id]; const pv = perf(id, range); new TChart($(`[data-mc="${id}"]`, g), { dates: al.dates, legend: false, panes: [{ h: 110, fmt: v => o.type === 'yield' ? nf(v, 2) : axFmt(v), series: [{ key: id, label: o.tk, color: pv >= 0 ? 'var(--up)' : 'var(--dn)', values: al.cols[0], type: 'area' }] }] }); });
  };
  $('#ls', pg).onchange = e => { set = e.target.value; S.prefs.lotsSet = set; save(); draw(); }; onSeg(pg, 'lr', v => { range = v; draw(); }); draw();
};

/* ---------- Market Scatter ---------- */
PAGES.scatter = pg => {
  const MET = { r1y: ['1Y return %', id => perf(id, '1Y')], r1m: ['1M return %', id => perf(id, '1M')], ytd: ['YTD return %', id => perf(id, 'YTD')], vol: ['1Y volatility %', id => annVol(id)], dd: ['1Y max drawdown %', id => maxDD(id)], beta: ['Beta vs S&P', id => beta(id)], pe: ['P/E', id => fund(id)?.pe], div: ['Dividend yield %', id => fund(id)?.div], mcap: ['Market cap ($bn, log)', id => fund(id) ? fund(id).mcap / 1e9 : null], nm: ['Net margin %', id => fund(id)?.nm], gr: ['Revenue growth %', id => fund(id)?.gr] };
  const UNI = { eq: ['U.S. large caps', () => EQ.map(o => o.id), true], etf: ['Sector & style ETFs', () => [...SECTORS, ...STYLE].map(o => o.id), false], gl: ['Global indices', () => GLOBAL_IDX.map(o => o.id), false], all: ['All priced assets', () => U.filter(o => PRICE_TYPES.includes(o.type)).map(o => o.id), false] };
  let x = 'vol', y = 'r1y', uni = 'eq', labels = true;
  pg.innerHTML = hdr('scatter', 'Plot any two metrics across a universe. Click a point to open the security. The dashed line is an ordinary least-squares fit.', `<select class="inp sm" id="su" aria-label="Universe">${Object.entries(UNI).map(([k, v]) => `<option value="${k}">${v[0]}</option>`).join('')}</select><label class="row note">X <select class="inp sm" id="sx"></select></label><label class="row note">Y <select class="inp sm" id="sy"></select></label><label class="row note"><input type="checkbox" id="sl" checked> Labels</label>`) + `<section class="panel"><div class="pb"><div id="scp"></div><div class="row note" id="slg" style="margin-top:6px"></div><div class="note" id="sst"></div></div></section>`;
  const opts = () => { const fundOk = UNI[uni][2]; const keys = Object.keys(MET).filter(k => fundOk || !['pe', 'div', 'mcap', 'nm', 'gr'].includes(k)); if (!keys.includes(x)) x = 'vol'; if (!keys.includes(y)) y = 'r1y'; $('#sx', pg).innerHTML = keys.map(k => `<option value="${k}" ${k === x ? 'selected' : ''}>${MET[k][0]}</option>`).join(''); $('#sy', pg).innerHTML = keys.map(k => `<option value="${k}" ${k === y ? 'selected' : ''}>${MET[k][0]}</option>`).join(''); };
  const draw = () => {
    const ids = UNI[uni][1](); const groups = {}; const keyOf = o => o.sector || o.region || o.cls;
    ids.forEach(id => { const o = BY[id]; const xv = MET[x][1](id), yv = MET[y][1](id); if (xv == null || yv == null || !isFinite(xv) || !isFinite(yv) || (x === 'mcap' && xv <= 0)) return; (groups[keyOf(o)] = groups[keyOf(o)] || []).push({ x: xv, y: yv, label: o.tk, name: o.name, id, extra: keyOf(o) }); });
    const series = Object.entries(groups).map(([g, pts], i) => ({ label: g, color: PAL[i % 8], points: pts }));
    const all = series.flatMap(s => s.points); const xs = all.map(p => x === 'mcap' ? Math.log10(p.x) : p.x), ys = all.map(p => p.y); const n = xs.length;
    let stat = ''; if (n > 2) { const mx = xs.reduce((a, b) => a + b, 0) / n, my = ys.reduce((a, b) => a + b, 0) / n; let sxy = 0, sxx = 0, syy = 0; for (let i = 0; i < n; i++) { sxy += (xs[i] - mx) * (ys[i] - my); sxx += (xs[i] - mx) ** 2; syy += (ys[i] - my) ** 2; } const b = sxy / sxx, a = my - b * mx, r = sxy / Math.sqrt(sxx * syy); const lo = Math.min(...xs), hi = Math.max(...xs); series.push({ label: 'OLS fit', color: 'var(--fg2)', line: true, dash: true, r: .01, points: [{ x: x === 'mcap' ? Math.pow(10, lo) : lo, y: a + b * lo }, { x: x === 'mcap' ? Math.pow(10, hi) : hi, y: a + b * hi }] }); stat = `n = ${n} · correlation r = ${nf(r, 2)} · slope ${nf(b, 3)}${x === 'mcap' ? ' per log10($bn)' : ''}. Correlation describes association within this simulated sample only.`; }
    xyChart($('#scp', pg), { series, xlab: MET[x][0], ylab: MET[y][0], xlog: x === 'mcap', labels, h: 420, onPick: p => p.id && go('sec', p.id) });
    $('#slg', pg).innerHTML = series.filter(s => !s.line).map(s => `<span><i style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${s.color};vertical-align:middle;margin-right:4px"></i>${esc(s.label)}</span>`).join(''); $('#sst', pg).textContent = stat;
  };
  $('#su', pg).onchange = e => { uni = e.target.value; opts(); draw(); }; $('#sx', pg).onchange = e => { x = e.target.value; draw(); }; $('#sy', pg).onchange = e => { y = e.target.value; draw(); }; $('#sl', pg).onchange = e => { labels = e.target.checked; draw(); };
  opts(); draw();
};

/* ---------- Historical Analysis ---------- */
PAGES.hist = (pg, pid) => {
  let id = pid && BY[pid] && !isRate(BY[pid]) ? pid : state.ctx && BY[state.ctx] && !isRate(BY[state.ctx]) ? state.ctx : 'IX.SPX';
  const draw = () => {
    const o = BY[id], s = series(id); state.ctx = id;
    pg.innerHTML = hdr('hist', 'Ten years of calendar returns, monthly seasonality, drawdowns and volatility regimes for one instrument.', `<span class="chip on">${lnk(id)}</span>${secSearch('Change security…', PRICE_TYPES)}`) + `<div class="grid">${panelH('Summary statistics (full history)', { cls: 'c12', id: 'hs' })}${panelH('Calendar-year returns', { cls: 'c5', id: 'hy' })}${panelH('Monthly returns heatmap', { cls: 'c7', id: 'hm', flush: true })}${panelH('Drawdown from running peak & rolling 63-day volatility', { cls: 'c12', id: 'hd' })}</div>`;
    wireSecSearch(pg, nid => { id = nid; draw(); });
    const yrs = {}; const months = {}; s.d.forEach((t, i) => { const d = new Date(t); const y = d.getUTCFullYear(), m = d.getUTCMonth(); yrs[y] = i; months[y * 12 + m] = i; });
    const yk = Object.keys(yrs).map(Number).sort(); const yret = yk.slice(1).map(y => ({ y, v: (s.c[yrs[y]] / s.c[yrs[y - 1]] - 1) * 100, ytd: y === new Date(END).getUTCFullYear() }));
    const rets = []; for (let i = 1; i < s.c.length; i++) rets.push({ t: s.d[i], r: (s.c[i] / s.c[i - 1] - 1) * 100 }); const sorted = rets.slice().sort((a, b) => a.r - b.r); const st = seriesStats(s.c);
    $('#hs', pg).innerHTML = `<dl class="kv" style="margin:0">${[['Period', `${fd(s.d[0])} – ${fd(s.d[s.d.length - 1])}`], ['Total return', pc(st.ret, 1)], ['CAGR', pc(st.cagr)], ['Ann. volatility', nf(st.vol, 1) + '%'], ['Max drawdown', pc(st.dd, 1)], ['Return / vol', nf(st.sharpe, 2)], ['Best day', `${pc(sorted[sorted.length - 1].r)} · ${fd(sorted[sorted.length - 1].t)}`], ['Worst day', `${pc(sorted[0].r)} · ${fd(sorted[0].t)}`], ['Positive days', nf(rets.filter(r => r.r > 0).length / rets.length * 100, 1) + '%'], ['Observations', nf(s.c.length, 0)]].map(([k, v]) => `<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="note" style="margin-top:6px">${simB()} Price-only series; dividends are not reinvested. CAGR uses 252 observations per year.</div>`;
    xyChartBars($('#hy', pg), yret.map(r => ({ x: String(r.y) + (r.ytd ? ' YTD' : ''), y: r.v })));
    const mm = []; for (const y of yk) { const row = { y, m: [] }; for (let m = 0; m < 12; m++) { const k = y * 12 + m, pk = k - 1; row.m.push(months[k] != null && months[pk] != null ? (s.c[months[k]] / s.c[months[pk]] - 1) * 100 : null); } mm.push(row); }
    const sc = Math.max(...mm.flatMap(r => r.m).filter(v => v != null).map(Math.abs), 1); const avg = Array.from({ length: 12 }, (_, m) => { const v = mm.map(r => r.m[m]).filter(x => x != null); return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null; });
    $('#hm', pg).innerHTML = `<div class="tw"><table class="t dense" style="font-size:11.5px"><thead><tr><th>Year</th>${['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'].map(m => `<th class="r">${m}</th>`).join('')}</tr></thead><tbody>${mm.slice().reverse().map(r => `<tr><td>${r.y}</td>${r.m.map(v => `<td class="r" style="${v == null ? '' : heatBg(v, sc)}">${v == null ? '' : nf(v, 1)}</td>`).join('')}</tr>`).join('')}<tr><td><b>Avg</b></td>${avg.map(v => `<td class="r" style="${v == null ? '' : heatBg(v, sc)}"><b>${v == null ? '' : nf(v, 1)}</b></td>`).join('')}</tr></tbody></table></div>`;
    new TChart($('#hd', pg).appendChild(document.createElement('div')), { dates: s.d, zoom: true, panes: [{ h: 170, fmt: v => fv(o, v), series: [{ key: 'p', label: o.tk, color: 'var(--s1)', values: s.c }] }, { h: 120, title: 'Drawdown %', fmt: v => nf(v, 0) + '%', series: [{ key: 'd', label: 'Drawdown', color: 'var(--dn)', values: drawdown(s.c), type: 'area' }] }, { h: 100, title: 'Rolling 63D volatility, annualised %', fmt: v => nf(v, 0) + '%', series: [{ key: 'v', label: 'Volatility', color: 'var(--s4)', values: rollVol(s.c, 63) }] }] });
  };
  draw();
};
function xyChartBars(el, rows) {
  const W = Math.max(260, el.clientWidth || 400), H = 30 + rows.length * 22, L = 64, R = 56; const mx = Math.max(...rows.map(r => Math.abs(r.y)), 1); const x0 = L + (W - L - R) / 2 * (rows.some(r => r.y < 0) ? 1 : 0); const sc = (W - L - R) / (rows.some(r => r.y < 0) ? 2 : 1) / mx;
  el.innerHTML = `<svg viewBox="0 0 ${W} ${H}" width="100%" height="${H}" role="img" aria-label="Calendar-year returns"><line x1="${x0}" x2="${x0}" y1="6" y2="${H - 6}" style="stroke:var(--line2)"/>${rows.map((r, i) => { const y = 10 + i * 22, w = Math.abs(r.y) * sc; return `<text x="${L - 8}" y="${y + 12}" text-anchor="end" style="fill:var(--fg2);font:11px var(--f-num)">${esc(r.x)}</text><rect x="${r.y >= 0 ? x0 : x0 - w}" y="${y + 2}" width="${Math.max(1, w)}" height="14" rx="2" style="fill:var(${r.y >= 0 ? '--up' : '--dn'});opacity:.75"/><text x="${r.y >= 0 ? x0 + w + 4 : x0 - w - 4}" y="${y + 13}" text-anchor="${r.y >= 0 ? 'start' : 'end'}" style="fill:var(--fg);font:11px var(--f-num)">${pc(r.y, 1)}</text>`; }).join('')}</svg>`;
}

/* ---------- Model Portfolios ---------- */
PAGES.models = (pg, mid) => {
  let m = S.models.find(x => x.id === mid) || S.models[0]; let range = '5Y', ch = null;
  pg.innerHTML = hdr('models', 'Target-weight model portfolios built from ETFs, back-tested with monthly rebalancing against a benchmark. Illustrative only — not investment advice.', `<button class="btn pri" id="mn">New model</button>`) + `<div class="split"><section class="panel"><div class="lst" id="ml"></div></section><div id="me" style="display:flex;flex-direction:column;gap:10px;min-width:0"></div></div>`;
  const drawL = () => $('#ml', pg).innerHTML = S.models.map(x => `<button class="li ${m && x.id === m.id ? 'on' : ''}" data-m="${x.id}"><b>${esc(x.name)}</b><small>${Object.keys(x.w).length} holdings · bench ${esc(BY[x.bench]?.tk)}</small></button>`).join('');
  const drawE = () => {
    const e = $('#me', pg); if (!m) { e.innerHTML = '<div class="empty">No models.</div>'; return; } const tot = Object.values(m.w).reduce((a, b) => a + b, 0);
    e.innerHTML = `<section class="panel"><header class="ph"><input class="inp sm" id="mnm" value="${esc(m.name)}" aria-label="Model name" style="font-weight:600;min-width:220px"><span class="pm"><label class="row note">Benchmark <select class="inp sm" id="mb">${['IX.SPX', 'ET.IWB', 'ET.AGG', 'ET.IWD', 'ET.IWF'].map(id => `<option value="${id}" ${id === m.bench ? 'selected' : ''}>${BY[id].tk}</option>`).join('')}</select></label><button class="btn sm dng" id="mdel">Delete</button></span></header><div class="tbar">${secSearch('Add ETF or stock…', ['etf', 'equity'])}<span class="note">Weights total <b class="${Math.abs(tot - 100) < .01 ? 'up' : 'dn'}">${nf(tot, 1)}%</b>${Math.abs(tot - 100) >= .01 ? ' — back-test normalises to 100%' : ''}</span></div><div class="tw"><table class="t dense"><thead><tr><th>Holding</th><th>Category</th><th class="r">Target %</th><th class="r">1Y</th><th></th></tr></thead><tbody>${Object.entries(m.w).map(([id, w]) => `<tr><td>${lnk(id)}<div class="sub">${esc(BY[id].name)}</div></td><td><span class="sub">${esc(BY[id].cat || BY[id].sector || BY[id].cls)}</span></td><td class="r"><input class="inp sm" type="number" min="0" max="100" step="0.5" value="${w}" data-w="${id}" style="width:80px;text-align:right" aria-label="Target weight"></td><td class="r ${cls(perf(id, '1Y'))}">${pc(perf(id, '1Y'))}</td><td><button class="btn sm ghost" data-rw="${id}">Remove</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><header class="ph"><span class="pt">Back-test vs. ${esc(BY[m.bench].tk)}</span><span class="pm">${seg('mr', ['1Y', '3Y', '5Y', '10Y'], range)}</span></header><div class="pb"><div id="mc"></div><div class="kv" id="ms" style="margin-top:8px"></div><div class="note" style="margin-top:6px">Monthly rebalancing to target, USD, price returns, no costs or taxes. ${simB()}</div></div></section>`;
    const bt = backtest(m.w, range, 'M'); if (bt) { const bs = align([m.bench], periodStart(range), END, 'D', 'USD'); const bv = bt.dates.map(t => { const i = bsLE(bs.dates, t); return i < 0 ? null : bs.cols[0][i]; }); ch = new TChart($('#mc', e), { dates: bt.dates, panes: [{ h: 250, rebase: true, fmt: pctAx, series: [{ key: 'm', label: m.name, color: 'var(--s2)', values: bt.vals, type: 'area' }, { key: 'b', label: BY[m.bench].tk, color: 'var(--s8)', values: bv }] }] }); const a = seriesStats(bt.vals), b = seriesStats(bv); $('#ms', e).innerHTML = [['Total return', pc(a.ret), pc(b.ret)], ['CAGR', pc(a.cagr), pc(b.cagr)], ['Volatility', nf(a.vol, 1) + '%', nf(b.vol, 1) + '%'], ['Max drawdown', pc(a.dd), pc(b.dd)], ['Return / vol', nf(a.sharpe, 2), nf(b.sharpe, 2)]].map(([k, x, y]) => `<div><dt>${k}</dt><dd>${x} <span class="muted">vs ${y}</span></dd></div>`).join(''); } else $('#mc', e).innerHTML = '<div class="empty">Add holdings with weights to back-test.</div>';
    $('#mnm', e).onchange = ev => { m.name = ev.target.value.trim() || m.name; save(); drawL(); }; $('#mb', e).onchange = ev => { m.bench = ev.target.value; save(); drawE(); drawL(); };
    $('#mdel', e).onclick = () => confirmBox('Delete this model? Clients assigned to it will lose their target.', () => { S.models = S.models.filter(x => x !== m); m = S.models[0]; save(); drawL(); drawE(); });
    onSeg(e, 'mr', v => { range = v; drawE(); });
    on(e, 'change', '[data-w]', (ev, b) => { m.w[b.dataset.w] = Math.max(0, +b.value || 0); save(); drawE(); }); on(e, 'click', '[data-rw]', (ev, b) => { delete m.w[b.dataset.rw]; save(); drawE(); drawL(); });
    wireSecSearch(e, id => { if (m.w[id] != null) return; m.w[id] = 5; save(); drawE(); drawL(); });
  };
  $('#mn', pg).onclick = () => { m = { id: uid(), name: 'New model', bench: 'IX.SPX', w: { 'ET.IWB': 60, 'ET.AGG': 40 } }; S.models.push(m); save(); drawL(); drawE(); };
  on(pg, 'click', '[data-m]', (e, b) => { m = S.models.find(x => x.id === b.dataset.m); drawL(); drawE(); });
  drawL(); drawE();
};

/* ---------- Client Portfolios ---------- */
PAGES.clients = (pg, cid) => {
  let c = S.clients.find(x => x.id === cid) || S.clients[0];
  pg.innerHTML = hdr('clients', 'Client accounts measured against their assigned model. Drift and rebalancing trades are calculated from simulated closes. Illustrative only.', `<button class="btn pri" id="cn">New client</button>`) + `<div class="split"><section class="panel"><div class="lst" id="cl"></div></section><div id="ce" style="display:flex;flex-direction:column;gap:10px;min-width:0"></div></div>`;
  const val = x => { const r = holdingsValue(x.holdings); return { rows: r, tot: r.reduce((a, b) => a + b.mv, 0) + (x.cash || 0) }; };
  const drawL = () => $('#cl', pg).innerHTML = S.clients.map(x => `<button class="li ${c && x.id === c.id ? 'on' : ''}" data-c="${x.id}"><b>${esc(x.name)}</b><small>$${nf(val(x).tot, 0)} · ${esc(S.models.find(m => m.id === x.model)?.name || 'No model')}</small></button>`).join('') || '<div class="empty">No clients yet.</div>';
  const drawE = () => {
    const e = $('#ce', pg); if (!c) { e.innerHTML = '<div class="empty"><b>No client selected</b></div>'; return; }
    const m = S.models.find(x => x.id === c.model); const { rows, tot } = val(c); const tw = m ? Object.values(m.w).reduce((a, b) => a + b, 0) : 0;
    const ids = [...new Set([...rows.map(r => r.o.id), ...(m ? Object.keys(m.w) : [])])];
    const drift = ids.map(id => { const r = rows.find(x => x.o.id === id); const cur = r ? r.mv / tot * 100 : 0; const tgt = m && m.w[id] ? m.w[id] / tw * 100 : 0; const px = quote(id).last; const tradeUSD = (tgt - cur) / 100 * tot; return { id, cur, tgt, d: cur - tgt, trade: tradeUSD, sh: tradeUSD / px }; });
    e.innerHTML = `<section class="panel"><header class="ph"><input class="inp sm" id="cnm" value="${esc(c.name)}" aria-label="Client name" style="font-weight:600;min-width:260px"><span class="pm"><label class="row note">Model <select class="inp sm" id="cm">${S.models.map(x => `<option value="${x.id}" ${x.id === c.model ? 'selected' : ''}>${esc(x.name)}</option>`).join('')}</select></label><button class="btn sm dng" id="cdel">Delete</button></span></header><div class="pb"><dl class="kv" style="margin:0"><div><dt>Account value</dt><dd>$${nf(tot, 0)}</dd></div><div><dt>Cash</dt><dd><input class="inp sm" type="number" id="ccash" value="${c.cash || 0}" style="width:110px" aria-label="Cash"></dd></div><div><dt>Day change</dt><dd class="${cls(rows.reduce((a, b) => a + b.day, 0))}">${sgn(rows.reduce((a, b) => a + b.day, 0), 0)}</dd></div><div><dt>Max |drift|</dt><dd>${nf(Math.max(0, ...drift.map(d => Math.abs(d.d))), 1)} pts</dd></div></dl></div></section>
      <section class="panel"><header class="ph"><span class="pt">Holdings, drift & rebalancing trades</span></header><div class="tbar">${secSearch('Add holding…', ['etf', 'equity'])}</div><div class="tw"><table class="t dense"><thead><tr><th>Holding</th><th class="r">Qty</th><th class="r">Value</th><th class="r">Current %</th><th class="r">Target %</th><th class="r">Drift</th><th class="r">Trade to target</th></tr></thead><tbody>${drift.map(d => { const r = rows.find(x => x.o.id === d.id); return `<tr><td>${lnk(d.id)}</td><td class="r"><input class="inp sm" type="number" min="0" step="any" value="${r ? r.h.qty : 0}" data-cq="${d.id}" style="width:80px;text-align:right" aria-label="Quantity"></td><td class="r">${r ? nf(r.mv, 0) : '0'}</td><td class="r">${nf(d.cur, 1)}</td><td class="r">${nf(d.tgt, 1)}</td><td class="r"><span class="badge ${Math.abs(d.d) > 5 ? 'bad' : Math.abs(d.d) > 2 ? 'sim' : 'ok'}">${sgn(d.d, 1)} pts</span></td><td class="r ${cls(d.trade)}">${Math.abs(d.trade) < 1 ? '—' : `${d.trade > 0 ? 'Buy' : 'Sell'} ${nf(Math.abs(d.sh), 0)} sh ($${nf(Math.abs(d.trade), 0)})`}</td></tr>`; }).join('')}</tbody></table></div><div class="pf"><span>Drift bands: ≤2 pts within tolerance, 2–5 pts watch, &gt;5 pts rebalance.</span><span>Trades size each line to the model target at the latest simulated close; no orders are sent.</span></div></section>`;
    $('#cnm', e).onchange = ev => { c.name = ev.target.value.trim() || c.name; save(); drawL(); }; $('#cm', e).onchange = ev => { c.model = ev.target.value; save(); drawE(); drawL(); }; $('#ccash', e).onchange = ev => { c.cash = +ev.target.value || 0; save(); drawE(); drawL(); };
    $('#cdel', e).onclick = () => confirmBox(`Delete ${c.name}?`, () => { S.clients = S.clients.filter(x => x !== c); c = S.clients[0]; save(); drawL(); drawE(); });
    on(e, 'change', '[data-cq]', (ev, b) => { const h = c.holdings.find(x => x.sid === b.dataset.cq); const q = Math.max(0, +b.value || 0); if (h) h.qty = q; else c.holdings.push({ sid: b.dataset.cq, qty: q }); c.holdings = c.holdings.filter(x => x.qty > 0); save(); drawE(); drawL(); });
    wireSecSearch(e, id => { if (!c.holdings.find(h => h.sid === id)) c.holdings.push({ sid: id, qty: 10 }); save(); drawE(); drawL(); });
  };
  $('#cn', pg).onclick = () => { c = { id: uid(), name: 'New client', model: S.models[0]?.id, cash: 0, holdings: [] }; S.clients.push(c); save(); drawL(); drawE(); };
  on(pg, 'click', '[data-c]', (e, b) => { c = S.clients.find(x => x.id === b.dataset.c); drawL(); drawE(); });
  drawL(); drawE();
};

/* ---------- Reports ---------- */
function reportHTML(r) {
  const at = `${simB('SIM EOD')} Data as of ${fd(END)} · generated ${fdt(Date.now())}`; const md = []; let h = '';
  if (r.type === 'tear') { const o = BY[r.subject], q = quote(o.id); h = `<h2>${esc(o.name)} (${esc(o.tk)}) — tear sheet</h2><div class="note">${at}</div><h3>Snapshot</h3>${secStats(o, q)}<h3>Performance</h3><div class="tw"><table class="t dense"><thead><tr>${['1M', '3M', 'YTD', '1Y', '3Y'].map(k => `<th class="r">${k}</th>`).join('')}</tr></thead><tbody><tr>${['1M', '3M', 'YTD', '1Y', '3Y'].map(k => `<td class="r ${cls(perf(o.id, k))}">${fper(o, perf(o.id, k))}</td>`).join('')}</tr></tbody></table></div><div data-rchart="${o.id}"></div><h3>Analyst notes</h3>${S.notes.filter(n => n.links.includes(o.id)).map(n => `<p><b>${esc(n.title)}</b><br>${esc(n.body).replace(/\n/g, '<br>')}</p>`).join('') || '<p class="muted">No linked notes.</p>'}`; md.push(`# ${o.name} (${o.tk}) — tear sheet`, `Simulated data as of ${fd(END)}`, `Last: ${fv(o, q.last)} (${q.pct != null ? pc(q.pct) : fchg(o, q)})`, ...['1M', '3M', 'YTD', '1Y', '3Y'].map(k => `- ${k}: ${fper(o, perf(o.id, k))}`)); }
  if (r.type === 'wrap') { const ids = ['IX.SPX', 'IX.NDX', 'IX.RUT', 'IX.UKX', 'IX.DAX', 'IX.NKY', 'YD.US10', 'FX.DXY', 'CM.CO1', 'CM.GC1'].filter(realOK); h = `<h2>Market wrap — ${fd(END)}</h2><div class="note">${at}</div><h3>Cross-asset</h3><div class="tw"><table class="t dense"><thead><tr><th>Instrument</th><th class="r">Last</th><th class="r">1D</th><th class="r">1M</th><th class="r">YTD</th></tr></thead><tbody>${ids.map(id => { const o = BY[id], q = quote(id); return `<tr><td>${esc(o.name)}</td><td class="r">${fv(o, q.last)}</td><td class="r ${cls(q.chg)}">${o.type === 'yield' ? bpf(q.bp) : pc(q.pct)}</td><td class="r">${fper(o, perf(id, '1M'))}</td><td class="r">${fper(o, perf(id, 'YTD'))}</td></tr>`; }).join('')}</tbody></table></div><h3>Sectors (1D)</h3><div data-rsec="1"></div><h3>Briefs</h3>${newsFeed().slice(0, 6).map(n => `<p>• ${esc(n.title)}</p>`).join('')}`; md.push(`# Market wrap — ${fd(END)}`, 'Simulated data', ...ids.map(id => { const o = BY[id], q = quote(id); return `- ${o.name}: ${fv(o, q.last)} (${o.type === 'yield' ? bpf(q.bp) : pc(q.pct)})`; })); }
  if (r.type === 'port') { const rows = holdingsValue(S.portfolio.holdings); const tot = rows.reduce((a, b) => a + b.mv, 0); h = `<h2>${esc(S.portfolio.name)} — summary</h2><div class="note">${at}</div><h3>Holdings</h3><div class="tw"><table class="t dense"><thead><tr><th>Holding</th><th class="r">Value</th><th class="r">Weight</th><th class="r">1D</th><th class="r">1Y</th></tr></thead><tbody>${rows.map(r => `<tr><td>${esc(r.o.tk)} — ${esc(r.o.name)}</td><td class="r">$${nf(r.mv, 0)}</td><td class="r">${nf(r.mv / tot * 100, 1)}%</td><td class="r ${cls(r.q.pct)}">${pc(r.q.pct)}</td><td class="r">${pc(perf(r.o.id, '1Y'))}</td></tr>`).join('')}</tbody></table></div><p>Total value <b>$${nf(tot, 0)}</b>.</p>`; md.push(`# ${S.portfolio.name} — summary`, `Total $${nf(tot, 0)}`, ...rows.map(r => `- ${r.o.tk}: $${nf(r.mv, 0)} (${nf(r.mv / tot * 100, 1)}%)`)); }
  if (r.type === 'wl') { const w = S.watchlists.find(x => x.id === r.subject) || S.watchlists[0]; h = `<h2>Watchlist review — ${esc(w?.name || '')}</h2><div class="note">${at}</div><div class="tw"><table class="t dense"><thead><tr><th>Instrument</th><th class="r">Last</th><th class="r">1D</th><th class="r">1M</th><th class="r">1Y</th></tr></thead><tbody>${(w?.items || []).filter(id => BY[id]).map(id => { const o = BY[id], q = quote(id); return `<tr><td>${esc(o.tk)} — ${esc(o.name)}</td><td class="r">${fv(o, q.last)}</td><td class="r ${cls(q.chg)}">${o.type === 'yield' ? bpf(q.bp) : q.pct != null ? pc(q.pct) : fchg(o, q)}</td><td class="r">${fper(o, perf(id, '1M'))}</td><td class="r">${fper(o, perf(id, '1Y'))}</td></tr>`; }).join('')}</tbody></table></div>`; md.push(`# Watchlist review — ${w?.name}`); }
  h += `<p class="note">Prepared with Superfinancials. All market values are simulated and are not suitable for investment decisions.</p>`;
  return { h, md: md.join('\n') + '\n\n_All values simulated._' };
}
PAGES.reports = (pg, rid) => {
  let cur = S.reports.find(r => r.id === rid) || null;
  const TYPES = { tear: 'Security tear sheet', wrap: 'Market wrap', port: 'Portfolio summary', wl: 'Watchlist review' };
  pg.innerHTML = hdr('reports', 'Generate reports from live workspace data. Reports re-compute from the latest data each time you open them.', '') + `<div class="split"><section class="panel"><header class="ph"><span class="pt">New report</span></header><form class="pb" id="rf" style="display:flex;flex-direction:column;gap:8px"><label class="f"><span>Type</span><select class="inp" id="rt">${Object.entries(TYPES).map(([k, v]) => `<option value="${k}">${v}</option>`).join('')}</select></label><div id="rsub"></div><button class="btn pri" type="submit">Generate report</button></form><header class="ph"><span class="pt">Saved reports</span></header><div class="lst" id="rl"></div></section><section class="panel" id="rv"></section></div>`;
  let subj = state.ctx || 'EQ.AAPL';
  const drawSub = () => { const t = $('#rt', pg).value; $('#rsub', pg).innerHTML = t === 'tear' ? `<label class="f"><span>Security</span></label><div class="row"><span class="chip on" id="rsc">${esc(BY[subj].tk)}</span>${secSearch('Change…')}</div>` : t === 'wl' ? `<label class="f"><span>Watchlist</span><select class="inp" id="rw">${S.watchlists.map(w => `<option value="${w.id}">${esc(w.name)}</option>`).join('')}</select></label>` : ''; wireSecSearch($('#rsub', pg), id => { subj = id; $('#rsc', pg).textContent = BY[id].tk; }); };
  $('#rt', pg).onchange = drawSub; drawSub();
  const drawL = () => $('#rl', pg).innerHTML = S.reports.map(r => `<button class="li ${cur && r.id === cur.id ? 'on' : ''}" data-r="${r.id}"><b>${esc(r.title)}</b><small>${fdt(r.created)}</small></button>`).join('') || '<div class="note" style="padding:10px">No saved reports.</div>';
  const drawV = () => {
    const v = $('#rv', pg); if (!cur) { v.innerHTML = '<div class="empty"><b>Choose or generate a report</b>Pick a type on the left and press Generate.</div>'; return; }
    const out = reportHTML(cur); v.innerHTML = `<header class="ph"><span class="pt">${esc(cur.title)}</span><span class="pm"><button class="btn sm" id="rcp">Copy as Markdown</button><button class="btn sm" id="rdk">Add to presentation</button><button class="btn sm dng" id="rdl">Delete</button></span></header><div class="pb"><article class="report">${out.h}</article></div>`;
    $$('[data-rchart]', v).forEach(el => { const id = el.dataset.rchart; const al = align([id], periodStart('1Y'), END); new TChart(el, { dates: al.dates, panes: [{ h: 200, series: [{ key: id, label: BY[id].tk + ' · 1Y', color: 'var(--s1)', values: al.cols[0], type: 'area' }], fmt: x => fv(BY[id], x) }] }); });
    $$('[data-rsec]', v).forEach(el => sectorHeat(el, '1D'));
    $('#rcp', v).onclick = () => copyText(out.md); $('#rdl', v).onclick = () => confirmBox('Delete this report?', () => { S.reports = S.reports.filter(r => r !== cur); cur = null; save(); drawL(); drawV(); });
    $('#rdk', v).onclick = e => popMenu(e.currentTarget, S.decks.map(d => ({ label: d.name, fn: () => { d.slides.push({ id: uid(), type: cur.type === 'tear' ? 'security' : 'snapshot', title: cur.title, sid: cur.subject }); save(); toast(`Added a slide to ${d.name}`); } })));
  };
  $('#rf', pg).onsubmit = e => { e.preventDefault(); const t = $('#rt', pg).value; const s = t === 'tear' ? subj : t === 'wl' ? $('#rw', pg).value : null; const title = t === 'tear' ? `${BY[subj].tk} tear sheet` : t === 'wl' ? `Watchlist review — ${S.watchlists.find(w => w.id === s)?.name}` : t === 'port' ? 'Portfolio summary' : `Market wrap ${fd(END)}`; cur = { id: uid(), type: t, subject: s, title, created: Date.now() }; S.reports.unshift(cur); save(); drawL(); drawV(); };
  on(pg, 'click', '[data-r]', (e, b) => { cur = S.reports.find(r => r.id === b.dataset.r); drawL(); drawV(); });
  drawL(); drawV();
};

/* ---------- Research Presentations ---------- */
function slideHTML(sl, deck, i) {
  let body = '';
  if (sl.type === 'title') body = `<div style="display:flex;flex-direction:column;justify-content:center;height:100%;gap:8px"><div class="note">${esc(USER.name)} · ${fd(Date.now())}</div><h2 style="font-size:clamp(22px,3.6vw,44px)">${esc(sl.title)}</h2><div style="color:var(--fg2);font-size:clamp(13px,1.6vw,18px)">${esc(sl.sub || '')}</div></div>`;
  else if (sl.type === 'snapshot') body = `<div class="tw"><table class="t dense"><thead><tr><th>Market</th><th class="r">Last</th><th class="r">1D</th><th class="r">YTD</th></tr></thead><tbody>${['IX.SPX', 'IX.NDX', 'IX.SX5E', 'IX.NKY', 'YD.US10', 'FX.EURUSD', 'CM.CO1', 'CM.GC1'].map(id => { const o = BY[id], q = quote(id); return `<tr><td>${esc(o.name)}</td><td class="r">${fv(o, q.last)}</td><td class="r ${cls(q.chg)}">${o.type === 'yield' ? bpf(q.bp) : pc(q.pct)}</td><td class="r">${fper(o, perf(id, 'YTD'))}</td></tr>`; }).join('')}</tbody></table></div>`;
  else if (sl.type === 'graph' || sl.type === 'security') body = `<div data-sch="${sl.id}"></div>`;
  else if (sl.type === 'note') { const n = S.notes.find(x => x.id === sl.note); body = n ? `<div style="white-space:pre-wrap;font-size:clamp(12px,1.4vw,16px);line-height:1.6">${esc(n.body)}</div><div class="row" style="margin-top:8px">${n.links.map(l => `<span class="chip static">${esc(BY[l]?.tk)}</span>`).join('')}</div>` : '<div class="muted">Linked note was deleted.</div>'; }
  return `<div class="slide">${sl.type !== 'title' ? `<h2>${esc(sl.title)}</h2>` : ''}<div class="sbody">${body}</div><div class="sfoot"><span>${esc(deck.name)} · Simulated data as of ${fd(END)}</span><span>${i + 1} / ${deck.slides.length}</span></div></div>`;
}
function mountSlideCharts(root, deck) { $$('[data-sch]', root).forEach(el => { const sl = deck.slides.find(s => s.id === el.dataset.sch); let ids; if (sl.type === 'graph') { const g = S.graphs.find(x => x.id === sl.graph); if (!g) { el.innerHTML = '<div class="muted">Saved graph was deleted.</div>'; return; } ids = g.cfg.ids; const { cfg } = buildCompare(ids, { range: g.cfg.range || '1Y', mode: g.cfg.mode, h: Math.max(140, el.closest('.slide').clientHeight * .55) }); new TChart(el, cfg); } else { ids = [sl.sid]; const { cfg } = buildCompare(ids, { range: '1Y', mode: 'abs', h: Math.max(140, el.closest('.slide').clientHeight * .55) }); new TChart(el, cfg); } }); }
PAGES.decks = (pg, did) => {
  let d = S.decks.find(x => x.id === did) || S.decks[0]; let si = 0;
  pg.innerHTML = hdr('decks', 'Build presentations from saved graphs, notes and live market snapshots. Slides refresh from the latest data when opened.', `<button class="btn pri" id="dn">New presentation</button>`) + `<div class="split"><section class="panel"><div class="lst" id="dl"></div></section><div id="de" style="min-width:0"></div></div>`;
  const drawL = () => $('#dl', pg).innerHTML = S.decks.map(x => `<button class="li ${d && x.id === d.id ? 'on' : ''}" data-d="${x.id}"><b>${esc(x.name)}</b><small>${x.slides.length} slides</small></button>`).join('') || '<div class="empty">No presentations.</div>';
  const drawE = () => {
    const e = $('#de', pg); if (!d) { e.innerHTML = '<div class="empty"><b>No presentation selected</b></div>'; return; } si = clamp(si, 0, Math.max(0, d.slides.length - 1)); const sl = d.slides[si];
    e.innerHTML = `<section class="panel"><header class="ph"><input class="inp sm" id="dnm" value="${esc(d.name)}" aria-label="Presentation name" style="font-weight:600;min-width:240px"><span class="pm"><button class="btn sm pri" id="dpr">Present</button><button class="btn sm dng" id="ddl">Delete</button></span></header><div class="pb" style="display:grid;grid-template-columns:200px minmax(0,1fr);gap:10px"><div class="thumbs">${d.slides.map((s, i) => `<div class="thumb ${i === si ? 'on' : ''}" data-si="${i}" role="button" tabindex="0"><span>${i + 1}. ${esc(s.title || s.type)}</span><span class="row" style="gap:2px"><button class="btn sm ghost" data-su="${i}" aria-label="Move up">↑</button><button class="btn sm ghost" data-sx="${i}" aria-label="Delete slide">×</button></span></div>`).join('')}<div class="row"><select class="inp sm" id="dst" aria-label="Slide type" style="flex:1"><option value="title">Title</option><option value="snapshot">Market snapshot</option>${S.graphs.map(g => `<option value="graph:${g.id}">Graph: ${esc(g.name)}</option>`).join('')}${S.notes.map(n => `<option value="note:${n.id}">Note: ${esc(n.title)}</option>`).join('')}<option value="security">Security chart (current)</option></select><button class="btn sm" id="dad">Add</button></div></div><div>${sl ? `<label class="f" style="margin-bottom:6px"><span>Slide title</span><input class="inp sm" id="dtt" value="${esc(sl.title || '')}"></label>${slideHTML(sl, d, si)}` : '<div class="empty">Add a slide.</div>'}</div></div></section>`;
    mountSlideCharts(e, d);
    $('#dnm', e).onchange = ev => { d.name = ev.target.value.trim() || d.name; save(); drawL(); }; if ($('#dtt', e)) $('#dtt', e).onchange = ev => { sl.title = ev.target.value; save(); drawE(); };
    $('#ddl', e).onclick = () => confirmBox('Delete this presentation?', () => { S.decks = S.decks.filter(x => x !== d); d = S.decks[0]; save(); drawL(); drawE(); });
    $('#dad', e).onclick = () => { const v = $('#dst', e).value; const [t, ref] = v.split(':'); const s = { id: uid(), type: t, title: t === 'title' ? 'New section' : t === 'snapshot' ? 'Market snapshot' : t === 'graph' ? S.graphs.find(g => g.id === ref)?.name : t === 'note' ? S.notes.find(n => n.id === ref)?.title : `${BY[state.ctx || 'IX.SPX'].tk} — 1Y`, graph: t === 'graph' ? ref : undefined, note: t === 'note' ? ref : undefined, sid: t === 'security' ? (state.ctx || 'IX.SPX') : undefined }; d.slides.push(s); si = d.slides.length - 1; save(); drawE(); drawL(); };
    $('#dpr', e).onclick = () => present(d, si);
    on(e, 'click', '[data-si]', (ev, b) => { if (ev.target.closest('button')) return; si = +b.dataset.si; drawE(); });
    on(e, 'click', '[data-su]', (ev, b) => { const i = +b.dataset.su; if (i) { [d.slides[i - 1], d.slides[i]] = [d.slides[i], d.slides[i - 1]]; si = i - 1; save(); drawE(); } });
    on(e, 'click', '[data-sx]', (ev, b) => { d.slides.splice(+b.dataset.sx, 1); save(); drawE(); drawL(); });
  };
  $('#dn', pg).onclick = () => { d = { id: uid(), name: 'New presentation', slides: [{ id: uid(), type: 'title', title: 'New presentation', sub: '' }] }; S.decks.push(d); si = 0; save(); drawL(); drawE(); };
  on(pg, 'click', '[data-d]', (e, b) => { d = S.decks.find(x => x.id === b.dataset.d); si = 0; drawL(); drawE(); });
  drawL(); drawE();
};
function present(d, start = 0) {
  let i = start; const w = document.createElement('div'); w.className = 'mw'; w.style.background = 'var(--bg)'; w.setAttribute('role', 'dialog'); w.setAttribute('aria-label', 'Presentation');
  const draw = () => { w.innerHTML = `<div style="width:min(1200px,100%);display:flex;flex-direction:column;gap:10px">${slideHTML(d.slides[i], d, i)}<div class="row" style="justify-content:center"><button class="btn" data-pv>← Previous</button><button class="btn" data-nx>Next →</button><button class="btn ghost" data-ex>Exit (Esc)</button></div></div>`; mountSlideCharts(w, d); };
  const k = e => { if (e.key === 'ArrowRight' || e.key === ' ') { i = Math.min(d.slides.length - 1, i + 1); draw(); } else if (e.key === 'ArrowLeft') { i = Math.max(0, i - 1); draw(); } else if (e.key === 'Escape') close(); };
  const close = () => { w.remove(); document.removeEventListener('keydown', k); if (document.fullscreenElement) document.exitFullscreen().catch(() => { }); };
  w.addEventListener('click', e => { if (e.target.closest('[data-nx]')) { i = Math.min(d.slides.length - 1, i + 1); draw(); } if (e.target.closest('[data-pv]')) { i = Math.max(0, i - 1); draw(); } if (e.target.closest('[data-ex]')) close(); });
  document.addEventListener('keydown', k); document.body.append(w); draw(); if (w.requestFullscreen) w.requestFullscreen().catch(() => { });
}

