function chk(c) { return (c.words && c.words.length ? `<span class="aichk bad" title="Wording that may read as advice, prediction or loaded language: ${esc(c.words.join(', '))}">Review wording</span> ` : '') + (c.total ? (c.bad.length ? `<span class="aichk bad" title="Not found in the screen's data: ${esc(c.bad.join(', '))}">Check ${esc(c.bad.join(', '))}</span>` : `<span class="aichk ok" title="Every figure was found in the screen's data">✓ verified</span>`) : ''); }
