  if ($('#aiShare', el)) $('#aiShare', el).onclick = () => { const cur = describeCurrent(); shareModal({ kind: 'insight', title: `AI ${r.mode === 'explain' ? 'explanation' : 'insight'} · ${cur.title}`, route: cur.route, p: cur.p, payload: cur.payload || null, snap: r.mode === 'ask' ? 'Question: ' + r.q.slice(0, 160) : '', message: insightText(r) }); };
