/* =====================================================================
   Superfinancials — Market News: market intelligence edition
   Principle: separate what happened (facts), what the data suggests
   (hypotheses to test) and what remains unknown. Every insight carries
   the evidence and the rule that triggered it. No catalyst is ever
   invented: with no news provider connected, causes are "unconfirmed".
   ===================================================================== */
const NX = { st: { topic: 'All', ticker: null, q: '', type: 'All', mkts: [], sigs: [], rel: [], range: '5D', from: null, to: null, sort: 'newest', asof: null, tab: 'corr', show: 30 }, items: new Map(), days: new Map(), z: new Map(), open: new Set(), charts: new Set() };
const NX_D = () => series('IX.SPX').d;
const nxAsof = () => { const D = NX_D(); const t = NX.st.asof; return t && D.includes(t) ? t : D[D.length - 1]; };
const nxNext = t => { const D = NX_D(); const i = bsLE(D, t); return D[i + 1] ?? null; };
const nxPrevN = (t, k) => { const D = NX_D(); const i = bsLE(D, t); return D[Math.max(0, i - k)]; };
const isY = id => BY[id] && BY[id].type === 'yield';
const unitCh = (id, v) => v == null ? '—' : isY(id) ? bpf(v) : pc(v);
const zf = z => z == null ? '—' : nf(Math.abs(z), 1) + 'σ';

/* ---------- primitive measures (on each series' own calendar) ---------- */
function nxChg(id, t, k = 1) { const s = series(id); const i = bsLE(s.d, t); if (i < k || s.d[i] !== t) return null; return isY(id) ? (s.c[i] - s.c[i - k]) * 100 : (s.c[i] / s.c[i - k] - 1) * 100; }
function nxWin(id, t0, t1) { const a = valAt(id, t0), b = valAt(id, t1); if (a == null || b == null) return null; return isY(id) ? (b - a) * 100 : (b / a - 1) * 100; }
function nxZ(id, t) {
  const key = id + '|' + t; if (NX.z.has(key)) return NX.z.get(key);
  const s = series(id); const i = bsLE(s.d, t); let z = null;
  if (i > 62 && s.d[i] === t) { const ch = j => isY(id) ? (s.c[j] - s.c[j - 1]) * 100 : Math.log(s.c[j] / s.c[j - 1]) * 100; let m = 0, v = 0; const xs = []; for (let j = i - 60; j < i; j++) xs.push(ch(j)); m = xs.reduce((a, b) => a + b, 0) / xs.length; v = xs.reduce((a, b) => a + (b - m) ** 2, 0) / (xs.length - 1); const sd = Math.sqrt(v); z = sd > 0 ? (ch(i) - m) / sd : null; }
  NX.z.set(key, z); return z;
}
function nxVolX(id, t) { const s = series(id); if (!s.v) return null; const i = bsLE(s.d, t); if (i < 21 || s.d[i] !== t) return null; let a = 0; for (let j = i - 20; j < i; j++) a += s.v[j]; return s.v[i] / (a / 20); }
function nxRVPct(id, t) {
  const s = series(id); const i = bsLE(s.d, t); if (i < 290) return null; const ch = j => isY(id) ? (s.c[j] - s.c[j - 1]) : Math.log(s.c[j] / s.c[j - 1]);
  const rv = k => { let m = 0; for (let j = k - 19; j <= k; j++) m += ch(j); m /= 20; let v = 0; for (let j = k - 19; j <= k; j++) v += (ch(j) - m) ** 2; return Math.sqrt(v / 19); };
  const now = rv(i); let below = 0, n = 0; for (let k = i - 250; k < i; k += 2) { n++; if (rv(k) <= now) below++; } return { rv: now * Math.sqrt(252) * (isY(id) ? 100 : 100), pct: below / n * 100 };
}
function nxLvlPct(id, t) { const s = series(id); const i = bsLE(s.d, t); if (i < 252) return null; const x = s.c[i]; let b = 0; for (let j = i - 251; j <= i; j++) if (s.c[j] <= x) b++; return b / 252 * 100; }
function nxCorr(a, b, t, n) {
  const D = NX_D(); const e = bsLE(D, t); if (e - n < 1) return null; const ra = [], rb = [];
  const ch = (id, k) => { const v1 = valAt(id, D[k]), v0 = valAt(id, D[k - 1]); if (v1 == null || v0 == null) return null; return isY(id) ? v1 - v0 : Math.log(v1 / v0); };
  for (let k = e - n + 1; k <= e; k++) { const x = ch(a, k), y = ch(b, k); if (x != null && y != null && isFinite(x) && isFinite(y)) { ra.push(x); rb.push(y); } }
  if (ra.length < 10) return null; const mx = ra.reduce((p, q) => p + q, 0) / ra.length, my = rb.reduce((p, q) => p + q, 0) / rb.length; let sxy = 0, sx = 0, sy = 0; ra.forEach((x, i) => { sxy += (x - mx) * (rb[i] - my); sx += (x - mx) ** 2; sy += (rb[i] - my) ** 2; }); return sx && sy ? sxy / Math.sqrt(sx * sy) : null;
}
const mktOf = id => { const o = BY[id]; if (!o) return 'Equities'; if (o.type === 'crypto') return 'Crypto'; if (o.type === 'fx') return 'FX'; if (o.type === 'commodity') return 'Commodities'; if (o.type === 'yield' || o.type === 'bond' || o.type === 'econ') return 'Rates'; if (o.fi) return /yield|credit|investment-grade|convertible|em /i.test(o.cat + ' ' + o.name) ? 'Credit' : 'Rates'; if (/gold|oil|commodit/i.test(o.name)) return 'Commodities'; return 'Equities'; };
const relSets = () => { const w = new Set(S.watchlists.flatMap(l => l.items)); const p = new Set((S.portfolio?.holdings || []).map(h => h.sid)); return { w, p, s: new Set(S.nxSaved || []) }; };

/* ---------- earnings & macro schedules (simulated) ---------- */
function nxEarnDates(id) { const f = fund(id); const out = []; for (let k = 0; k < 4; k++) { let t = f.nextEarn - k * 91 * DAY; while ([0, 6].includes(new Date(t).getUTCDay())) t += DAY; out.push(t); } return out; }
function nxEarn(id, t) {
  const f = fund(id); const r = rng(hash('earn' + id + t)); const act = f.eps / 4 * (1 + (r() - .5) * .08); const s = (r() - .32) * .22; const cons = act / (1 + s * Math.sign(act || 1)); const surp = (act - cons) / Math.abs(cons) * 100;
  const rt = f.earnTime === 'Before open' ? t : nxNext(t); const done = rt != null && rt <= END;
  return { t, act, cons, surp, time: f.earnTime, rt, rx: done ? nxChg(id, rt) : null, bx: done ? nxChg('IX.SPX', rt) : null, zx: done ? nxZ(id, rt) : null };
}
function nxRelDate(o, d) { const x = new Date(d); let t = Date.UTC(x.getUTCFullYear(), x.getUTCMonth() + 1, o.freq === 'Q' ? 26 : 8 + hash(o.id) % 12); while ([0, 6].includes(new Date(t).getUTCDay())) t += DAY; return t; }
function nxReleases(o) { const s = series(o.id); const out = []; for (let i = Math.max(1, s.c.length - 8); i < s.c.length; i++) out.push({ t: nxRelDate(o, s.d[i]), i, v: s.c[i], p: s.c[i - 1] }); return out; }

/* ---------- one session: market context ---------- */
function nxDay(t) {
  if (NX.days.has(t)) return NX.days.get(t);
  const c = id => nxChg(id, t); const z = id => nxZ(id, t);
  const eq = EQ.map(o => ({ o, v: c(o.id), z: z(o.id), vx: nxVolX(o.id, t), mc: fund(o.id).mcap })).filter(x => x.v != null);
  const adv = eq.filter(x => x.v > 0).length; const ew = eq.reduce((a, x) => a + x.v, 0) / (eq.length || 1);
  const sec = SECTORS.map(o => ({ o, v: c(o.id), z: z(o.id) })).filter(x => x.v != null).sort((a, b) => b.v - a.v);
  const disp = sd => { const m = sd.reduce((a, b) => a + b, 0) / sd.length; return Math.sqrt(sd.reduce((a, b) => a + (b - m) ** 2, 0) / (sd.length - 1)); };
  const dNow = disp(sec.map(x => x.v)); const hist = []; for (let k = 1; k <= 60; k++) { const tt = nxPrevN(t, k); const xs = SECTORS.map(o => nxChg(o.id, tt)).filter(v => v != null); if (xs.length > 5) hist.push(disp(xs)); }
  const hm = hist.reduce((a, b) => a + b, 0) / hist.length, hs = Math.sqrt(hist.reduce((a, b) => a + (b - hm) ** 2, 0) / (hist.length - 1));
  const X = {}; ['IX.SPX', 'IX.NDX', 'IX.RUT', 'IX.VIX', 'YD.US10', 'YD.US2', 'FX.DXY', 'CM.CO1', 'CM.CL1', 'CM.GC1', 'CM.HG1', 'CR.BTCUSD', 'CR.ETHUSD', 'ET.HYG', 'ET.LQD', 'ET.TLT', 'ET.IEF', 'FX.EURUSD', 'FX.USDJPY', 'ET.XLE'].forEach(id => X[id] = { v: c(id), z: z(id), last: valAt(id, t) });
  const vote = (k, label, val, on, rule) => ({ k, label, val, on: val == null ? null : on, rule });
  const hy = X['ET.HYG'].v != null && X['ET.IEF'].v != null ? X['ET.HYG'].v - X['ET.IEF'].v : null; const sz = X['IX.RUT'].v != null && X['IX.SPX'].v != null ? X['IX.RUT'].v - X['IX.SPX'].v : null;
  const votes = [vote('eq', 'Equities', X['IX.SPX'].v, X['IX.SPX'].v > 0, 'S&P 500 1D return above 0'), vote('vol', 'Volatility', X['IX.VIX'].v, X['IX.VIX'].v < 0, 'VIX 1D change below 0'), vote('crd', 'Credit', hy, hy > 0, 'HYG minus IEF 1D return above 0'), vote('hav', 'Safe havens', X['CM.GC1'].v, X['CM.GC1'].v < 0, 'Gold 1D return below 0'), vote('size', 'Size', sz, sz > 0, 'Russell 2000 minus S&P 500 above 0')];
  const on = votes.filter(v => v.on === true).length, off = votes.filter(v => v.on === false).length; const label = on >= 4 ? 'Risk-on' : off >= 4 ? 'Risk-off' : 'Mixed'; const agree = Math.max(on, off);
  const UNI = [...new Set([...EQ, ...SECTORS, ...US_IDX, ...GLOBAL_IDX, ...FI, ...YLD, ...FXL.filter(o => !o.gen), ...CMD.filter(o => o.type === 'commodity' && !o.gen), ...RISK].map(o => o.id))];
  const unusual = UNI.map(id => ({ id, v: c(id), z: z(id), vx: nxVolX(id, t) })).filter(x => x.v != null && ((x.z != null && Math.abs(x.z) >= 2) || (x.vx != null && x.vx >= 2))).sort((a, b) => Math.max(Math.abs(b.z || 0), (b.vx || 0) - 1) - Math.max(Math.abs(a.z || 0), (a.vx || 0) - 1));
  const d = { t, X, eq, adv, n: eq.length, pctAdv: adv / (eq.length || 1) * 100, ew, sec, disp: dNow, dispZ: hs ? (dNow - hm) / hs : null, dispAvg: hm, votes, regime: { label, on, off, agree, n: votes.filter(v => v.on != null).length }, vixPct: nxLvlPct('IX.VIX', t), unusual };
  NX.days.set(t, d); return d;
}

/* ---------- impact score ---------- */
function nxImpact(it, rel) {
  const mag = clamp(Math.abs(it.z || 0) / 4, 0, 1) * 40; const un = clamp(it.u || 0, 0, 1) * 25;
  const mcs = it.ids.map(id => BY[id]?.type === 'equity' ? fund(id).mcap : null).filter(Boolean); const val = (mcs.length ? clamp(Math.log10(Math.max(...mcs) / 1e10) / Math.log10(400), 0, 1) : it.broad ? 1 : .6) * 20;
  const r = it.ids.some(id => rel.w.has(id) || rel.p.has(id)) ? 15 : 0;
  return { score: Math.round(mag + un + val + r), parts: [['Magnitude', mag, 40, `|σ-score| ${nf(Math.abs(it.z || 0), 1)} of 4`], ['Unusualness', un, 25, it.uWhy || 'volume or dispersion vs baseline'], ['Market value affected', val, 20, mcs.length ? 'largest company market cap, log scale' : it.broad ? 'broad market measure' : 'single non-equity asset'], ['Relevance to you', r, 15, r ? 'in a watchlist or the portfolio' : 'not in your watchlists or portfolio']] };
}

