  for (let w = 0; w < weeks; w++) { h += '<div class="cal-gw">'; for (let d = 0; d < 5; d++) { const t = start + (w * 7 + d) * DAY; const xs = (by[t] || []).sort((a, b) => b.imp - a.imp); h += `<div class="cal-gc ${t === day(END + 12 * 3600e3) ? 'today' : ''}"><span class="cal-gd">${fd(t, { day: '2-digit', month: 'short' })}</span>${xs.slice(0, kind === 'week' ? 14 : 4).map(e => `<a href="#" data-ev="${e.id}" class="cal-chip t-${e.type} i${e.imp}" title="${esc(e.title)}">${e.time && kind === 'week' ? `<time>${fmtHM(e.at)}</time>` : ''}${esc(e.type === 'earn' ? e.co.tk : e.type === 'eco' ? e.eco.tk : e.title.split(' ')[0] === 'U.S.' ? e.title.replace('U.S. ', '').replace(' Treasury note auction', ' auction') : e.title.split(' (')[0].split(' rate')[0])}</a>`).join('')}${xs.length > (kind === 'week' ? 14 : 4) ? `<span class="note">+${xs.length - 4} more</span>` : ''}</div>`; } h += '</div>'; }
