  const wk = {}; up.filter(e => e.imp === 3 && ['earn', 'eco', 'cb'].includes(e.type)).forEach(e => { let m = e.t; while (new Date(m).getUTCDay() !== 1) m -= DAY; (wk[m] = wk[m] || []).push(e); }); const busy = Object.entries(wk).filter(([, xs]) => xs.length >= 4).sort((a, b) => b[1].length - a[1].length);
  add('Catalyst concentration', busy.length > 0, busy.slice(0, 2).map(([m, xs]) => `Week of ${fd(+m)}: ${xs.length} high-impact events (${xs.slice(0, 6).map(e => e.type === 'earn' ? e.co.tk : e.type === 'eco' ? e.eco.tk : e.d.k).join(', ')}).`), 'A week with 4 or more high-impact events in the next 45 days.');
  const mom = up.filter(e => e.type === 'earn').map(e => ({ e, r: e.d.rev[1].eps })).filter(x => Math.abs(x.r) >= 1.2).sort((a, b) => Math.abs(b.r) - Math.abs(a.r));
  add('Consensus momentum', mom.length > 0, mom.slice(0, 4).map(x => `${x.e.co.tk}: EPS estimate ${sgn(x.r, 1)}% over 30 days before ${fd(x.e.t)} (${x.e.d.real ? 'consensus revisions' : 'simulated revisions'}).`), 'Upcoming reporters whose 30-day EPS estimate revision is at least ±1.2%.');
  const rep = []; EQ.forEach(o => { const h = ceHistory(o.id).slice(-4); if (h.length >= 4 && (h.every(x => x.d.surp > 0) || h.every(x => x.d.surp < 0))) rep.push(`${o.tk}: ${h[0].d.surp > 0 ? 'beat' : 'missed'} ${h[0].d.real ? 'consensus' : 'simulated consensus'} in each of the last ${h.length} reports.`); }); ECO.filter(o => o.tk !== 'FEDF').forEach(o => { const p = ecoRels(o).past.slice(-5); if (p.length === 5 && (p.every(x => x.surp > 0) || p.every(x => x.surp < 0))) rep.push(`${o.name}: ${p[0].surp > 0 ? 'above' : 'below'} consensus in each of the last 5 releases.`); });
  add('Repeat surprise patterns', rep.length > 0, rep.slice(0, 5).concat(rep.length ? ['A run of surprises does not guarantee the next outcome.'] : []), 'A company beating or missing in each of its last 4 reports, or an indicator surprising the same way 5 times running.');
  const cpi = BY['EC.USCPI']; const rels = ecoRels(cpi).past; const D = NX_D(); const rx = ['YD.US2', 'FX.DXY', 'IX.SPX', 'CM.GC1'].map(id => { const on = rels.map(x => Math.abs(nxChg(id, D[bsLE(D, x.t)]) ?? 0)); const base = []; for (let k = 1; k <= 120; k++) base.push(Math.abs(nxChg(id, D[D.length - 1 - k]) ?? 0)); const a = on.reduce((p, q) => p + q, 0) / on.length, b = base.reduce((p, q) => p + q, 0) / base.length; return { id, ratio: a / b, n: on.length }; }).sort((a, b) => b.ratio - a.ratio);
  add('Macro sensitivity: U.S. CPI days', true, rx.map(x => `${BY[x.id].tk}: average absolute move on CPI days is ${nf(x.ratio, 2)}× its normal daily move (n = ${x.n} releases, last 2 years).`), 'Release-day absolute moves divided by the average absolute daily move over the last 120 sessions. Simulated history; co-movement only.');
  const nfp = ecoRels(BY['EC.USNFP']).past.at(-1), ism = ecoRels(BY['EC.USISM']).past.at(-1);
  add('Conflicting signals', nfp && ism && ((nfp.act > 100 && ism.act < 50) || (nfp.act < 0 && ism.act > 52)), nfp && ism ? [`Latest payrolls ${fv(BY['EC.USNFP'], nfp.act)} while ISM manufacturing is ${fv(BY['EC.USISM'], ism.act)} (${ism.act < 50 ? 'contraction' : 'expansion'}).`] : [], 'Strong payrolls (>100k) with ISM below 50, or negative payrolls with ISM above 52.');
  const revs = ECO.filter(o => o.tk !== 'FEDF').map(o => ({ o, x: ecoRels(o).past.at(-1) })).filter(y => y.x && Math.abs(y.x.rev) > 0 && Math.abs(y.x.rev) >= Math.abs(y.x.surp) * .5);
  add('Revision impact', revs.length > 0, revs.slice(0, 4).map(y => `${y.o.name}: latest ${fv(y.o, y.x.act)} (surprise ${sgn(y.x.surp, y.o.dp ?? 1)}), but the prior reading was revised by ${sgn(y.x.rev, y.o.dp ?? 1)}; read both together.`), 'The latest release revised the prior reading by at least half the size of the headline surprise.');
