  const y = bY(b); const P = bPrice(b, y); const ytc = b.call && b.call > SETTLE ? bSolve(b, P.clean, { mat: b.call, redeem: b.callPx }) : null; const ytw = ytc != null ? Math.min(y, ytc) : y;
