/* ---------- small charts ---------- */
function fiCurveChart(el, sets, h = 260) { xyChart(el, { h, xlog: true, xlab: 'Maturity (years, log scale)', ylab: 'Yield %', xf: v => v < 1 ? Math.round(v * 12) + 'M' : nf(v, 0) + 'Y', yf: v => nf(v, 2) + '%', series: sets.map(s => ({ label: s.label, color: s.color, line: true, dash: s.dash, r: 3, points: s.pts.map(([x, y]) => ({ x, y, name: s.label, extra: nf(y, 3) + '%' })) })) }); }
function fiBars(rows, { h = 180, f = v => nf(v, 0), stack } = {}) {
  const W = 560, L = 44, B = 22, keys = stack || ['v']; const tot = rows.map(r => keys.reduce((a, k) => a + Math.max(0, r[k] || 0), 0)); const mx = Math.max(...tot, 1); const bw = (W - L) / rows.length; const cols = ['var(--s1)', 'var(--s2)', 'var(--s3)', 'var(--s4)'];
  let s = `<svg viewBox="0 0 ${W} ${h}" width="100%" role="img">`; for (const t of niceTicks(0, mx, 4)) { const y = h - B - t / mx * (h - B - 8); s += `<line x1="${L}" x2="${W}" y1="${y}" y2="${y}" style="stroke:var(--line)"/><text x="${L - 5}" y="${y + 3.5}" text-anchor="end" class="nx-ax">${f(t)}</text>`; }
  rows.forEach((r, i) => { let acc = 0; keys.forEach((k, j) => { const v = Math.max(0, r[k] || 0); const hh = v / mx * (h - B - 8); s += `<rect x="${L + i * bw + bw * .18}" y="${h - B - acc - hh}" width="${bw * .64}" height="${hh}" style="fill:${cols[j]}"><title>${esc(r.label)} ${esc(k)}: ${f(v)}</title></rect>`; acc += hh; }); s += `<text x="${L + i * bw + bw / 2}" y="${h - 6}" text-anchor="middle" class="nx-ax">${esc(r.label)}</text>`; });
  return s + '</svg>' + (stack ? `<div class="nx-leg">${stack.map((k, j) => `<span><i style="background:${cols[j]}"></i>${esc(k)}</span>`).join('')}</div>` : '');
}
function fiDiv(parts) { const mx = Math.max(...parts.map(p => Math.abs(p[1])), .01); return `<div class="fi-div">${parts.map(([l, v]) => `<div class="${l === 'Total' ? 'tot' : ''}"><span>${esc(l)}</span><div class="fi-dt"><i class="${v >= 0 ? 'p' : 'n'}" style="width:${Math.abs(v) / mx * 50}%"></i></div><b class="${cls(v)}">${sgn(v, 2)}%</b></div>`).join('')}</div>`; }
