  const cbs = [['FOMC', 'EC.FEDF', 'Federal Reserve (upper bound)'], ['CBN', 'MM.NGMPR', 'Central Bank of Nigeria MPR']].map(([k, id, l]) => ({ k, l, v: valAt(id, END), next: k === 'CBN' ? fiCbn()[0] : calAll().find(e => e.type === 'cb' && e.d.k === 'FOMC' && !e.past)?.t }));
