function gyFacts() { const r = v => r2(v); return { global_yields_tab: GY_TABS.find(t => t[0] === GY.tab)?.[1], note: 'Simulated yields; real yields use CPI or labelled illustrative inflation assumptions; policy paths are approximations from government curves, not OIS.', markets: gyCC().map(cc => ({ country: gyN(cc), region: GY_META[cc]?.[0], class: GY_META[cc]?.[1], y2: r(gyY(cc, 2).v), y5: r(gyY(cc, 5).v), y10: r(gyY(cc, 10).v), y30: r(gyY(cc, 30).v), y10_1d_bp: r(nxChg(`YD.${cc}10`, END)), y10_1w_bp: r((gyY(cc, 10).v - gyY(cc, 10, gyD(5)).v) * 100), y10_1m_bp: r((gyY(cc, 10).v - gyY(cc, 10, gyD(21)).v) * 100), s2s10_bp: r((gyY(cc, 10).v - gyY(cc, 2).v) * 100), inflation_used: r(gyInf(cc).v), inflation_method: gyInf(cc).kind, real10: r(gyReal(cc)), policy_rate_sim: r(gyPol(cc)), implied_12m_change_bp: gyPath(cc) ? r((gyPath(cc)[2].r - gyPol(cc)) * 100) : null, local_ccy_vs_usd_1m_pct: COUNTRY[cc]?.fx ? r(gyFx(cc, gyD(21))) : null })), eurobond_spreads_bp: Object.fromEntries(Object.keys(SOV).map(k => { const xs = fiAll().filter(a => a.b.iss === k && a.b.kind === 'Eurobond'); return [SOV[k].n, r(xs.reduce((q, a) => q + a.spr, 0) / (xs.length || 1))]; })), us_breakeven_10y: r(govY('US', 10) - fiAll().find(a => a.b.tk === 'TIPS35').y), illustrative_fiscal: Object.fromEntries(Object.entries(SOV2).map(([k, v]) => [gyN(k), { debt_gdp: v[0], interest_revenue: v[1] }])) }; }
{ const _ff5 = factsFor; factsFor = function (r, p) { const f = _ff5(r, p); if (r === 'yields') { try { Object.assign(f, gyFacts()); } catch (e) { f.note = 'Some global yields figures could not be computed.'; } } return f; }; }

