/* ---------- insight cards & trail ---------- */
function gyCard(c, i) { return `<article class="gy-card" data-gyx="trail" data-i="${i}" tabindex="0"><header><span class="gy-cat ${c.cat}">${esc(GY_CAT[c.cat][0])}</span><span class="gy-conf ${c.conf.toLowerCase()}" title="${esc(c.confWhy || '')}">${c.conf} confidence</span></header><h4>${esc(c.head)}</h4><p class="gy-ev">${esc(c.ev)}</p><p class="gy-why">${esc(c.why)}</p><footer><button class="btn sm" data-gyx="trail" data-i="${i}">Insight trail</button>${c.link ? `<button class="btn sm ghost" data-gyx="golink" data-i="${i}">${esc(c.link[1])} →</button>` : ''}</footer></article>`; }
GY_X.trail = b => { const c = GY.cards?.[+b.dataset.i]; if (!c) return; const T = c.trail;
  gyDrawer(`<header class="mv-dh"><div><span class="nx-lab">${esc(GY_CAT[c.cat][0])} · ${c.conf} confidence</span><h2 style="font-size:22px;line-height:1.25">${esc(c.head)}</h2><div class="note">Simulated close ${fd(END)} · ${esc(c.confWhy || '')}</div></div><button class="btn sm ghost" id="gyClose" aria-label="Close">✕</button></header><div class="mv-db gy-trail">
    <section><h4><b>1</b>Observation</h4><p>${esc(T.obs)}</p></section>
    <section><h4><b>2</b>Evidence</h4><dl class="kl">${T.ev.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(String(v))}</dd></div>`).join('')}</dl></section>
    <section><h4><b>3</b>Interpretation: competing explanations</h4><ul class="mv-its">${T.interp.map(x => `<li>${esc(x)}</li>`).join('')}</ul><p class="note">Coincident observations, listed by size. None is confirmed as the cause.</p></section>
    <section><h4><b>4</b>Historical context</h4><p>${esc(T.hist)}</p></section>
    <section><h4><b>5</b>Implications</h4><p>${esc(T.impl)}</p></section>
    <section><h4><b>6</b>Uncertainty</h4><ul class="mv-its">${T.unc.map(x => `<li>${esc(x)}</li>`).join('')}</ul></section>
    <div class="mv-act"><button class="btn sm pri" id="gyTA">Ask Superfinancials to investigate</button>${c.link ? `<button class="btn sm" id="gyTL">${esc(c.link[1])}</button>` : ''}${c.rule ? `<button class="btn sm" id="gyTR2">Alert me on this</button>` : ''}</div></div>`);
  $('#gyTA').onclick = () => { $('#gyDrawer').hidden = true; GY.ask(c.q + ' Evidence: ' + T.ev.map(([k, v]) => `${k}: ${v}`).join('; ')); };
  if ($('#gyTL')) $('#gyTL').onclick = () => { $('#gyDrawer').hidden = true; GY_X.golink({ dataset: { i: b.dataset.i } }); };
  if ($('#gyTR2')) $('#gyTR2').onclick = () => { gyMakeAlert(c.rule); };
};
