GY_FN.heat = el => { gyHeat(el); if (!['d1', 'd5', 'd21'].includes(GY.hm)) return; const k = { d1: 1, d5: 5, d21: 21 }[GY.hm]; const ccs = gyRows(); const cells = ccs.flatMap(cc => GY_TEN.filter(t => t[1] !== 20).map(([l, m]) => ({ cc, l, v: gyCh(cc, m, k) })).filter(x => x.v != null)); const tot = cells.reduce((s, c) => s + Math.abs(c.v), 0) || 1; const by = (f) => { const o = {}; cells.forEach(c => { const g = f(c); o[g] = (o[g] || 0) + Math.abs(c.v); }); return Object.entries(o).map(([g, v]) => ({ g, s: v / tot * 100, n: cells.filter(c => f(c) === g).length })).sort((a, b) => b.s / b.n - a.s / a.n); }; const R = by(c => GY_META[c.cc][0]), T2 = by(c => c.l); const top = cells.slice().sort((a, b) => Math.abs(b.v) - Math.abs(a.v)); const share3 = top.slice(0, 3).reduce((s, c) => s + Math.abs(c.v), 0) / tot * 100; const up = cells.filter(c => c.v > 0).length / cells.length * 100;
  const verdict = share3 > 35 ? `Concentrated: three cells (${top.slice(0, 3).map(c => `${c.cc} ${c.l}`).join(', ')}) account for ${nf(share3, 0)}% of all absolute movement.` : R[0].s / R[0].n > 1.6 * (100 / cells.length) ? `Regional: ${R[0].g} moved most per cell (${nf(R[0].s, 0)}% of absolute movement from ${R[0].n} cells).` : `Broad-based: movement is spread across markets; ${nf(up, 0)}% of cells rose.`;
  el.querySelector('.fi-tb').insertAdjacentHTML('afterend', `<section class="panel"><div class="pb gy-conc"><div><span class="nx-lab">Where is the repricing?</span><p class="gy-interp">${esc(verdict)}</p></div><div><h6>By region (avg |Δ| per cell)</h6>${R.map(x => `<div class="fi-r"><span>${esc(x.g)}</span><b>${nf(x.s * tot / 100 / x.n, 1)} bp</b></div>`).join('')}</div><div><h6>By tenor</h6>${T2.map(x => `<div class="fi-r"><span>${x.g}</span><b>${nf(x.s * tot / 100 / x.n, 1)} bp</b></div>`).join('')}</div></div></section>`); };
// Curve atlas: shift chart, tenor comparison, shape ranking, segments
