  const shift = gyGBars(ten.map(t => t[0]), GY.cty.map((cc, i) => ({ label: gyN(cc), color: PAL[i % 8], vals: ten.map(([, m]) => { const a = gyY(cc, m).v, b = gyY(cc, m, t0).v; return a == null || b == null ? null : (a - b) * 100; }) })), { h: 220 });
  const shp = gyCC().map(cc => { const g = (m, t) => gyY(cc, m, t).v; const s = t => (g(10, t) - g(2, t)) * 100, fl = t => (2 * g(5, t) - g(2, t) - g(10, t)) * 100, lv = t => gyM([2, 5, 10].map(m => g(m, t))); const ds = s(END) - s(t0), df = fl(END) - fl(t0), dl = (lv(END) - lv(t0)) * 100; return { cc, ds, df, dl, sc: Math.abs(ds) + Math.abs(df), lab: Math.abs(ds) < 3 ? (dl > 0 ? 'Parallel rise' : 'Parallel fall') : `${dl > 0 ? 'Bear' : 'Bull'} ${ds > 0 ? 'steepening' : 'flattening'}` }; }).sort((a, b) => b.sc - a.sc);
  const segs = GY.cty.map(cc => { const p = ten.map(([l, m]) => [l, m, gyY(cc, m).v]).filter(x => x[2] != null); const sg = []; for (let i = 1; i < p.length; i++) sg.push({ s: `${p[i - 1][0]}–${p[i][0]}`, v: (p[i][2] - p[i - 1][2]) * 100 / (p[i][1] - p[i - 1][1]) }); sg.sort((a, b) => b.v - a.v); return { cc, hi: sg[0], lo: sg[sg.length - 1] }; });
