  AUD: { n: 'Australian dollar', reg: 'Asia-Pacific', cls: 'G10', cc: 'AU', turn: 6.4, cmd: 'CM.HG1', regime: 'Free float' },
  CAD: { n: 'Canadian dollar', reg: 'North America', cls: 'G10', cc: 'CA', turn: 6.2, cmd: 'CM.CO1', regime: 'Free float' },
