  const span = x[n - 1] - x[0]; const xt = niceTicks(x[0], x[n - 1], Math.max(3, Math.floor(W / 120))); xt.forEach(t => { if (t < x[0] || t > x[n - 1]) return; const xx = L + (t - x[0]) / (span || 1) * (W - L - R); s += `<text x="${xx}" y="${H - 10}" text-anchor="middle" class="nx-ax">${esc((c.xf || (v => fd(v, span > 400 * DAY ? { month: 'short', year: '2-digit' } : { day: '2-digit', month: 'short' })))(t))}</text>`; });
  if (c.split != null) s += `<line x1="${tx(c.split)}" x2="${tx(c.split)}" y1="${T}" y2="${H - B}" style="stroke:var(--fg3);stroke-dasharray:3 3"/><text x="${tx(c.split) + 4}" y="${T + 10}" class="nx-ax">${esc(c.splitLab || '')}</text>`;
  const txf = v => { const a = Math.max(0, Math.min(n - 1, Math.floor(v))), b2 = Math.max(0, Math.min(n - 1, Math.ceil(v))); return tx(a) + (tx(b2) - tx(a)) * (v - Math.floor(v)); }; (c.spans || []).forEach(sp => { const x0 = txf(Math.max(0, sp.i0)), x1 = txf(Math.min(n - 1, sp.i1)); s += `<rect x="${x0.toFixed(1)}" y="${T}" width="${Math.max(1, x1 - x0).toFixed(1)}" height="${H - T - B}" style="fill:${sp.c};opacity:${sp.op ?? .14}"><title>${esc(sp.label || '')}</title></rect>${sp.lab && x1 - x0 > 40 ? `<text x="${((x0 + x1) / 2).toFixed(1)}" y="${T + 11}" text-anchor="middle" class="nx-ax" style="fill:${sp.c};font-weight:600">${esc(sp.lab)}</text>` : ''}`; });
  (c.bands || []).forEach(b => { const ax = b.ax || 'l'; const idx = []; for (let i = 0; i < n; i++) if (b.lo[i] != null && b.hi[i] != null) idx.push(i); if (idx.length < 2) return; s += `<path d="M${idx.map(i => `${tx(i).toFixed(1)} ${ty(b.hi[i], ax).toFixed(1)}`).join('L')}L${idx.slice().reverse().map(i => `${tx(i).toFixed(1)} ${ty(b.lo[i], ax).toFixed(1)}`).join('L')}Z" style="fill:${b.c};opacity:${b.op ?? .15}"/>`; });
  (c.hl || []).forEach(h => { s += `<line x1="${L}" x2="${W - R}" y1="${ty(h.y, h.ax || 'l')}" y2="${ty(h.y, h.ax || 'l')}" style="stroke:${h.c || 'var(--fg2)'};stroke-dasharray:6 4;stroke-width:1.4"/>`; });
  c.series.forEach(se => { const ax = se.ax || 'l'; let d = '', on = false; se.v.forEach((v, i) => { if (v == null || !isFinite(v)) { on = false; return; } d += `${on ? 'L' : 'M'}${tx(i).toFixed(1)} ${ty(v, ax).toFixed(1)}`; on = true; }); if (se.area) { const f = se.v.findIndex(v => v != null), l = se.v.length - 1 - se.v.slice().reverse().findIndex(v => v != null); s += `<path d="${d}L${tx(l)} ${H - B}L${tx(f)} ${H - B}Z" style="fill:${se.c};opacity:.08"/>`; } s += `<path d="${d}" style="fill:none;stroke:${se.c};stroke-width:${se.w || 1.7}${se.dash ? ';stroke-dasharray:' + se.dash : ''}"/>`; (se.pts || []).forEach(i => { if (se.v[i] != null) s += `<path d="M${tx(i)} ${ty(se.v[i], ax) - 6}l6 6l-6 6l-6-6z" style="fill:${se.c}"/>${se.lab ? `<text x="${tx(i) + 8}" y="${ty(se.v[i], ax) - 6}" class="gy-ann" style="fill:${se.c}">${esc(se.lab(se.v[i]))}</text>` : ''}`; }); });
