const GX = { tab: 'ov', per: '1M', mx: 'G10', mxM: 'ret', watch: ['EUR/USD', 'USD/JPY', 'GBP/USD', 'USD/NGN', 'USD/ZAR', 'EUR/NGN', 'AUD/USD'], pb: 'EUR', pq: 'USD', pm: 'spot', pr: '1Y', single: false, est: 'USCPI', vc: 'EUR', vm: 'reer', rk: 'mov', evR: 'EC.USCPI', evP: 'EUR/USD', evW: 1, ev1: 0, rel: 'EUR', crF: 'USD', hA: 'EUR', hB: 'USD', hR: 5, hH: 100, hF: -3, fan: 'USD/NGN', fanS: null, scen: 'usd5', cperF: '1M', base: 'USD', nW: 120, nM: 'mst', nS: 'all', nC: false, fl: 'yld', xq: '', xr: null, cat: '', ngP: '1Y', ng: { oil: -20, res: -3, us: 50, sup: -10 }, emP: '1M' };
const GX_TABS = [['ov', 'FX overview'], ['pair', 'Currency pairs'], ['val', 'Performance & valuation'], ['macro', 'Macro & policy'], ['em', 'Emerging & frontier'], ['carry', 'Relative value & carry'], ['flows', 'Flows & network'], ['risk', 'FX risk & scenarios'], ['ai', 'AI FX strategist'], ['data', 'Data & sources'], ['old', 'Converter & products']];
