  const weak = /weak|fell|depreciat|worst|lost/.test(s); const vs = /against the euro/.test(s) ? 'EUR' : 'USD'; out.crit = [`${grp === GX_G10 ? 'G10' : grp === GX_EM ? 'Emerging & frontier' : grp.length < 10 ? 'Frontier' : 'All'} currencies`, `vs ${vs}`, per, weak ? 'weakest first' : 'strongest first']; out.cols = [['c', 'Currency'], ['v', `${per} vs ${vs}`, v => pc(v, 2)], ['z', 'Move ÷ vol', v => sgn(v, 2)]]; out.rows = grp.filter(c => c !== vs).map(c => { const v = gxRet(c, per, vs); return { c, v, z: v / (gxVol(c, vs, 252) * Math.sqrt(Math.max(1, gxK(per)) / 252) || 1) }; }).sort((a, b) => weak ? a.v - b.v : b.v - a.v); out.interp = `${weak ? 'Weakest' : 'Strongest'}: ${out.rows.slice(0, 3).map(r => `${r.c} ${pc(r.v, 1)}`).join(', ')}.`; return out;
