/* ---------- catalysts (schedule patterns; dates simulated) ---------- */
function cmEvents(from, to) { const out = []; for (let t = Math.floor(from / DAY) * DAY; t <= to; t += DAY) { const d = new Date(t), wd = d.getUTCDay(), dm = d.getUTCDate(), mo = d.getUTCMonth(); if (wd === 3) out.push({ t, k: 'EIAP', title: 'EIA Weekly Petroleum Status Report', ids: ['CM.CO1', 'CM.CL1', 'CM.RB1', 'CM.HO1'], imp: 2 }); if (wd === 4) out.push({ t, k: 'EIAG', title: 'EIA Natural Gas Storage Report', ids: ['CM.NG1'], imp: 2 }); if (wd === 5) out.push({ t, k: 'COT', title: 'CFTC Commitments of Traders', ids: CM_FUT, imp: 1 }); if (wd === 1 && mo >= 3 && mo <= 10) out.push({ t, k: 'CROP', title: 'USDA Crop Progress', ids: ['CM.ZC1', 'CM.ZS1', 'CM.ZW1'], imp: 1 }); if (dm >= 9 && dm <= 12 && wd === 2) out.push({ t, k: 'WASDE', title: 'USDA WASDE supply-demand report', ids: ['CM.ZC1', 'CM.ZS1', 'CM.ZW1', 'CM.CT1', 'CM.SB1'], imp: 3 }); if (dm >= 1 && dm <= 7 && wd === 0) out.push({ t: t + DAY * 0, k: 'OPEC', title: 'OPEC+ ministerial meeting (simulated date)', ids: ['CM.CO1', 'CM.CL1'], imp: 3 }); if (dm === 7 || (dm === 8 && wd === 1)) if (wd >= 1 && wd <= 5) out.push({ t, k: 'CNTR', title: 'China trade data (imports of crude, ore, copper, soybeans)', ids: ['CM.CO1', 'CM.TIO', 'CM.HG1', 'CM.ZS1'], imp: 2 }); if ([0, 3, 6, 9].includes(mo) && dm >= 14 && dm <= 18 && wd === 4) out.push({ t, k: 'COCOA', title: 'Quarterly cocoa grind data', ids: ['CM.CC1'], imp: 2 }); if (mo === 5 && dm === 1) out.push({ t, k: 'HUR', title: 'Atlantic hurricane season begins', ids: ['CM.CO1', 'CM.NG1', 'CM.RB1'], imp: 2 }); } return out; }
function cmEvSurprise(e) { if (e.k !== 'EIAP' && e.k !== 'EIAG') return null; const id = e.k === 'EIAP' ? 'CM.CO1' : 'CM.NG1'; const I = cmInv(id); const i = bsLE(I.W, e.t); if (i < 2) return null; const act = I.v[i] - I.v[i - 1]; const r = rng(hash('cons' + e.t)); const cons = act - (r() - .5) * gySd(I.v.slice(Math.max(1, i - 52), i + 1).map((v, j, a) => j ? v - a[j - 1] : 0)) * 1.2; return { act, cons, surp: act - cons, unit: I.unit }; }

/* ---------- explanations: measured drivers vs hypotheses ---------- */
function cmExplain(id, k) { const t0 = gyD(k); const ch = cmRet(id, k); const out = []; const beta = (drv) => gyOLS(gyDx(drv, 250), gyDx(id, 250))?.b || 0;
  const dx = (valAt('FX.DXY', END) / valAt('FX.DXY', t0) - 1) * 100; out.push({ m: true, f: 'U.S. dollar', v: beta('FX.DXY') * dx, txt: `Dollar index ${pc(dx, 1)}; 1Y beta ${nf(beta('FX.DXY'), 2)} → ${pc(beta('FX.DXY') * dx, 1)}` });
  const sp = (valAt('IX.SPX', END) / valAt('IX.SPX', t0) - 1) * 100; out.push({ m: true, f: 'Risk appetite (equities)', v: beta('IX.SPX') * sp, txt: `S&P 500 ${pc(sp, 1)}; beta ${nf(beta('IX.SPX'), 2)} → ${pc(beta('IX.SPX') * sp, 1)}` });
  const I = cmInv(id); if (I) { const n = I.v.length, w = Math.max(1, Math.round(k / 5)); const c = I.v[n - 1] - I.v[n - 1 - w]; out.push({ m: true, f: 'Inventories', v: null, txt: `${I.name} ${sgn(c, 1)} ${I.unit} over ${w} week(s) (${cmInvStat(id).pct != null ? cmPctW(cmInvStat(id).pct) : ''})` }); }
  const c0 = cmSlope(id, t0), c1 = cmSlope(id); if (c1 != null) out.push({ m: true, f: 'Curve shape', v: null, txt: `M1→M12 ${sgn(c0, 1)}% → ${sgn(c1, 1)}% (${c1 < c0 ? 'tightening at the front' : 'easing'})` });
  const P = cmPos(id); if (P) { const n = P.mm.length; out.push({ m: true, f: 'Positioning', v: null, txt: `Managed-money net ${sgn(P.mm[n - 1], 0)}% of OI (${sgn(P.mm[n - 1] - P.mm[Math.max(0, n - 1 - Math.max(1, Math.round(k / 5)))], 0)} pts; reported with a lag)` }); }
  const wx = CM_REG.map((_, i) => cmWx(i)).filter(w => w.ids.includes(id) && w.cond >= 2 && w.cond < 5); wx.forEach(w => out.push({ m: false, f: 'Weather (hypothesis)', txt: `${w.name}: ${CM_COND[w.cond][0].toLowerCase()} conditions, temperature ${sgn(w.ta, 1)}°C, rainfall ${sgn(w.pa, 0)}% vs normal` }));
  const ev = cmEvents(t0, END).filter(e => e.ids.includes(id) && e.imp >= 2); ev.slice(-2).forEach(e => out.push({ m: false, f: 'Scheduled report (hypothesis)', txt: `${fd(e.t, { day: '2-digit', month: 'short' })} ${e.title}` }));
  return { ch, out }; }

/* ---------- insights ---------- */
const CM_CAT = { def: 'Emerging supply deficit', inv: 'Inventory anomaly', curve: 'Curve dislocation', wx: 'Weather-driven supply risk', flow: 'Trade-flow disruption', margin: 'Producer margin pressure', cat: 'Upcoming market catalyst', rev: 'Data and forecast revision' };
let CM_INS = null;
function cmInsights() { if (CM_INS) return CM_INS; const out = [];
  CM_IDS.filter(id => CMX[id].inv).forEach(id => { const s = cmInvStat(id); if (!s) return; const c1 = cmSlope(id), c0 = cmSlope(id, gyD(21)); const b = cmBal(id); const lastF = b?.rows.find(r => r.st !== 'Actual'); const sig = [s.pct <= 20 ? `inventories at the ${ordn(s.pct)} seasonal percentile` : null, s.ch4 < 0 ? `stocks ${sgn(s.ch4, 1)} ${s.unit} in 4 weeks` : null, c1 != null && c1 < c0 - 1 ? `front of the curve tightening (M1→M12 ${sgn(c0, 1)}% → ${sgn(c1, 1)}%)` : null, lastF && lastF.chg < 0 ? `model balance shows a deficit in ${lastF.q}` : null].filter(Boolean);
    if (sig.length >= 3) out.push({ cat: 'def', id, score: sig.length * 5, conf: sig.length >= 4 ? 'Medium' : 'Low', head: `${cmN(id)}: ${sig.length} indicators point to tightening supply`, ev: sig.join(' · '), why: 'Several independent signals agreeing is stronger evidence than one unusual data point.', link: ['sd', 'Supply & inventories'], trail: { obs: `${sig.length} signals agree for ${cmN(id)}.`, ev: [[s.name, `${cmF(id, s.last)} ${s.unit} (${ordn(s.pct)} seasonal pctl, model)`], ['4-week change', `${sgn(s.ch4, 1)} ${s.unit}`], ['M1→M12', `${sgn(c1, 1)}% (was ${sgn(c0, 1)}%)`], ...(lastF ? [[`Balance ${lastF.q} (${lastF.st.toLowerCase()})`, `${sgn(lastF.chg, 2)} ${b.unit}`]] : [])], alt: ['Seasonal draw that will reverse', 'Logistics, not scarcity, may be holding stocks away from the delivery point', 'Positioning-driven curve move'], impl: `Front-month ${cmTk(id)} contracts and calendar spreads; producers and consumers of ${cmN(id)}.`, unc: ['Inventories and balances are modelled, not reported data', 'Forecast quarters are estimates'] }, q: `Is ${cmN(id)} moving into deficit? Weigh the inventory, curve and balance signals, give alternative explanations and what would weaken the conclusion.` });
    if (Math.abs(s.z) > 2 || s.pct <= 5 || s.pct >= 95) out.push({ cat: 'inv', id, score: Math.max(Math.abs(s.z), 2) * 4, conf: 'Low', head: `${s.name}: ${Math.abs(s.z) > 2 ? `${sgn(s.ch1, 1)} ${s.unit} in a week (${nf(Math.abs(s.z), 1)}σ)` : (s.pct >= 100 ? 'above its 5-year range for this time of year' : s.pct <= 0 ? 'below its 5-year range for this time of year' : `at the ${ordn(s.pct)} percentile for this time of year`)}`, ev: `Level ${cmF(id, s.last)} ${s.unit} vs 5-year seasonal average ${cmF(id, s.avg)} (range ${cmF(id, s.lo)}–${cmF(id, s.hi)}) · source pattern: ${s.src}`, why: 'Stocks far from seasonal norms change how sensitive prices are to supply shocks.', link: ['sd', 'Inventory chart'], trail: { obs: `${s.name} is ${cmF(id, s.last)} ${s.unit}.`, ev: [['Weekly change', `${sgn(s.ch1, 1)} ${s.unit} (${nf(s.z, 1)}σ)`], ['Seasonal percentile (5Y)', ordn(s.pct)], ['vs 5Y average', pc(s.vsAvg, 1)], ['Reporting period', `week to ${fd(END)} (modelled weekly path)`], ['Data source pattern', s.src]], alt: ['Reporting noise or revisions', 'Timing of imports/exports'], impl: `${cmTk(id)} spreads and price sensitivity.`, unc: ['Modelled inventories; production would use the named official source'] }, q: `How unusual is the latest ${s.name.toLowerCase()} reading and what could explain it?` }); });
  CM_FUT.forEach(id => { const h = cmSprHist(id, 0, 1, 1260).filter(v => v != null); const now = cmSpr(id, 0, 1); const p = gyPct(h, now); if (p > 4 && p < 96) return; out.push({ cat: 'curve', id, score: 9, conf: 'Low', head: `${cmN(id)} M1–M2 spread ${p >= 100 ? 'at a 5-year high (most backwardated)' : p <= 0 ? 'at a 5-year low (deepest contango)' : `at the ${ordn(p)} percentile of 5 years`}`, ev: `M1–M2 ${sgn(now, 2)} ${cmU(id)} · 5Y range ${sgn(Math.min(...h), 2)} to ${sgn(Math.max(...h), 2)}`, why: 'Extreme nearby spreads can signal acute scarcity or glut, or contract-specific delivery issues.', link: ['px', 'Curve atlas'], trail: { obs: `The first-to-second contract spread is ${sgn(now, 2)} ${cmU(id)}.`, ev: [['Percentile (5Y weekly)', ordn(p)], ['M1→M12 slope', sgn(cmSlope(id), 1) + '%'], ['Inventories', cmInvStat(id) ? `${ordn(cmInvStat(id).pct)} seasonal pctl` : 'n/a']], alt: ['Delivery-point logistics or contract specifics', 'Roll activity around expiry', 'Positioning squeeze'], impl: 'Calendar-spread positions; roll yield of long-only holdings.', unc: ['A dislocation is a research signal, not an executable arbitrage', 'Curves are modelled'] }, q: `Explain the unusual ${cmN(id)} front spread: physical vs financial drivers.` }); });
  CM_REG.forEach((_, i) => { const w = cmWx(i); if (w.cond < 2 || w.cond > 4) return; out.push({ cat: 'wx', id: w.ids[0], score: w.cond * 4, conf: 'Low', head: `${w.name}: ${CM_COND[w.cond][0].toLowerCase()} conditions for ${w.ids.map(cmTk).join(', ')}`, ev: `Temperature ${sgn(w.ta, 1)}°C, rainfall ${sgn(w.pa, 0)}% vs normal · 2-week outlook ${sgn(w.fta, 1)}°C ± ${nf(w.unc, 1)}°C · ${w.note}`, why: 'Weather in a material producing region can cut yields or output; the forecast is uncertain.', link: ['wx', 'Weather & risk'], trail: { obs: `${w.name} is rated ${CM_COND[w.cond][0].toLowerCase()} (simulated).`, ev: [['Temperature anomaly', `${sgn(w.ta, 1)}°C`], ['Precipitation vs normal', `${sgn(w.pa, 0)}%`], ['2-week forecast', `${sgn(w.fta, 1)}°C ± ${nf(w.unc, 1)}`], ['Production base (approx.)', w.note]], alt: ['Rain later in the season can restore yields', 'Other regions may offset'], impl: w.ids.map(cmN).join(', '), unc: ['Simulated conditions; production would use national met agencies and crop monitors', 'Forecast uncertainty grows beyond a week'] }, q: `How material is the weather risk in ${w.name} for ${w.ids.map(cmN).join(' and ')}?` }); });
  const fr = cmRet('CM.TD3C', 21), fb = cmRet('CM.BDIX', 21); [['CM.TD3C', fr, 'Tanker rates'], ['CM.BDIX', fb, 'Dry bulk freight']].forEach(([id, v, l]) => { if (Math.abs(v) < 15) return; out.push({ cat: 'flow', id, score: Math.abs(v) / 3, conf: 'Low', head: `${l} ${pc(v, 0)} in a month: possible rerouting or congestion`, ev: `${cmN(id)} ${cmF(id, cmP(id))} ${cmU(id)} · AIS vessel tracking and port data not connected`, why: 'Freight spikes change landed costs and regional availability.', link: ['phys', 'Physical markets'], trail: { obs: `${l} moved ${pc(v, 1)} over a month.`, ev: [['Level', `${cmF(id, cmP(id))} ${cmU(id)}`], ['1M change', pc(v, 1)]], alt: ['Seasonal demand', 'Fleet supply changes', 'Fuel costs'], impl: id === 'CM.TD3C' ? 'Middle East → Asia crude arbitrage; refiners in Asia' : 'Iron ore, coal and grain landed costs', unc: ['Freight indices are illustrative', 'Vessel-level data not connected'] }, q: `What could explain the ${l.toLowerCase()} move and which commodity flows are affected?` }); });
  const crack = cmCrack(), c21 = cmCrack(gyD(21)); if (Math.abs(crack - c21) > 3) out.push({ cat: 'margin', id: 'CM.HO1', score: 10, conf: 'Medium', head: `Refining margins ${crack < c21 ? 'compressing' : 'expanding'}: 3-2-1 crack ${nf(c21, 1)} → ${nf(crack, 1)} $/bbl in a month`, ev: `Gasoline crack ${nf(cmCrack(END, 'g'), 1)}, diesel crack ${nf(cmCrack(END, 'd'), 1)} $/bbl`, why: 'Crack spreads drive refiner earnings and crude demand.', link: ['sec', 'Energy research'], trail: { obs: 'The 3-2-1 crack spread changed materially.', ev: [['3-2-1 crack now', nf(crack, 2) + ' $/bbl'], ['1M ago', nf(c21, 2) + ' $/bbl']], alt: ['Refinery outages or turnarounds', 'Seasonal product demand'], impl: 'Refiners (e.g. VLO in the simulated universe); crude buyers.', unc: ['Uses NY Harbor futures vs WTI; regional cracks differ'] }, q: 'Explain the change in refining margins and who is affected.' });
  const ur = cmP('CM.UREA') / (cmP('CM.TTF') * valAt('FX.EURUSD', END) / 3.412), ur0 = cmP('CM.UREA', gyD(63)) / (cmP('CM.TTF', gyD(63)) * valAt('FX.EURUSD', gyD(63)) / 3.412); if (Math.abs(ur / ur0 - 1) > .12) out.push({ cat: 'margin', id: 'CM.UREA', score: 8, conf: 'Low', head: `Nitrogen producer margins ${ur < ur0 ? 'squeezed' : 'widening'}: urea vs European gas ratio ${nf(ur0, 1)} → ${nf(ur, 1)}`, ev: 'Urea USD/t divided by TTF in USD/MMBtu (rough feedstock proxy)', why: 'European ammonia/urea plants are marginal producers; gas costs set the floor.', link: ['sec', 'Fertilizer research'], trail: { obs: 'The urea-to-gas ratio moved over 3 months.', ev: [['Ratio now', nf(ur, 1)], ['3M ago', nf(ur0, 1)]], alt: ['Chinese export policy', 'Seasonal demand'], impl: 'Nitrogen producers (CF in universe); farmers\' input costs.', unc: ['Urea is an illustrative assessment'] }, q: 'How are fertilizer producer margins changing and what does it mean for crop economics?' });
  const cat = cmEvents(END + DAY, END + 14 * DAY).filter(e => e.imp >= 2); if (cat.length) out.push({ cat: 'cat', id: cat[0].ids[0], score: 7, conf: 'Medium', head: `Next 14 days: ${cat.filter(e => e.imp === 3).map(e => e.title).slice(0, 2).join(' and ') || cat[0].title}`, ev: cat.slice(0, 4).map(e => `${fd(e.t, { day: '2-digit', month: 'short' })} ${e.title}`).join(' · '), why: 'Scheduled reports and meetings concentrate price risk.', link: ['ov', 'Catalysts'], trail: { obs: `${cat.length} relevant scheduled events.`, ev: cat.slice(0, 8).map(e => [fd(e.t), `${e.title} · ${e.ids.slice(0, 4).map(cmTk).join(', ')}`]), alt: ['Unscheduled events often matter more'], impl: 'Positions in the affected markets.', unc: ['Schedule follows typical patterns; dates simulated'] }, q: 'Rank upcoming commodity catalysts and the markets each could move.' });
  Object.keys(CM_BAL).forEach(id => { const b = cmBal(id); const f = b.rows.filter(r => r.st !== 'Actual'); const rv = f.map(r => (r.prod - r.cons) - (r.prior.prod - r.prior.cons)); const tot = rv.reduce((a, v) => a + v, 0); if (Math.abs(tot) < CM_BAL[id][2] * .004) return; out.push({ cat: 'rev', id, score: 6, conf: 'Low', head: `${b.name} balance revised ${tot > 0 ? 'towards surplus' : 'towards deficit'} (${sgn(tot, 2)} ${b.unit} across ${f.length} quarters)`, ev: f.slice(0, 3).map((r, i) => `${r.q}: ${sgn(r.prior.prod - r.prior.cons, 2)} → ${sgn(r.chg, 2)}`).join(' · '), why: 'Revisions to expected balances often move deferred prices.', link: ['sd', 'Balances'], trail: { obs: 'The modelled balance changed from the prior estimate.', ev: f.map(r => [r.q + ' (' + r.st.toLowerCase() + ')', `prior ${sgn(r.prior.prod - r.prior.cons, 2)} → now ${sgn(r.chg, 2)} ${b.unit}`]), alt: ['Demand revisions vs supply revisions have different implications'], impl: `Deferred ${cmTk(id)} contracts.`, unc: ['Illustrative balances; production would use EIA/IEA/OPEC/USDA/ICSG releases with vintage history'] }, q: `What changed in the ${b.name.toLowerCase()} balance estimate and why does it matter?` }); });
  const CW = { High: 1.3, Medium: 1, Low: .6 }; out.forEach(c => c.rank = c.score * (CW[c.conf] || 1)); return CM_INS = out.sort((a, b) => b.rank - a.rank); }
function cmCrack(t = END, k = '321') { const cl = cmP('CM.CL1', t), rb = cmP('CM.RB1', t) * 42, ho = cmP('CM.HO1', t) * 42; return k === 'g' ? rb - cl : k === 'd' ? ho - cl : (2 * rb + ho) / 3 - cl; }
const cmDiv = (rows, f, upGood) => gyDivRows(rows, f, upGood);

