  const fac = [['Refinery A', 'U.S. Gulf Coast', 'Crude refining', 'CM.CO1'], ['Refinery B', 'Northwest Europe', 'Crude refining', 'CM.CO1'], ['LNG terminal C', 'U.S. Gulf Coast', 'Liquefaction', 'CM.NG1'], ['Copper smelter D', 'China', 'Smelting', 'CM.HG1'], ['Copper mine E', 'Chile', 'Mining', 'CM.HG1'], ['Aluminium smelter F', 'Gulf states', 'Smelting', 'CM.ALI'], ['Crude terminal G', 'West Africa', 'Export terminal', 'CM.CO1'], ['Cocoa processor H', 'Côte d\'Ivoire', 'Grinding', 'CM.CC1']].map(([n, loc, typ, id]) => { const r = rng(hash('fac' + n + iso(END).slice(0, 7))); const u = 60 + r() * 38; return { n, loc, typ, id, u, st: u < 70 ? 'Reduced (outage or maintenance)' : 'Operating' }; });
