  const ev = R.past.slice(-12).filter(x => x.t >= D[0]).map(x => ({ t: x.ref, label: `${mcRef(x.ref, f)} released ${fd(x.t)}`, c: 'var(--violet)' })); const p10 = gyQ(xs, 10), p90 = gyQ(xs, 90);
