/* ---------- OECD-style composite leading indicators & diffusion ---------- */
let EC_CLI = null;
function ecCLI() { if (EC_CLI) return EC_CLI; const M = mcM(); const out = {}; MC_IDS.forEach(cc => { const A = mcAssets(cc); const comp = []; const z = a => { const xs = a.filter(v => v != null); const m = gyM(xs), sd = gySd(xs) || 1; return a.map(v => v == null ? null : (v - m) / sd); }; ['MPMI', 'SPMI', 'CONF'].forEach(k => { if (mcHas(cc, k)) comp.push(z(M.map(t => mcAt(cc, k, t)))); }); if (mcHas(cc, 'CRED')) comp.push(z(M.map((t, i) => { const x = mcAt(cc, 'CRED', t), y = mcAt(cc, 'CRED', M[i - 6]); return x != null && y != null ? x - y : null; }))); if (mcHas(cc, 'FCI')) comp.push(z(M.map(t => -mcAt(cc, 'FCI', t)))); if (A.y10 && A.y2) comp.push(z(M.map(t => t > END ? null : valAt(A.y10, Math.min(t, END)) - valAt(A.y2, Math.min(t, END))))); if (comp.length < 2) return; let e = null; const raw = M.map((_, i) => { const xs = comp.map(c => c[i]).filter(v => v != null); const v = xs.length ? gyM(xs) : null; if (v == null) return e; e = e == null ? v : .7 * e + .3 * v; return e; }); const sd = gySd(raw.filter(v => v != null)) || 1; const cli = raw.map(v => v == null ? null : 100 + v / sd); out[cc] = { cli, n: comp.length }; }); const ccs = Object.keys(out); const diff = M.map((_, i) => { const xs = ccs.filter(cc => out[cc].cli[i] != null && out[cc].cli[i - 1] != null); return xs.length && i > 0 ? xs.filter(cc => out[cc].cli[i] > out[cc].cli[i - 1]).length / xs.length * 100 : null; }); const glob = M.map((_, i) => { let s = 0, w = 0; ccs.forEach(cc => { const v = out[cc].cli[i]; if (v != null) { s += v * MCC[cc][7]; w += MCC[cc][7]; } }); return w ? s / w : null; }); return EC_CLI = { M, out, diff, glob }; }
const ecPhase = (v, d) => v >= 100 ? (d >= 0 ? ['Expansion', '#2e9e4f'] : ['Downturn', '#e2b93b']) : (d < 0 ? ['Slowdown', '#c0392b'] : ['Recovery', '#2e6bd9']);

/* ---------- GDP fan chart with forecast vintages ---------- */
function ecGdpFan(cc) { const G = mcGen(cc).GDP; if (!G) return null; const yr0 = new Date(END).getUTCFullYear(); const ann = {}; G.d.forEach((t, i) => { const y = new Date(t).getUTCFullYear(); (ann[y] = ann[y] || []).push(G.v[i]); }); const ys = Object.keys(ann).map(Number).filter(y => y < yr0 && ann[y].length >= (G.f === 'Q' ? 3 : 1)).sort(); const hist = ys.map(y => ({ y, v: gyM(ann[y]) })); if (hist.length < 3) return null; const cur = gyM(ann[yr0] || [hist.at(-1).v]); const fv = ecFcVint(cc, 'GDP'); const lr = gyM(hist.slice(-8).map(h => h.v)); const path = (f1, f0) => [{ y: yr0, v: f0 }, { y: yr0 + 1, v: f1 }, { y: yr0 + 2, v: f1 * .5 + lr * .5 }, { y: yr0 + 3, v: lr }]; const now = path(fv.now, cur), old = path(fv.ago6, cur + (fv.ago6 - fv.now) * .6); const sdY = gySd(hist.slice(1).map((h, i) => h.v - hist[i].v)) * .7 || 1; return { hist, now, old, sdY, yr0 }; }

/* ---------- market reaction around central-bank meetings ---------- */
function ecCBReact(code) { const C = CB.find(c => c[0] === code); if (!C) return null; const ev = cbEvents(END - 400 * DAY, END).filter(e => e.id.startsWith('C.' + code + '.') && e.t <= END); const D = NX_D(); const ids = C[5].filter(id => BY[id]); const isY = id => /^YD\./.test(id); const path = (id, t) => { const i = bsLE(D, t); if (i < 6) return null; const b = valAt(id, D[i - 1]); return Array.from({ length: 11 }, (_, j) => { const k = i - 5 + j; if (k >= D.length) return null; const v = valAt(id, D[k]); return isY(id) ? (v - b) * 100 : (v / b - 1) * 100; }); }; return { C, ev, ids, path, isY }; }

