  pg.innerHTML = hdr('studio', `Enter and upload the data that powers country coverage, news, calendars, research and private markets. Only you can open this page; everything you publish is visible to signed-in users and labelled as data-desk content.`, `<span class="badge ${ADM.db ? 'ok' : ''}">${ADM.db ? 'Database connected' : 'Database not connected'}</span><span class="note" id="stuProg">${esc(STU.prog)}</span>`) +
    `<nav class="stu-tabs" role="tablist">${STU_TABS.map(([k, l]) => `<button role="tab" aria-selected="${STU.tab === k}" class="${STU.tab === k ? 'on' : ''}" data-stt="${k}">${l}${{ eco: cnt.s, px: cnt.i, news: cnt.n, cal: cnt.c, res: cnt.r, priv: cnt.p }[k] ? `<span>${{ eco: cnt.s, px: cnt.i, news: cnt.n, cal: cnt.c, res: cnt.r, priv: cnt.p }[k]}</span>` : ''}</button>`).join('')}</nav><div id="stuBody"></div>`;
  const b = $('#stuBody', pg); try { (STU_FN[STU.tab] || STU_FN.ov)(b); } catch (e) { console.error(e); b.innerHTML = `<div class="callout">This view failed: ${esc(e.message)}</div>`; }
