  on(pg, 'click', '[data-sta]', (e, x) => { e.preventDefault(); const [a, k] = [x.dataset.sta, x.dataset.k]; (STU_X[a] || (() => { }))(k, x); });
  on(pg, 'change', '[data-stc]', (e, x) => { const a = x.dataset.stc; if (a === 'fcc') STU.fcc = x.value; if (a === 'flt') STU.flt = x.value; if (a.startsWith('opt.')) { const k = a.slice(4); STU.opt[k] = x.type === 'checkbox' ? x.checked : x.value; } if (a.startsWith('map.')) STU.map[a.slice(4)] = x.value; if (a === 'kind') { STU.kind = x.value; STU.map = stuAutoMap(STU.kind, stuCur().rows[stuCur().hi] || []); } if (a === 'sheet') { STU.si = +x.value; stuSheetInit(); } if (a === 'hi') { const s = stuCur(); s.hi = Math.max(0, +x.value - 1); STU.map = stuAutoMap(STU.kind, s.rows[s.hi] || []); } render(); });
