  eco(el) { const ss = Object.values(ADM.S).filter(x => (!STU.fcc || x.cc === STU.fcc) && stuMatch(x.key, x.name, x.src)).sort((a, b) => a.key.localeCompare(b.key)); el.innerHTML = `<section class="panel">${stuFilt('Filter series')}<button class="btn sm pri" data-sta="newSeries">New series</button><button class="btn sm" data-sta="newDerived">Build an indicator</button></div>${ss.length ? `<div class="tw"><table class="t dense"><thead><tr><th>Series</th><th>Country</th><th>Type</th><th class="r">Obs.</th><th class="r">Latest</th><th>Period</th><th>Feeds</th><th>Updated</th><th></th></tr></thead><tbody>${ss.map(x => { const s = admGet(x.key); const l = admLast(x.key); return `<tr><td><b>${esc(x.name)}</b><div class="sub">${esc(x.key)}${x.unit ? ' · ' + esc(x.unit) : ''}</div></td><td>${esc(ddCN(x.cc))}</td><td class="sub">${x.kind === 'derived' ? 'Derived · ' + esc(ADM_OPS[x.op]?.[0] || x.op) : esc(ADM_FREQ[x.freq] || '')}</td><td class="r">${s ? s.v.length : 0}</td><td class="r">${l ? ddFmt(l.v) : '—'}</td><td class="sub">${l ? fd(l.t) : '—'}</td><td class="sub">${x.mi ? 'Econ. indicators: ' + esc(x.mi) : '—'}</td><td class="sub">${x.upd ? fd(Date.parse(x.upd)) : ''}</td><td class="r" style="white-space:nowrap">${stuDelBtn(x.kind === 'derived' ? 'edDerived' : 'edSeries', x.key)}</td></tr>`; }).join('')}</tbody></table></div>` : '<div class="empty"><b>No series yet</b>Create one or import a spreadsheet.</div>'}</section>`; },
  px(el) { const xs = Object.values(ADM.I).filter(x => (!STU.fcc || (x.meta?.country || BY[x.id]?.country) === STU.fcc) && stuMatch(x.id, BY[x.id]?.name)); el.innerHTML = `<section class="panel">${stuFilt('Filter instruments')}<button class="btn sm pri" data-sta="newInst">Add prices</button></div>${xs.length ? `<div class="tw"><table class="t dense"><thead><tr><th>Instrument</th><th>Status</th><th class="r">Prices</th><th class="r">Last</th><th>Date</th><th>Source</th><th></th></tr></thead><tbody>${xs.map(x => `<tr><td>${lnk(x.id)}<div class="sub">${esc(BY[x.id]?.name || x.meta?.name || '')}</div></td><td class="sub">${x.new ? 'New instrument' : 'Overrides existing'}</td><td class="r">${x.pts.length}</td><td class="r">${x.pts.length ? nf(x.pts.at(-1)[1], 2) : '—'}</td><td class="sub">${x.pts.length ? fd(x.pts.at(-1)[0]) : ''}</td><td class="sub">${esc(x.src || '')}</td><td class="r" style="white-space:nowrap">${stuDelBtn('edInst', x.id)}</td></tr>`).join('')}</tbody></table></div>` : '<div class="empty"><b>No prices yet</b>Add prices for an existing instrument (for example Nigerian yields or the NGX index) or create new ones such as listed Nigerian stocks.</div>'}</section>`; },
