    if (kind === 'px') return { use: true, name: sscStr(r.name, 120), tk: sscStr(r.ticker, 30).toUpperCase(), close: sscNum(r.close), open: sscNum(r.open), high: sscNum(r.high), low: sscNum(r.low), vol: sscNum(r.volume), date: sscDate(r.date) || asOf, type: ADM_TYPES[sscStr(r.type, 20).toLowerCase()] ? sscStr(r.type, 20).toLowerCase() : 'equity', cc: ddCC(sscStr(r.country, 40)) || cc0 };
    if (kind === 'eco') return { use: true, code: admId(sscStr(r.indicator, 20) || sscStr(r.name, 20)).toUpperCase().slice(0, 20), name: sscStr(r.name, 120), value: sscNum(r.value), unit: sscStr(r.unit, 30), period: sscStr(r.period, 12), cc: ddCC(sscStr(r.country, 40)) || cc0 };
    if (kind === 'cal') return { use: true, title: sscStr(r.title, 200), date: sscDate(r.date) || asOf, time: /^\d{1,2}:\d{2}$/.test(sscStr(r.time, 5)) ? sscStr(r.time, 5) : '', cc: ddCC(sscStr(r.country, 40)) || cc0, cat: ADM_CALCAT[sscStr(r.category, 10)] ? sscStr(r.category, 10) : 'eco', actual: sscStr(r.actual, 30), cons: sscStr(r.consensus, 30), prior: sscStr(r.prior, 30) };
    if (kind === 'news') return { use: true, title: sscStr(r.title, 200), date: sscDate(r.date) || asOf, cc: ddCC(sscStr(r.country, 40)) || cc0, sum: sscStr(r.summary, 600) };
