  const q = id => mfQ(id);
  const qt = (label, id, sub) => { const x = q(id); if (!x) return `<div class="hm-t"><span>${esc(label)}</span><b>—</b><small>not covered yet</small></div>`; const y = x.o.type === 'yield'; let ytd = null; try { ytd = y ? null : perf(id, 'YTD'); } catch (z) { } return `<div class="hm-t"><span>${esc(label)}</span><b>${lnk(id, x.o.tk)} ${fv(x.o, x.q.last)}</b><em class="${cls(y ? x.q.bp : x.q.pct)}">${y ? bpf(x.q.bp, 1) : pc(x.q.pct)}${ytd != null ? ` <i class="muted">· YTD ${pc(ytd, 1)}</i>` : ''}</em><small>${hmTag(id)} ${fd(x.q.date, { day: '2-digit', month: 'short' })}${sub ? ' · ' + esc(sub) : ''}</small></div>`; };
  const mt = (label, k) => { const m = hmMacro(e, k); if (!m) return ''; return `<div class="hm-t"><span>${esc(label)}</span><b>${mcFmt(k, m.v)}${/%/.test(MI[k]?.[2] || '') ? '%' : ''}</b><em class="${m.chg == null || !MI[k]?.[5] ? '' : cls(MI[k][5] === -1 ? -m.chg : m.chg)}">${m.chg == null ? '' : Math.abs(m.chg) < Math.pow(10, -(MI[k]?.[4] ?? 1)) / 2 ? 'unchanged vs prior' : sgn(m.chg, MI[k]?.[4] ?? 1) + ' vs prior'}</em><small>${m.desk ? '<span class="badge live desk">DESK</span>' : '<span class="badge sim">SIM</span>'} ${fd(m.ref || m.t, { month: 'short', year: '2-digit' })}</small></div>`; };
  const bill = ['3M', '6M', '1Y'].map(t => `YD.${hmCcs(cc).find(c => BY[`YD.${c}${t}`]) || cc}${t}`).find(id => BY[id]);
  const stocks = hmStocks(cc).map(o => { try { const x = quote(o.id); return { o, x }; } catch (z) { return null; } }).filter(r => r && isFinite(r.x.pct)).sort((a, b) => b.x.pct - a.x.pct);
  const ev = (typeof ADM !== 'undefined' ? ADM.cal : []).filter(x => hmCcs(cc).includes(x.cc) && Date.parse(x.date) >= END - DAY).sort((a, b) => (a.date + (a.time || '')).localeCompare(b.date + (b.time || ''))).slice(0, 5);
  const nw = (typeof ADM !== 'undefined' ? ADM.news : []).filter(x => (x.cc || []).some(c => hmCcs(cc).includes(c))).slice(0, 5);
