    <div class="hm-tiles">${qt('Stock index', homeIdx(cc))}${qt(cc === 'US' ? 'Dollar index' : `Currency · ${mfCcy(cc)} per USD`, cc === 'US' ? 'FX.DXY' : COUNTRY[cc]?.fx, cc === 'SN' || cc === 'CI' ? 'fixed to the euro' : '')}${COUNTRY[cc]?.y ? qt('10-year government yield', COUNTRY[cc].y) : ''}${bill ? qt('Treasury bill', bill) : ''}${mt('Policy rate', 'POL')}${mt('Inflation', 'CPI')}${mt('GDP growth', 'GDP')}${cmdId ? qt('Key commodity', cmdId) : ''}</div>
