/* movers: a universe of the home market's instruments */
function mvHomeSet() { const cc = hmCC(); if (cc === 'US') return EQ; const set = U.filter(o => hmCcs(cc).includes(o.country) && !isRate(o) && o.type !== 'bond' && o.type !== 'econ'); const fx = COUNTRY[cc]?.fx; if (fx && BY[fx] && !set.includes(BY[fx])) set.push(BY[fx]); return set; }
