  const secs = [...new Set(all.map(r => r.sec))].sort(); const ccy = all[0].ccy; const t1 = Math.max(...all.map(r => r.t)), t0 = Math.min(...all.map(r => r.t0));
  const FL = [['pxMin', `Price min (${ccy})`], ['pxMax', `Price max (${ccy})`], ['d1Min', 'Day change min (%)'], ['d1Max', 'Day change max (%)'], ['chMin', 'Change over recorded history min (%)'], ['chMax', 'Change over recorded history max (%)'], ['nMin', 'Days of data min']];
  pg.innerHTML = hdr('screener', `Screen ${all.length} ${esc(nm)} stocks on the closing prices recorded by the data desk (${fd(t0, { day: '2-digit', month: 'short' })} to ${fd(t1, { day: '2-digit', month: 'short', year: 'numeric' })}). Market cap, P/E, dividends and margins are not available for these stocks yet, so only price fields are offered.`, `${tog}<button class="btn" id="hswl">Add results to watchlist</button>`) +
    `<section class="panel"><div class="pb" style="display:flex;flex-direction:column;gap:10px"><div class="row">${secs.map(s => `<button class="chip ${f.sec.includes(s) ? 'on' : ''}" data-hsc="${esc(s)}">${esc(s)}</button>`).join('')}</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:8px">${FL.map(([k, l]) => `<label class="f"><span>${esc(l)}</span><input class="inp sm" type="number" step="any" data-hfk="${k}" value="${f[k] ?? ''}"></label>`).join('')}</div><div class="row"><span id="hcnt" class="note"></span><button class="btn sm ghost" id="hclr">Clear filters</button></div></div></section><section class="panel"><div id="hres"></div><div class="pb"><p class="note"><span class="badge live desk">DESK</span> Delayed closes entered by the data desk; each stock's source is listed. Change over recorded history covers only the days recorded, not a standard period.</p></div></section>`;
