  const groups = {}; Object.entries(map).forEach(([c, r]) => { const R = ROUTES[r]; const g = (R.m === 'pri' ? 'Private markets · ' : R.m === 'pub' ? 'Public markets · ' : '') + (R.e || R.g || 'Other'); (groups[g] = groups[g] || []).push([c, r]); });
