    const capex = rev * i.capex / 100; const dnwc = (rev - prevRev) * i.nwc / 100; const fcf = ebit - tax + da - capex - dnwc;
    const tt = i.mid ? t - .5 : t; const df = 1 / Math.pow(1 + i.wacc / 100, tt); pv += fcf * df;
