  safes.forEach((s, k) => out.push({ name: s.name, cls: s.cls || (s.note ? 'Converted note' : 'Converted SAFE'), kind: 'pref', shares: Ss[k], invested: s.invested, liq: 1, part: 'none', sen: r.sen ?? 0, conv: true }));
