  const st = { U: 0, Q: 0, lpP: 0, gp: 0 }; const rows = [];
  for (let t = 1; t <= Y; t++) { st.U += contrib[t]; st.Q += (st.Q + st.U) * (i.pref / 100); const o = PM.tier(st, dist[t], T); rows.push({ t, inv: inv[t], fee: fee[t], contrib: contrib[t], dist: dist[t], ...o }); }
  /* American (deal-by-deal): each deal carries its own capital plus a pro-rata share of fees; no netting of losses */
  const totInv = i.deals.reduce((a, d) => a + d.amt, 0); const totFee = fee.reduce((a, v) => a + v, 0); let amCarry = 0; const amGP = Array(Y + 1).fill(0);
  i.deals.forEach(d => { const cap = d.amt + totFee * d.amt / (totInv || 1); const s = { U: cap, Q: 0, lpP: 0, gp: 0 }; for (let t = d.y0; t <= d.y1; t++) s.Q += (s.Q + s.U) * (i.pref / 100); const o = PM.tier(s, d.amt * d.mult, T); amCarry += o.toGP; if (d.y1 <= Y) amGP[d.y1] += o.toGP; });
  const lpShare = 1 - i.gpc / 100; let cP = 0, cD = 0; const series = rows.map(r => { cP += r.contrib; cD += r.toInv; const nv = nav[r.t]; return { ...r, nav: nv, paid: cP, cumDist: cD, dpi: cP ? cD / cP : 0, rvpi: cP ? nv / cP : 0, tvpi: cP ? (cD + nv) / cP : 0 }; });
  const cfInv = [0, ...rows.map(r => r.toInv - r.contrib)]; const cfGross = [0, ...rows.map(r => r.dist - r.inv)];
  const investors = i.lps.map(l => { const w = l.pct / 100 * lpShare; const cf = [0, ...rows.map(r => (r.toInv - r.contrib) * w)]; const paid = rows.reduce((a, r) => a + r.contrib * w, 0), got = rows.reduce((a, r) => a + r.toInv * w, 0); return { name: l.name, cf, irr: PM.irr(cf.slice(1)), moic: paid ? got / paid : null, paid, got }; });
  const gpcf = [0, ...rows.map(r => (r.toInv - r.contrib) * (i.gpc / 100) + r.toGP)]; const gpPaid = rows.reduce((a, r) => a + r.contrib * i.gpc / 100, 0), gpGot = rows.reduce((a, r) => a + r.toInv * i.gpc / 100 + r.toGP, 0);
