    pmLines($('#pi2', R), { xs: S.qs.map((_, k) => k), xf: k => fd(S.qs[Math.round(k)] || END, { month: 'short', year: '2-digit' }), yf: v => nf(v, 0) + '%', series: [{ label: 'Gross IRR', values: S.pts.map(x => x.gIrr == null ? null : clamp(x.gIrr, -100, 300)), c: 'var(--s4)' }, { label: 'Net IRR', values: S.pts.map(x => x.nIrr == null ? null : clamp(x.nIrr, -100, 300)), c: 'var(--dn)' }] });
    const grp = ['Realised', 'Unrealised'].map(s => { const xs = ps.filter(p => s === 'Realised' ? p.status === 'Realised' : p.status !== 'Realised'); const c = xs.reduce((a, p) => a + p.h.cost, 0); return { s, n: xs.length, cost: c, com: c + xs.reduce((a, p) => a + (p.h.reserve || 0), 0), tvpi: c ? xs.reduce((a, p) => a + p.fv + p.realized, 0) / c : null, avg: xs.length ? xs.reduce((a, p) => a + p.fv, 0) / xs.length : null, rgl: xs.reduce((a, p) => a + (p.status === 'Realised' ? p.realized - p.h.cost : p.realized), 0), ugl: xs.reduce((a, p) => a + (p.fv ? p.fv - p.h.cost : 0), 0), rem: xs.reduce((a, p) => a + (p.fv ? p.h.cost : 0), 0) }; });
    table($('#pi3', R), { dense: true, rows: grp, cols: [{ k: 's', h: 'Status', f: r => `${esc(r.s)} <span class="muted">${r.n}</span>` }, { k: 'c', h: 'Capital invested', a: 'r', f: r => $m(r.cost, 2) }, { k: 'cm', h: 'Committed', a: 'r', f: r => $m(r.com, 2) }, { k: 't', h: 'TVPI', a: 'r', f: r => xF(r.tvpi, 2) }, { k: 'a', h: 'Avg. FMV', a: 'r', f: r => $m(r.avg, 2) }, { k: 'rg', h: 'Realised G/L', a: 'r', f: r => `<span class="${cls(r.rgl)}">${$m(r.rgl, 2)}</span>` }, { k: 'ug', h: 'Unrealised G/L', a: 'r', f: r => `<span class="${cls(r.ugl)}">${$m(r.ugl, 2)}</span>` }, { k: 'rc', h: 'Remaining cost', a: 'r', f: r => $m(r.rem, 2) }] });
    table($('#pi4', R), { dense: true, rows: ps.map(p => ({ p, n: pmPosNet(p) })), csv: 'investments', sort: { k: 'fmv', d: -1 }, cols: [{ k: 'n', h: 'Investment', v: r => r.p.c.name, f: r => coLnk(r.p.c), csv: r => r.p.c.name }, { k: 'v', h: 'Vehicle', f: r => esc(r.p.h.vehicle), csv: r => r.p.h.vehicle }, { k: 'sr', h: 'Deal source', f: r => esc(r.p.h.src), csv: r => r.p.h.src }, { k: 'st', h: 'Status', f: r => esc(r.p.status), csv: r => r.p.status }, { k: 'tv', h: 'TVPI', a: 'r', v: r => r.p.moic, f: r => xF(r.p.moic, 2) }, { k: 'fmv', h: 'FMV', a: 'r', v: r => r.p.fv, f: r => $m(r.p.fv, 2), csv: r => r.p.fv.toFixed(3) }, { k: 'gi', h: 'Gross IRR', a: 'r', v: r => r.p.irr, f: r => `<span class="${cls(r.p.irr)}">${pF(r.p.irr)}</span>` }, { k: 'ni', h: 'Net IRR', a: 'r', v: r => r.n?.nIrr, f: r => `<span class="${cls(r.n?.nIrr)}">${pF(r.n?.nIrr)}</span>` }, { k: 'cm', h: 'Committed', a: 'r', f: r => $m(r.p.h.cost + (r.p.h.reserve || 0), 2) }, { k: 'in', h: 'Invested', a: 'r', v: r => r.p.h.cost, f: r => $m(r.p.h.cost, 2) }, { k: 'rc', h: 'Remaining cost', a: 'r', f: r => $m(r.p.fv ? r.p.h.cost : 0, 2) }, { k: 'd', h: 'Distributions', a: 'r', f: r => $m(r.p.realized, 2) }, { k: 'u', h: 'Unrealised G/L', a: 'r', f: r => `<span class="${cls(r.p.fv ? r.p.fv - r.p.h.cost : 0)}">${$m(r.p.fv ? r.p.fv - r.p.h.cost : 0, 2)}</span>` }, { k: 'rg', h: 'Realised G/L', a: 'r', f: r => `<span class="${cls(r.p.status === 'Realised' ? r.p.realized - r.p.h.cost : 0)}">${$m(r.p.status === 'Realised' ? r.p.realized - r.p.h.cost : r.p.realized, 2)}</span>` }, { k: 'ed', h: '', f: r => `<button class="btn sm ghost" data-ped="${r.p.h.id}">Edit</button>` }] });
