function pmBudget(c) { const K = pmKpi(c); const r = rng(hash('bud-' + c.id)); const bias = K.worsen ? .14 : .05; return { rev: K.usd.map(v => v * (1 + bias + (r() - .5) * .08)), em: K.em.map(v => v + (K.worsen ? 6 : 2.5) + (r() - .5) * 2) }; }
