  const gmL = Ks.map(x => ({ l: x.p.c.name, v: x.K.gm[N - 1] })).sort((a, b) => b.v - a.v); const avg = gmP[L], best = Math.max(...gmL.map(r => r.v));
  pmBarsRef($('#pk2', el), { rows: gmL, max: 100, marks: [{ l: 'Average', v: avg, c: 'var(--s2)' }, { l: 'Best', v: best, c: 'var(--s5)' }] });
