    const facts = { as_of: iso(END), note: 'Companies entered by the data desk or the user\'s organization; quarterly history modelled from their inputs; USD millions; quarters end on the dates shown.', weighting: PT.kw ? 'ownership-weighted' : 'company totals', quarters: qe.map(iso), portfolio: { revenue: rev.map(v => r2(v, 2)), gross_profit: gp.map(v => r2(v, 2)), gross_margin_pct: gmP.map(v => r2(v, 1)), ebitda: eb.map(v => r2(v, 2)), cash: cash.map(v => r2(v, 1)) }, companies: Ks.map(x => ({ name: x.p.c.name, revenue: ix.map(k => r2(x.K.usd[k], 2)), gross_margin_pct: ix.map(k => r2(x.K.gm[k], 1)), ebitda_margin_pct: ix.map(k => r2(x.K.em[k], 1)), cash: ix.map(k => r2(x.K.cash[k], 1)), runway_months: r2(x.K.runway[N - 1], 0), revenue_vs_budget_last_q_pct: r2((x.K.usd[N - 1] / pmBudget(x.p.c).rev[N - 1] - 1) * 100, 1) })) };
