  live.filter(r => r.kind === 'co').forEach(r => { const c = pfCoObj(r); if (c) { PFCOS.push(c); PCO[c.id] = c; } });
  PFCOS.sort((a, b) => a.name.localeCompare(b.name)); PFFUNDS.sort((a, b) => b.vintage - a.vintage || a.name.localeCompare(b.name));
