const SD_FIN = [['rev', 'Revenue'], ['gp', 'Gross profit'], ['op', 'Operating income'], ['ebitda', 'EBITDA'], ['ni', 'Net income'], ['eps', 'EPS (diluted)'], ['dps', 'Dividend per share'], ['assets', 'Total assets'], ['liab', 'Total liabilities'], ['equity', "Shareholders' equity"], ['cash', 'Cash & equivalents'], ['debt', 'Total debt'], ['ocf', 'Operating cash flow'], ['capex', 'Capital expenditure'], ['fcf', 'Free cash flow'], ['sh', 'Shares outstanding']];
