const SD_VAL = [['price', 'Last price'], ['pdate', 'Price date (YYYY-MM-DD)'], ['mcap', 'Market cap'], ['ev', 'Enterprise value'], ['pe', 'P/E (TTM)'], ['fpe', 'Forward P/E'], ['pb', 'Price / book'], ['ps', 'Price / sales'], ['evebitda', 'EV / EBITDA'], ['div', 'Dividend yield (%)'], ['beta', 'Beta'], ['hi52', '52-week high'], ['lo52', '52-week low'], ['nextEarn', 'Next results date (YYYY-MM-DD)']];
