  const nm = s.name ? (u ? `<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a>` : esc(s.name)) : '<span class="cr-miss">Source not recorded</span>';
  const asof = (part && D[part]?.asof) || D.asof; const upd = D.upd ? fd(Date.parse(D.upd)) : '';
  return `<div class="sd-cred">${pmTag('desk', 'Entered by the Superfinancials data desk')} <span>Source: ${nm}${asof ? `; as of ${esc(asof)}` : ''}${upd ? `; entered ${esc(upd)}` : ''}.</span></div>`;
