    if (sdv !== ADM.ver) { SDF.clear(); sdv = ADM.ver; } if (SDF.has(id)) return SDF.get(id);
    const g = { ...f }; const v = D.val || {}; const n = k => sdN(v[k]);
    const fin = D.fin || {}; const mul = SD_UNIT[fin.unit || 'u'][1]; const per = fin.periods || [];
    const row = k => (fin.rows || []).find(r => r.k === k); const last = k => { const r = row(k); if (!r) return null; for (let i = per.length - 1; i >= 0; i--) { const x = sdN(r.v?.[i]); if (x != null) return SD_PERSH.has(k) ? x : x * mul; } return null; };
    const set = (k, x) => { if (x != null && isFinite(x)) g[k] = x; };
    set('mcap', n('mcap')); set('pe', n('pe')); set('fpe', n('fpe')); set('pb', n('pb')); set('ps', n('ps')); set('evE', n('evebitda')); set('div', n('div')); set('beta', n('beta'));
    set('rev', last('rev')); set('ni', last('ni')); set('eps', last('eps'));
    if (g.rev && last('gp') != null) g.gm = last('gp') / g.rev * 100; if (g.rev && last('op') != null) g.om = last('op') / g.rev * 100; if (g.rev && last('ni') != null) g.nm = last('ni') / g.rev * 100;
