    const meta = $('.phd .meta', pg); if (meta) meta.insertAdjacentHTML('beforeend', `<span class="badge live desk" title="Extra details entered by the data desk${D.src ? ': ' + esc(D.src) : ''}">DESK details</span>`);
    const bar = $('.tabs[role="tablist"]', pg); if (!bar) return;
    const cur = $('[data-tab].on', bar)?.dataset.tab || 'overview';
    bar.innerHTML = sdTabs(o, D).map(([k, l]) => `<button role="tab" data-tab="${k}" class="${k === cur ? 'on' : ''}">${esc(l)}</button>`).join('');
