    pg.addEventListener('click', e => { const b = e.target.closest('[data-tab]'); if (!b || !pg.contains(b) || !owned(b.dataset.tab)) return; e.stopPropagation(); $$('[data-tab]', pg).forEach(x => x.classList.toggle('on', x === b)); paint(b.dataset.tab); }, true);
