  if (kind === 'table') { const split = l => (l.includes('\t') ? l.split('\t') : l.split(/,(?![^"]*"(?:[^"]*"[^"]*")*[^"]*$)/)).map(x => x.trim().replace(/^"|"$/g, '')); const [h, ...rs] = lines; return { cols: h ? split(h).slice(0, 20) : [], rows: rs.slice(0, 500).map(l => ({ c: split(l).slice(0, 20) })) }; }
  return { text: String(txt || '').slice(0, 20000) };
