  trimObj(x); ['profile', 'val', 'perf'].forEach(k => { x[k] = trimObj(x[k] || {}); if (x[k].extra) x[k].extra = x[k].extra.map(trimObj).filter(r => r.k); });
  x.fin.periods = (x.fin.periods || []).map(p => String(p || '').trim()); x.fin.rows = (x.fin.rows || []).map(r => ({ k: r.k, l: String(r.l || '').trim(), v: x.fin.periods.map((_, i) => String(r.v?.[i] ?? '').trim()) })).filter(r => r.v.some(v => v) && (r.l || !r.k.startsWith('x')));
  ['src', 'srcUrl', 'asof'].forEach(k => { if (blank(x.fin[k])) delete x.fin[k]; });
  ['divs', 'holders', 'notes'].forEach(k => { x[k] = (x[k] || []).map(trimObj).filter(r => Object.keys(r).length); });
