STU_K.mov = { n: 'Market movers (gainers, decliners, most active)', f: [['instrument', 'Ticker / instrument', 1], ['date', 'Session date'], ['market', 'Market (country code)'], ['list', 'List (gainers, decliners, most active)'], ['name', 'Name'], ['price', 'Price'], ['change', 'Change %'], ['volume', 'Volume'], ['reason', 'Reason'], ['source', 'Source'], ['source_url', 'Source URL']], ex: [['DANGCEM', '2026-10-29', 'NG', 'gainers', 'Dangote Cement', 512.5, 9.98, 1250000, '', 'NGX Daily Official List', 'https://ngxgroup.com'], ['ZENITHBANK', '2026-10-29', 'NG', 'decliners', 'Zenith Bank', 48.1, -4.2, 22100000, '', 'NGX Daily Official List', 'https://ngxgroup.com']] };
STU_SYNK.mov = { instrument: /^(instrument|ticker|symbol|security|stock|company|code)$/, list: /^(list|mover|movers|category|table|type)$/, price: /^(price|close|closeprice|last|lastprice)/, change: /^(change|chg|pctchange|changepct|percentchange|%change|changepercent|return|pchg)/, volume: /^(vol|volume|deals|units)/, reason: /^(reason|why|catalyst|note|notes|comment)/, market: /^(market|country|exchange|cc)$/ };
