  prev: [['m', 'Market', r => r.cc], ['t', 'Session', r => admIso(r.t)], ['l', 'List', r => MVD_L[r.l]], ['k', 'Ticker', r => r.ins ? r.tk : r.tk + ' (not on the platform)'], ['c', 'Change %', r => r.chg ?? '—']],
