  el.oninput = e => { const i = e.target; if (!CBX.d) return; if (i.dataset.cbp && (i.tagName === 'TEXTAREA' || i.type === 'text' || i.tagName === 'INPUT' && i.type !== 'checkbox')) { cbSet(CBX.d, i.dataset.cbp, val(i)); if (i.dataset.cbp === 'title') { const h = $('#cbpT', el); if (h) h.textContent = CBX.d.title || 'Untitled chart'; } else prev(); } };
