function vtFloating(F, t = Date.now()) { return F.filter(v => ['crude', 'product'].includes(v.type)).map(v => { const L = vtLoadQ(v); if (L.st !== 'loaded' && L.st !== 'part') return null; let i = v.track.length - 1; if (i < 0) return null; const last = v.track[i]; if ((last[3] || 0) > 1 || t - last[0] > 48 * HR) return null; while (i > 0 && (v.track[i - 1][3] || 0) <= 1 && vtKm([v.track[i - 1][1], v.track[i - 1][2]], [last[1], last[2]]) < 25) i--; const days = (last[0] - v.track[i][0]) / (24 * HR); const port = vtNearPort(last[1], last[2], 15); return days >= 20 && !port ? { v, days, lat: last[1], lon: last[2] } : null; }).filter(Boolean); }
function vtCongestion(F, t = Date.now()) { return Object.entries(VT_PORTS).map(([k, p]) => { const near = F.map(v => ({ v, q: vtAt(v, t) })).filter(x => x.q && (x.q.sog || 0) <= 1 && vtKm([p[2], p[3]], [x.q.lat, x.q.lon]) <= 60); const waits = near.map(x => { let i = x.v.track.length - 1; while (i > 0 && (x.v.track[i - 1][3] || 0) <= 1) i--; return (t - x.v.track[i][0]) / HR; }); const past = [7, 14, 21, 28].map(dd => F.filter(v => { const q = vtAt(v, t - dd * 24 * HR); return q && (q.sog || 0) <= 1 && vtKm([p[2], p[3]], [q.lat, q.lon]) <= 60; }).length); const base = past.reduce((a, b) => a + b, 0) / past.length; return { k, p, n: near.length, wait: waits.length ? waits.reduce((a, b) => a + b, 0) / waits.length : 0, base, list: near }; }).filter(x => x.n > 0).sort((a, b) => b.n - a.n); }
