/* alert engine: observation (what the data shows), hypothesis (what it could mean), evidence */
function vtAlerts(F, t = Date.now()) {
  const A = []; const add = (k, sev, title, obs, hyp, ev, v) => A.push({ k, sev, title, obs, hyp, ev, v, ill: v ? v.src === 'demo' : F.length && F.every(x => x.src === 'demo') });
  F.forEach(v => { const last = v.track.at(-1); if (!last) return;
    const quiet = (t - last[0]) / HR; if (quiet > 24 && quiet < 21 * 24 && (last[3] || 0) > 1) add('dark', 'warn', `AIS disappearance · ${v.name}`, `No position for ${nf(quiet, 0)} hours; last report at ${fdt(last[0])} moving at ${last[3]} kn near ${nf(last[1], 2)}, ${nf(last[2], 2)}.`, 'Coverage gap (satellite AIS can have delays), equipment problem, or the transponder switched off deliberately.', `Last report ${fdt(last[0])}`, v);
    if (v.destHist?.length >= 2) { const [a, b] = v.destHist.slice(-2); if (a[1] !== b[1] && t - b[0] < 14 * 24 * HR) add('dest', 'info', `Destination switching · ${v.name}`, `Declared destination changed from ${a[1]} to ${b[1]} on ${fd(b[0])}.`, 'A cargo resale, a change in refinery demand or routing for orders. Declared destinations are typed by the crew and can be wrong.', `Destination history: ${v.destHist.map(x => `${fd(x[0])} ${x[1]}`).join(' → ')}`, v); }
    const pk = vtPortKey(v.dest); if (pk && (last[3] || 0) > 5 && t - last[0] < 12 * HR) { const pts = v.track.filter(p => p[0] >= t - 24 * HR); if (pts.length >= 2) { const rl = q => { const R = vtRouteFrom([q[1], q[2]], pk); return R ? vtLen(R) : null; }; const d0 = rl(pts[0]), d1 = rl(pts.at(-1)); const P2 = VT_PORTS[pk]; const s0 = vtKm([pts[0][1], pts[0][2]], [P2[2], P2[3]]), s1 = vtKm([pts.at(-1)[1], pts.at(-1)[2]], [P2[2], P2[3]]); if (d0 != null && d1 != null && d1 - d0 > 80 && s1 - s0 > 30) add('dev', 'warn', `Route deviation · ${v.name}`, `The remaining sea route to its declared destination (${v.dest}) grew by ${nf(d1 - d0, 0)} km in 24 hours.`, 'A change of destination not yet declared, waiting for orders, or avoiding a risk area.', `Remaining route to ${v.dest}: ${nf(d0, 0)} → ${nf(d1, 0)} km (estimated along shipping lanes)`, v); } }
    (v.sts || []).filter(s => t - s.t < 30 * 24 * HR).forEach(s => add('sts', 'warn', `Ship-to-ship transfer · ${v.name}`, `Stationary alongside ${s.with} at sea near ${nf(s.lat, 2)}, ${nf(s.lon, 2)} on ${fd(s.t)}.`, 'A cargo transfer between the two ships (labelled ' + (s.q || 'estimated') + '); could also be bunkering or waiting together.', `Both vessels slow and within a few hundred metres, away from a port`, v));
    (v.sanc || []).forEach(s => add('sanc', s.sev === 'dn' ? 'dn' : 'warn', `Sanctions exposure · ${v.name}`, `${s.k}: ${s.txt}`, 'Check the listing before any decision; a flag is an indicator, not a determination.', `Source: ${s.src || 'not recorded'}`, v)); });
  vtFloating(F, t).forEach(f => add('float', 'info', `Floating storage · ${f.v.name}`, `Loaded (${vtLoadQ(f.v).q}) and stationary for ${nf(f.days, 0)} days at sea near ${nf(f.lat, 2)}, ${nf(f.lon, 2)}, away from any port.`, 'Storage at sea (contango economics), waiting for a buyer or a discharge slot, or port congestion nearby.', 'Speed ≤ 1 kn for 20+ days; draught consistent with cargo aboard', f.v));
  vtCongestion(F, t).filter(c => c.n >= 3 && c.n >= 1.8 * Math.max(1, c.base)).forEach(c => add('cong', 'warn', `Port congestion · ${c.p[0]}`, `${c.n} vessels waiting within 60 km (4-week average ${nf(c.base, 1)}); average wait ${nf(c.wait / 24, 1)} days.`, 'More arrivals than the terminal can handle, weather, inspections, or floating storage near the port. Watch departures before reading it as higher imports.', c.list.slice(0, 6).map(x => x.v.name).join(', '), null));
  const e = VT_EIA.v; Object.entries(e).forEach(([k, a]) => { const prev = a[5], now2 = a[6]; if (prev && now2 / prev - 1 <= -.25) add('supply', 'dn', `Supply disruption · ${VT_CP[k][0]}`, `Oil flows of ${now2} mb/d in 2Q26 against ${prev} mb/d in 1H25 (${pc((now2 / prev - 1) * 100)}).`, 'Reported by EIA. The drop reflects the conflict affecting Gulf exports; rerouting shows up as higher flows elsewhere.', VT_EIA.src, null); });
  A.forEach(a => { if (a.k === 'supply') a.ill = false; });
  return A.sort((a, b) => ({ dn: 0, warn: 1, info: 2 })[a.sev] - ({ dn: 0, warn: 1, info: 2 })[b.sev]);
}
const VT_AK = { dark: 'AIS disappearance', dest: 'Destination switching', dev: 'Route deviation', sts: 'Ship-to-ship transfer', sanc: 'Sanctions exposure', float: 'Floating storage', cong: 'Port congestion', supply: 'Supply disruption' };

/* ---------- map ---------- */
