KB.fc = KB.fc || { reports: [], cc: {} }; KB.rs = KB.rs || []; KB.rt = KB.rt || { decisions: {}, curves: {}, eurobonds: {} }; KB.eq = KB.eq || []; KB.ep = KB.ep || [];
