{ const _x = kbContext; kbContext = function (q) { const C = _x(q); const R = C.R; const add = []; R.cc.slice(0, 3).forEach(cc => { const g = kbFcFor(cc, 'gdp').slice(0, 2), c = kbFcFor(cc, 'cpi').slice(0, 2); if (g.length || c.length) add.push(`FORECASTS ${cc}: ${JSON.stringify({ gdp: g.map(f => ({ src: kbRepLbl(f.id), v: f.v })), cpi: c.map(f => ({ src: kbRepLbl(f.id), v: f.v })) })}`); const d = (KB.rt.decisions?.[cc] || []).slice(0, 2); if (d.length) add.push(`DECISIONS ${cc}: ${JSON.stringify(d.map(x => ({ date: x.date, action: x.action, bp: x.bp, rate: x.rate, rationale: x.rationale, guidance: x.guidance })))}`); const cv = KB.rt.curves?.[cc]; if (cv) add.push(`CURVE ${cc} ${cv.date}: ${JSON.stringify(cv.pts)}`); }); kbDocsFor(R, 3).forEach(r => add.push(`REPORT ${r.publisher} "${r.title}" (${r.date}): ${r.summary} Findings: ${(r.findings || []).slice(0, 5).map(f => f.t).join(' | ')}`)); kbEqFind(R).slice(0, 2).forEach(e => add.push(`INDEX ${e.name}: ${JSON.stringify({ level: e.level, ytd: e.ytd, pe: e.pe, dy: e.dy, top: (e.top || []).slice(0, 5), annual: e.annual })}`)); C.txt = (C.txt + '\n' + add.join('\n')).slice(0, 22000); C.n += add.length; return C; }; }
