    calc: I => { const eq = ((1 + I.eps / 100) * I.pe1 / I.pe0 - 1) * 100; const hy = -I.hydur * (I.hy - I.hy0) / 100; return [{ k: 'eq', l: 'S&P 500 change', v: eq, u: '%', how: '(1 + earnings change) × trough P/E ÷ P/E today − 1' }, { k: 'hy', l: 'High-yield price change from spreads', v: hy, u: '%', how: '− duration × spread widening' }]; },
    direct: ['Earnings and employment fall; credit spreads widen.', 'Central banks cut rates; bond yields fall.'], second: ['Defaults rise among leveraged borrowers.', 'Commodity prices and exporter currencies fall.', 'Fiscal deficits widen.'],
    assets: [['Global equities', 'down'], ['Government bonds', 'up'], ['Credit spreads', 'up'], ['Commodities', 'down'], ['US dollar and yen', 'up']], winners: ['Government bonds', 'Defensive sectors (staples, healthcare, utilities)', 'Quality balance sheets'], losers: ['Cyclicals and small caps', 'High-yield credit', 'Commodity exporters', 'EM currencies'], inst: ['banks', 'private_credit', 'em_debt'], hist: ['gfc_2008', 'covid_crash_2020', 'dotcom_bust_2000'], monitor: ['PMIs below 50', 'Initial jobless claims', 'Earnings revisions', 'High-yield spreads', 'Yield-curve shape'],
