{ const _s = scDecorate; scDecorate = function (root) { _s(root); try { $$('.sc-btn', root || document).forEach(b => { if (b.parentElement.querySelector('.cpx-ask')) return; const a = document.createElement('button'); a.type = 'button'; a.className = 'sc-btn cpx-ask'; a.title = 'Ask Copilot to analyse this chart'; a.innerHTML = '<svg viewBox="0 0 16 16" width="13" height="13" aria-hidden="true"><path d="M3 12V4h10v6H6l-3 2z" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/></svg><span>Ask Copilot</span>'; b.after(a); }); } catch (e) { } }; }
