/* ---------- data-status pop-up: Explain this movement ---------- */
{ const _u = ubOpen; ubOpen = function (id) { _u(id); try { const m = [...document.querySelectorAll('.mw .md')].at(-1); if (m && BY[id] && !m.querySelector('.cpx-why')) { const b = document.createElement('button'); b.className = 'btn sm cpx-why'; b.textContent = 'Explain this movement'; b.onclick = () => { m.querySelector('[data-x]')?.click(); m.closest('.mw')?.remove(); cpAsk(`Why is ${BY[id].name} moving?`, { kind: 'instrument', id, text: `Instrument: ${BY[id].name} (${id})` }); }; (m.querySelector('.ub-hd') || m.querySelector('.mb')).after(b); } } catch (e) { } }; }
