const NI_CAT = [['Monetary policy', /central bank|rate (hike|cut|decision)|hikes?|cuts? rates?|holds? rates?|mpc|fomc|ecb|boe|boj|cbn|sarb|policy rate|monetary/], ['Geopolitical', /war|sanction|conflict|attack|missile|election|coup|tariff|blockade|strait|military|ceasefire|hormuz/], ['Corporate earnings', /earnings|results|profit|revenue|quarterly|guidance|eps\b/], ['Financial distress', /bankrupt|insolven|distress|collapse|bailout|rescue|liquidation/], ['Credit event', /default|restructur|downgrade|missed payment|spread widen|credit event|rating/], ['Mergers & acquisitions', /acquir|merger|takeover|buyout|\bstake in\b|deal to buy/], ['Regulatory change', /regulat|\brules?\b|\blaws?\b|\bbill\b|\bsec\b|\bbans?\b|\bbanned\b|licen[cs]e|reform|policy change/], ['Commodity supply disruption', /opec|output|supply|export ban|pipeline|refinery|strike|production cut|shipping|tanker|inventor/], ['Sovereign debt', /eurobond|sovereign|debt|imf|bond auction|treasury bills?|fiscal|budget deficit/], ['Market liquidity', /liquidity|repo|funding|outflow|redemption|margin call|volatility spike/]];
