const RAD = { at: 0, res: null };
const RAD_TOPIC = [['rates', 'Rates & bonds'], ['fx', 'Currencies'], ['equity', 'Equities'], ['credit', 'Credit'], ['commod', 'Commodities'], ['em', 'Emerging markets & Africa'], ['vol', 'Volatility'], ['ship', 'Shipping']];
const RAD_SEV = { low: [1, 'Low', 'up'], medium: [2, 'Medium', 'wn'], high: [3, 'High', 'dn'], critical: [4, 'Critical', 'dn'] };
function radIsRate(id) { return /^(YD|SP|MM)\./.test(id) || BY[id]?.type === 'yield'; }
function radUnit(id) { return radIsRate(id) ? 'bp' : id === 'IX.VIX' || id === 'IX.MOVE' ? 'pts' : '%'; }
function radTopic(id) { const o = BY[id] || {}; if (/^(YD|MM)\./.test(id)) return /US|DE|JP|GB/.test(id) ? 'rates' : 'em'; if (/^SP\./.test(id)) return 'credit'; if (/^FX\./.test(id)) return /NGN|ZAR|KES|EGP|GHS|CNH|INR|BRL|TRY/.test(id) ? 'em' : 'fx'; if (/^CM\.(BDIX|TD3C)/.test(id)) return 'ship'; if (/^CM\./.test(id)) return 'commod'; if (/VIX|MOVE|EVZ/.test(id)) return 'vol'; if (['NG', 'ZA', 'KE', 'EG', 'GH'].includes(o.country)) return 'em'; return 'equity'; }
/* real series only: feed closes, else data-desk points; never simulated */
