function radIds() { const s = new Set(); try { Object.keys(LIVE.real || {}).forEach(k => s.add(k)); } catch (e) { } try { Object.values(ADM.I || {}).forEach(x => x?.id && s.add(x.id)); } catch (e) { } return [...s].filter(id => BY[id] && BY[id].type !== 'econ'); }
function radChg(id, a, b) { if (a == null || b == null) return null; return radIsRate(id) ? (b - a) * 100 : a ? (b / a - 1) * 100 : null; }
