    if (n >= 40) { const c5 = []; for (let i = 5; i < n; i++) c5.push(radChg(id, s.c[i - 5], s.c[i])); const h5 = c5.slice(-121, -1).filter(x => x != null); const s5 = radStats(h5); const l5 = c5.at(-1); if (s5.sd > 0 && l5 != null) { const z = (l5 - s5.m) / s5.sd; if (Math.abs(z) >= 2.5 && !out.some(a => a.id === id && a.kind === 'Unusual one-day move' && Math.sign(a.z) === Math.sign(z))) out.push({ ...base, kind: 'Sharp 5-session move', z, chg: l5, sev: sevZ(z), why: `Over the last five observations it moved ${radFmt(l5, u)}, ${nf(Math.abs(z), 1)} standard deviations from its usual 5-session move.` }); } }
