    const lb = s.c.slice(-253, -1); if (lb.length >= 120) { const hi = Math.max(...lb), lo = Math.min(...lb); const per = lb.length >= 240 ? '52-week' : `${Math.round(lb.length / 21)}-month`; if (s.c.at(-1) > hi) out.push({ ...base, kind: `New ${per} high`, z: null, chg: last, sev: 'low', why: `It closed at ${nf(s.c.at(-1), 2)}, above the previous ${per} high of ${nf(hi, 2)}.` }); else if (s.c.at(-1) < lo) out.push({ ...base, kind: `New ${per} low`, z: null, chg: last, sev: 'low', why: `It closed at ${nf(s.c.at(-1), 2)}, below the previous ${per} low of ${nf(lo, 2)}.` }); }
    let k = 0; const sg = Math.sign(last || 0); for (let i = ch.length - 1; i >= 0 && sg && Math.sign(ch[i] || 0) === sg; i--) k++; if (k >= 7) out.push({ ...base, kind: `${k} moves in a row ${sg > 0 ? 'up' : 'down'}`, z: null, chg: radChg(id, s.c[n - 1 - k], s.c.at(-1)), sev: k >= 10 ? 'medium' : 'low', why: `It has ${sg > 0 ? 'risen' : 'fallen'} for ${k} consecutive observations.` });
