function radFollowed() { const s = new Set(); try { (S.watchlists || []).forEach(w => (w.items || []).forEach(i => s.add(i))); } catch (e) { } return s; }
function radRelevant(x, isPat) { const P = radPrefs(); if (RAD_SEV[x.sev]?.[0] < RAD_SEV[P.min][0]) return false; if (isPat) return x.topics.some(t => P.topics.includes(t)) || (P.wl && x.rows.some(r => r.met && radFollowed().has(r.id))); return P.topics.includes(x.topic) || (P.wl && radFollowed().has(x.id)); }
