  const ser = F.filter(x => x.series?.x?.length >= 3).slice(0, 2); ser.forEach(x => B.push({ k: 'chart', type: 'line', title: `${x.title} (${x.series.u || x.u})`, x: x.series.x, series: [{ name: x.title, data: x.series.y }], tag: 'kb', src: x.src ? [x.src] : null }));
