document.addEventListener('click', e => {
  const m = e.target.closest('[data-ptx]'); if (m) { const v = m.dataset.v; if (m.dataset.ptx === 'port') { PTM.sel = v; const el = $('#ptPan .pb'); if (el) { el.innerHTML = ptPanel(ptBy(v)); el.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); } else go('pprof', v); } else if (m.dataset.ptx === 'choke') { go('prisk'); } else if (m.dataset.ptx === 'fac') { PTF.sel = v; go('pref'); } return; }
  const a = e.target.closest('[data-ptask]'); if (a) { const p = ptBy(a.dataset.ptask); if (p) cpAsk(`Give me an intelligence briefing on ${p.name} (${p.country}): activity, throughput trend, ownership, risks and what to watch.`); }
});
document.addEventListener('change', e => { if (state.r !== 'pmap') return; const l = e.target.dataset.ptl; if (l) { e.target.checked ? PTM.layers.add(l) : PTM.layers.delete(l); render(); return; } if (e.target.id === 'ptCat') { PTM.cat = e.target.value; render(); } });
{ let tm = null; document.addEventListener('input', e => { if (e.target.id !== 'ptQ') return; clearTimeout(tm); tm = setTimeout(() => { PTM.q = e.target.value.slice(0, 40); const pos = e.target.selectionStart; render(); const i = $('#ptQ'); if (i) { i.focus(); try { i.setSelectionRange(pos, pos); } catch (er) { } } }, 350); }); }
document.addEventListener('click', e => { const r = e.target.closest('.cm-regs [data-reg]'); if (r && state.r === 'pmap') PTM.region = r.dataset.reg; }, true);
const PTF = { sel: null };
const ptNoBasis = fa => ({ ...fa, basis: '', why: '' });

const PT_CHOKE_STOP = new Set(['strait', 'straits', 'of', 'the', 'canal', 'and', 'sumed', 'el', 'cape', 'good', 'hope']);
function ptChokeSt(k) { if (typeof CMI_CHOKE === 'undefined') return null; const kw = ptNorm(k.name).split(' ').filter(w => w.length > 3 && !PT_CHOKE_STOP.has(w)); const kw2 = kw.length ? kw : ptNorm(k.name).split(' ').filter(w => w.length > 3); return Object.entries(CMI_CHOKE).find(([n]) => { const nn = ptNorm(n); return kw2.some(w => nn.split(' ').includes(w)); }) || null; }

