const PTE = { tab: 'comps', v: { teu0: 1.0, g: 6, yrs: 25, tariff: 140, opm: 55, capex: 900, build: 3, ramp: 4, mcap: 2.5, wacc: 11, debt: 60, rate: 9, tenor: 15, fee: 8, tax: 25, green: 1 }, w: { growth: 30, util: 25, priv: 15, risk: 20, inv: 10 } };
function ptConcession(v) { /* annual model in USD m; volumes in m TEU */ const Y = []; let teu = v.teu0; const capex = v.capex; const debt = capex * v.debt / 100; const r = v.rate / 100; const n = v.tenor; const pay = debt * r / (1 - Math.pow(1 + r, -n)); let bal = debt;
  for (let y = 1; y <= v.yrs; y++) { const build = v.green && y <= v.build; const rampF = v.green ? Math.min(1, Math.max(0, (y - v.build) / Math.max(1, v.ramp))) : 1; if (!build && y > 1) teu *= 1 + v.g / 100; const vol = build ? 0 : Math.min(teu * rampF, v.mcap); const rev = vol * v.tariff; const opex = rev * (1 - v.opm / 100); const fee = rev * v.fee / 100; const ebitda = rev - opex - fee; const cx = v.green ? (build ? capex / v.build : capex * .015) : (y === 1 ? capex : capex * .02); const intr = bal * r; const tax = Math.max(0, (ebitda - intr - capex / v.yrs) * v.tax / 100); const ds = y > (v.green ? v.build : 0) && y <= (v.green ? v.build : 0) + n ? pay : 0; if (ds) bal = bal * (1 + r) - pay; const fcf = ebitda - tax - cx; const cfads = ebitda - tax - (v.green && build ? 0 : cx * (build ? 1 : 0)); Y.push({ y, vol, rev, ebitda, fee, cx, tax, fcf, ds, dscr: ds ? (ebitda - tax) / ds : null }); }
  const npv = Y.reduce((s, x) => s + x.fcf / Math.pow(1 + v.wacc / 100, x.y), 0); const irr = (() => { let lo = -0.9, hi = 1; const f = k => Y.reduce((s, x) => s + x.fcf / Math.pow(1 + k, x.y), 0); if (f(lo) * f(hi) > 0) return null; for (let i = 0; i < 80; i++) { const m = (lo + hi) / 2; if (f(m) > 0) lo = m; else hi = m; } return (lo + hi) / 2 * 100; })(); const ds = Y.filter(x => x.dscr != null); return { Y, npv, irr, minDscr: ds.length ? Math.min(...ds.map(x => x.dscr)) : null, avgDscr: ds.length ? ds.reduce((s, x) => s + x.dscr, 0) / ds.length : null, debt }; }
function ptAfricaScore() { const W = PTE.w; const A = PTD.ports.filter(p => p.region === 'Africa'); const rows = A.map(p => { const g = ptCagr(p.throughput) ?? ptCagr(p.teu); const u = ptUtil(p)?.v; const priv = (p.terminals || []).some(t => (t.owners || []).some(o => !/authority|government|state|ports authority|ministry|npa|gpha|transnet|kpa|tpa/i.test(o.name))) ? 1 : 0; const dis = (p.disruptions || []).filter(d => String(d.date) >= '2019').length + (PTD.events || []).filter(e => (e.port_ids || []).includes(p.id) && String(e.date) >= '2019').length; const inv = (p.investment || []).length; return { p, g, u, priv, dis, inv }; });
  const nz = (vals, v, inv) => { const xs = vals.filter(x => x != null); if (v == null || !xs.length) return null; const lo = Math.min(...xs), hi = Math.max(...xs); const s = hi > lo ? (v - lo) / (hi - lo) : .5; return inv ? 1 - s : s; };
  return rows.map(r => { const parts = { growth: nz(rows.map(x => x.g), r.g), util: nz(rows.map(x => x.u), r.u), priv: r.priv, risk: nz(rows.map(x => x.dis), r.dis, true), inv: nz(rows.map(x => x.inv), r.inv) }; let s = 0, w = 0; Object.entries(parts).forEach(([k, v]) => { if (v != null) { s += v * W[k]; w += W[k]; } }); return { ...r, parts, score: w ? s / w * 100 : null, cover: Object.values(parts).filter(v => v != null).length }; }).sort((a, b) => (b.score ?? -1) - (a.score ?? -1)); }
