/* ---------- AI port intelligence (rule-based insights with evidence) ---------- */
function ptInsights() {
  const out = []; const on = ptPWOn();
  if (on) PTD.ports.forEach(p => { const x = ptPW(p); if (!x) return; const c = ptPWStats(x, 'c_ct'), a = ptPWStats(x, 'calls'), tk = ptPWStats(x, 'exp_tk'), db = ptPWStats(x, 'c_db');
    if (c && c.vsPrev != null && c.vsPrev > 20 && c.d30 > 3) out.push({ k: 'A', t: 'Unusual port activity', p, d: c.last, text: `Container vessel arrivals at ${p.name} rose ${pc(c.vsPrev, 0)} versus the previous 30 days${c.vsBase != null ? ` and are ${pc(c.vsBase, 0)} versus the same period in earlier years` : ''}.`, ev: `IMF PortWatch: ${ptFmt(c.d30)} container calls a day (30d) vs ${ptFmt(c.p30)} (prior 30d).`, conf: c.yrs >= 2 ? 'medium' : 'low', tag: 'real' });
    if (tk && tk.vsBase != null && tk.vsBase < -25 && p.cats.some(k => ['crude', 'lng_exp', 'products'].includes(k))) out.push({ k: 'B', t: 'Export slowdown', p, d: tk.last, text: `Estimated tanker exports from ${p.name} are ${pc(tk.vsBase, 0)} below their seasonal baseline. Possible explanations include loading delays, maintenance, quota changes or reduced exports.`, ev: `IMF PortWatch: tanker exports ${nf(tk.d30, 0)} t/day (30d) vs ${nf(tk.base, 0)} t/day baseline (${tk.yrs} yrs).`, conf: tk.yrs >= 2 ? 'medium' : 'low', tag: 'real' });
    if (db && db.vsBase != null && db.vsBase < -25 && p.cats.some(k => ['iron_ore', 'coal'].includes(k))) out.push({ k: 'C', t: 'Commodity supply disruption risk', p, d: db.last, text: `Dry bulk calls at ${p.name} are ${pc(db.vsBase, 0)} below normal. If sustained, deliveries to downstream steel or power producers could be delayed. Waiting-time data needs the live AIS feed to confirm.`, ev: `IMF PortWatch dry bulk calls: ${ptFmt(db.d30)}/day vs ${ptFmt(db.base)}/day baseline.`, conf: 'low', tag: 'real' }); });
  PTD.ports.forEach(p => { const ev = ptAllEvents().filter(e => (e.port_ids || []).includes(p.id)); const w = ev.filter(e => e.type === 'weather').length; if (w >= 2) out.push({ k: 'D', t: 'Infrastructure risk', p, d: null, text: `${p.name} has ${w} recorded weather disruptions${ev.length > w ? ` and ${ev.length - w} other disruptions` : ''}. ${(p.dependency || []).length ? 'It is also a concentration point: ' + p.dependency[0].text + '.' : 'Check how many alternative routes exist before relying on it.'}`, ev: ev.filter(e => e.type === 'weather').slice(0, 3).map(e => `${e.date}: ${e.title}`).join('; '), conf: 'medium', tag: 'kb' });
    const g = ptCagr(p.throughput) ?? ptCagr(p.teu), u = ptUtil(p); if (g != null && g > 3 && u && u.v > 80) out.push({ k: 'E', t: 'Investment intelligence', p, d: null, text: `${p.name} throughput has grown ${pc(g, 1)} a year over five years and is at about ${ptFmt(u.v, 0)}% of stated capacity. Additional terminal capacity may be needed.`, ev: `${u.basis}; growth from ${(p.throughput?.series || p.teu?.series)[0][0]}–${ptLast(p.throughput || p.teu)[0]} official figures.`, conf: 'medium', tag: 'calc' }); });
  return out;
}
