        <div class="vx-mix\" role="img" aria-label="Listed registry by asset class">${mix.map(([l, v], i) => `<i class="${i === 0 ? 'b' : ''}" style="flex:${v};${i ? `opacity:${1 - i * .13}` : ''}"></i>`).join('')}</div>
