  const upd = () => { const rows = $$('[data-seat]', L).map(i => { const k = i.dataset.seat; const v = Math.max(0, Math.min(999, Math.round(+i.value || 0))); return [k, v, v * PLANS[k].price]; }); const m = rows.reduce((a, r) => a + r[2], 0), n = rows.reduce((a, r) => a + r[1], 0);
    out.innerHTML = `<div class="vx-calc-big"><span>Per month</span><b>$${nf(m, 0)}</b></div><div class="vx-calc-r"><span>Per year</span><b>$${nf(m * 12, 0)}</b></div><div class="vx-calc-r"><span>Seats</span><b>${n}</b></div><div class="vx-calc-r"><span>Average per seat</span><b>${n ? '$' + nf(m / n, 2) : '—'}</b></div>${rows.filter(r => r[1]).map(([k, v, c]) => `<div class="vx-calc-r vx-calc-s"><span>${v} × ${esc(PLANS[k].short)} at $${PLANS[k].price}</span><b>$${nf(c, 0)}</b></div>`).join('')}`; };
